function applyBoxContext(){const context=state.boxContext;if(!context)return;const workbench=context.product?.workbench||{},isGame=workbench.profile==='game_studio',homeView=isGame?'agent':'box-home',workbenchNav=document.querySelector('[data-module="workbench"]');MODULES.workbench.title=isGame?'财务目标组合':'Box 概览';MODULES.workbench.views=[[homeView,'工作台']];if(workbenchNav)workbenchNav.dataset.view=homeView;document.querySelector('.brand small').textContent=workbench.label||'OPC Finance Box';document.title=`${context.product?.name||'OPC Finance Box'} · 财务工作台`;['confirmations','analysis','settings'].forEach(module=>{const item=document.querySelector(`[data-module="${module}"]`);if(item)item.hidden=!isGame});['sample-scenario','sample-download','run-agent-button'].forEach(id=>{const item=el(id);if(item)item.hidden=!isGame});updateCompanyContext(state.companyProfile)}
