function boxBuilderStarter(){const profile=boxBuilderProfile(),jurisdiction=boxBuilderJurisdiction();return state.boxBuilderOptions?.starter_catalog?.entries?.find(item=>item.profile_id===profile?.id&&item.jurisdiction_id===jurisdiction?.id)}
function boxBuilderJurisdictionById(id){return state.boxBuilderOptions?.jurisdictions?.find(item=>item.id===id)}
function boxBuilderPresetMap(){return new Map((state.boxBuilderOptions?.integration_presets||[]).map(item=>[item.id,item]))}
function boxBuilderAllowedPresetIds(){const profile=boxBuilderProfile(),presets=boxBuilderPresetMap();return(profile?.allowed_integrations||[]).filter(id=>presets.has(id))}
function boxBuilderIntegrationOptions(selected=''){const presets=boxBuilderPresetMap(),single=new Set(state.boxBuilderOptions?.connector_binding_policy?.single_credential_connector_packs||[]);return'<option value="">仅文件导入 · 绑定该主体</option>'+boxBuilderAllowedPresetIds().map(id=>{const preset=presets.get(id),limited=(preset.connectors||[]).some(connector=>single.has(connector));return`<option value="${safe(id)}" ${id===selected?'selected':''}>${safe(preset.display_name)}${limited?' · 单凭证主体':''}</option>`}).join('')}
function boxBuilderEntityIntegrationDrafts(){return[{id:el('box-builder-entity-id').value.trim(),integration:el('box-builder-integration').value},...state.boxBuilderAdditionalEntities.map(item=>({id:item.id,integration:item.integration||''}))]}
function boxBuilderConnectorBindingDraft(drafts=boxBuilderEntityIntegrationDrafts()){const presets=boxBuilderPresetMap(),entityIds=drafts.map(item=>item.id).filter(Boolean),scopes=new Map([['connector.file_import',new Set(entityIds)]]),unknown=[];drafts.forEach(item=>{if(!item.integration)return;const preset=presets.get(item.integration);if(!preset){unknown.push(item.integration);return}(preset.connectors||[]).forEach(connector=>{if(!scopes.has(connector))scopes.set(connector,new Set());if(item.id)scopes.get(connector).add(item.id)})});const single=new Set(state.boxBuilderOptions?.connector_binding_policy?.single_credential_connector_packs||[]),bindings=[...scopes].map(([connector_pack,ids])=>({connector_pack,entity_ids:[...ids].sort()})).sort((a,b)=>a.connector_pack.localeCompare(b.connector_pack)),conflicts=bindings.filter(item=>single.has(item.connector_pack)&&item.entity_ids.length!==1).map(item=>item.connector_pack);return{bindings,conflicts,unknown}}
function renderBoxBuilderBindingDraft(){const container=el('box-builder-binding-draft');if(!container)return;const {bindings,conflicts}=boxBuilderConnectorBindingDraft(),drafts=boxBuilderEntityIntegrationDrafts(),assigned=drafts.filter(item=>item.integration&&item.id);container.className=`box-builder-binding-draft wide${conflicts.length?' conflict':''}`;container.innerHTML=`<strong>数据源主体范围 · ${bindings.length} 个 Connector Pack</strong><span>${bindings.map(item=>`${safe(item.connector_pack)} → ${item.entity_ids.map(safe).join('、')||'待补主体 ID'}`).join('<br>')}</span><small>${conflicts.length?`冲突：${conflicts.map(safe).join('、')} 当前每个运行凭证只能绑定一个主体，请调整主体数据源。`:'生成候选时会写入完整 connector_bindings；错绑主体会在调用 provider 前被拒绝。'}${assigned.length?` · ${assigned.length} 个主体数据源预设`:''}</small>`}
