function addBoxBuilderEntity(){const used=new Set([boxBuilderJurisdiction()?.id,...state.boxBuilderAdditionalEntities.map(item=>item.tax_pack)]),jurisdiction=(state.boxBuilderOptions?.jurisdictions||[]).find(item=>!used.has(item.id))||state.boxBuilderOptions?.jurisdictions?.[0];if(!jurisdiction)return toast('没有可用的纳税地区 Pack');state.boxBuilderAdditionalEntities.push(newBoxBuilderEntity(jurisdiction,state.boxBuilderAdditionalEntities.length));renderAdditionalBoxBuilderEntities();markBoxBuilderChanged()}
function syncBoxBuilderInputs(resetEntity=false){const profile=boxBuilderProfile(),jurisdiction=boxBuilderJurisdiction();if(!profile||!jurisdiction)return;const integration=el('box-builder-integration'),current=integration.value,allowed=new Set(boxBuilderAllowedPresetIds());integration.innerHTML=boxBuilderIntegrationOptions(current);integration.value=allowed.has(current)?current:'';state.boxBuilderAdditionalEntities.forEach(entity=>{if(!allowed.has(entity.integration))entity.integration=''});if(resetEntity){const starter=boxBuilderStarter()?.starter_spec,starterEntity=starter?.entities?.[0];el('box-builder-entity-id').value=starterEntity?.id||`${jurisdiction.country_code.toLowerCase()}_${profile.id}_company`;el('box-builder-entity-name').value=starterEntity?.name||`${jurisdiction.country_code} ${profile.display_name} 经营主体（待确认）`;el('box-builder-currency').value=starterEntity?.functional_currency||jurisdiction.starter?.functional_currency||'';el('box-builder-accounting-basis').value=starterEntity?.accounting_basis||jurisdiction.starter?.accounting_basis||'';el('box-builder-fiscal-year-end').value=starterEntity?.fiscal_year_end||jurisdiction.starter?.fiscal_year_end||'12-31'}const starterStatus=boxBuilderStarter()?.contract_checked?'Starter 契约已校验':'需要手动补全 Starter';el('box-builder-jurisdiction-note').innerHTML=`<strong>${safe(jurisdiction.display_name)}</strong><span>Tax Pack ${safe(jurisdiction.id)} · ${safe(jurisdiction.status)} · 成熟度 ${safe(jurisdiction.tax_readiness)} · ${safe(starterStatus)} · 规则生效 ${safe(jurisdiction.rules_effective_at)}</span><small>币种与准则是可编辑起点；税务登记保持空白，必须按真实主体确认。</small>`;renderAdditionalBoxBuilderEntities();markBoxBuilderChanged()}
function renderBoxBuilderOptions(){const options=state.boxBuilderOptions;if(!options)return;const profileSelect=el('box-builder-profile'),jurisdictionSelect=el('box-builder-jurisdiction'),profileCurrent=profileSelect.value||'dtc',jurisdictionCurrent=jurisdictionSelect.value;profileSelect.innerHTML=options.profiles.map(item=>`<option value="${safe(item.id)}">${safe(item.display_name)} · ${safe(item.description)}</option>`).join('');profileSelect.value=options.profiles.some(item=>item.id===profileCurrent)?profileCurrent:options.profiles[0]?.id||'';jurisdictionSelect.innerHTML=options.jurisdictions.map(item=>`<option value="${safe(item.id)}">${safe(item.country_code)} · ${safe(item.display_name)} · ${safe(item.tax_readiness)}</option>`).join('');jurisdictionSelect.value=options.jurisdictions.some(item=>item.id===jurisdictionCurrent)?jurisdictionCurrent:options.jurisdictions[0]?.id||'';const catalog=options.starter_catalog;if(el('box-builder-catalog-summary'))el('box-builder-catalog-summary').textContent=catalog?.complete?`${catalog.ready_combination_count} 个 Pack 契约已验证组合`:`${catalog?.ready_combination_count||0}/${catalog?.eligible_combination_count||0} 个 Starter 可用`;syncBoxBuilderInputs(true)}
async function loadBoxBuilder(force=false){if(state.boxBuilderBusy)return;if(state.boxBuilderOptions&&!force)return renderBoxBuilderOptions();state.boxBuilderBusy=true;el('box-builder-state').textContent='读取 Pack';try{state.boxBuilderOptions=await pipelineJson('/api/box-builder/options');renderBoxBuilderOptions()}catch(error){toast(error.message||'Box Builder 选项读取失败');el('box-builder-state').textContent='读取失败';el('box-builder-state').className='status error'}finally{state.boxBuilderBusy=false}}
function validateBoxBuilderEntity(entity){if(!entity.name?.trim()){toast('请填写每个法律主体名称');return false}if(!/^[a-z][a-z0-9_-]*$/.test(entity.id||'')){toast(`主体 ID ${entity.id||'（空）'} 格式无效`);return false}if(!/^[A-Z]{3}$/.test((entity.functional_currency||'').toUpperCase())){toast(`主体 ${entity.id} 的本位币必须是 3 位代码`);return false}if(!entity.accounting_basis?.trim()){toast(`请填写主体 ${entity.id} 的会计准则`);return false}if(!/^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$/.test(entity.fiscal_year_end||'')){toast(`主体 ${entity.id} 的财年结束需使用 MM-DD`);return false}return true}
function buildBoxBuilderSpec(){const profile=boxBuilderProfile(),jurisdiction=boxBuilderJurisdiction(),name=el('box-builder-name').value.trim(),currency=el('box-builder-currency').value.trim().toUpperCase(),primaryIntegration=el('box-builder-integration').value;if(!profile||!jurisdiction)return toast('请选择业务样板和纳税地区');if(!name)return toast('请填写 Box 名称');const primary={id:el('box-builder-entity-id').value.trim(),name:el('box-builder-entity-name').value.trim(),tax_country:jurisdiction.country_code,tax_pack:jurisdiction.id,functional_currency:currency,accounting_basis:el('box-builder-accounting-basis').value.trim(),fiscal_year_end:el('box-builder-fiscal-year-end').value.trim(),tax_registrations:[]},additional=state.boxBuilderAdditionalEntities.map(item=>({id:item.id,name:item.name,tax_country:item.tax_country,tax_pack:item.tax_pack,functional_currency:item.functional_currency.toUpperCase(),accounting_basis:item.accounting_basis,fiscal_year_end:item.fiscal_year_end,tax_registrations:[]})),entities=[primary,...additional];if(!entities.every(validateBoxBuilderEntity))return;const ids=entities.map(item=>item.id);if(new Set(ids).size!==ids.length)return toast('法律主体 ID 不能重复');const drafts=[{id:primary.id,integration:primaryIntegration},...state.boxBuilderAdditionalEntities.map(item=>({id:item.id,integration:item.integration||''}))],bindingDraft=boxBuilderConnectorBindingDraft(drafts);if(bindingDraft.unknown.length)return toast(`存在已卸载或不受当前业务支持的数据源预设：${bindingDraft.unknown.join('、')}`);if(bindingDraft.conflicts.length)return toast(`${bindingDraft.conflicts.join('、')} 当前每个运行凭证只能绑定一个主体，请调整逐主体数据源`);const integrations=[...new Set(drafts.map(item=>item.integration).filter(Boolean))];return{name,business_type:profile.business_type,channels:profile.channels,integrations,data_mode:el('box-builder-data-mode').value,reporting_currency:currency,entities,connector_bindings:bindingDraft.bindings}}
function boxBuilderShellQuote(value){const text=String(value);return/^[A-Za-z0-9_./:=+-]+$/.test(text)?text:`'${text.replaceAll("'","'\\''")}'`}
function buildBoxBuilderCliCommand(spec){const profile=boxBuilderProfile()?.id||'',drafts=boxBuilderEntityIntegrationDrafts();if(spec.entities.length===1){const entity=spec.entities[0],args=['opc-finance-box','starter-init','/absolute/new/opc-finance-box','--profile',profile,'--country',entity.tax_country,'--entity-id',entity.id,'--entity-name',entity.name,'--name',spec.name,'--data-mode',spec.data_mode,...(drafts[0]?.integration?['--integration',drafts[0].integration]:[]),'--actor','RECIPIENT'];return args.map(boxBuilderShellQuote).join(' \\\n  ')}const args=['opc-finance-box','starter-compose','/absolute/new/opc-finance-box','--profile',profile];spec.entities.forEach(entity=>args.push('--entity',`${entity.tax_country}=${entity.id}`,'--entity-name',`${entity.id}=${entity.name}`));drafts.filter(item=>item.integration).forEach(item=>args.push('--entity-integration',`${item.id}=${item.integration}`));args.push('--reporting-currency',spec.reporting_currency,'--name',spec.name,'--data-mode',spec.data_mode,'--actor','RECIPIENT');return args.map(boxBuilderShellQuote).join(' \\\n  ')}
