function setView(view){state.view=view;state.module=moduleForView(view);document.body.dataset.view=view;document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${view}`));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.module===state.module));el('page-title').textContent=MODULES[state.module].title;renderModuleTabs();const notice=el('notice');if(notice)notice.style.display=view==='overview'?'flex':'none';if(view==='agent')loadAgentWorkspace();if(view==='box-builder')loadBoxBuilder();if(view==='tax-workspace')loadTaxWorkspace();if(view==='confirmations'){if(state.agentWorkspace)renderConfirmations();else loadAgentWorkspace()}if(view==='pipeline-launch')loadPipelineLaunch();if(view==='connector-onboarding')loadConnectorReadiness();if(view==='pipeline-control')loadPipelineControl();if(view==='documents')loadDocuments();if(view==='records')renderRecords();if(view==='exceptions')renderExceptions();if(view==='sources')renderSources();if(view==='templates')loadTemplates();if(view==='revenue-close')loadRevenueClose();if(view==='procurement')loadProcurementWorkflow();if(view==='flows'&&state.payload)loadBusinessFlows();if(view==='banking')renderBanking();if(view==='invoices')renderInvoices();if(view==='payroll')renderPayroll();if(view==='planning')loadPlanning();if(view==='settings')loadCompanyProfile();if(view==='review')loadAudit();if(view==='bp')loadBp();if(view==='qa')renderQa();if(view==='onboarding')loadOnboarding();if(view==='shadow-close')loadShadowClose();if(['close','vouchers','ledger','tax','review'].includes(view))ensureFinanceOps()}
function records(){return state.payload?.records||[]}
function currencyRecords(){return records().filter(r=>!state.currency||r.currency===state.currency)}
function aggregate(items){return items.reduce((a,r)=>{a.gross+=r.gross||0;a.refunds+=r.refunds||0;a.shareBase+=r.share_base||0;a.settlement+=r.settlement_amount||0;a.tax+=r.withholding_tax||0;a.net+=r.net_receivable||0;return a},{gross:0,refunds:0,shareBase:0,settlement:0,tax:0,net:0})}
function render(){if(!state.payload)return;const currencies=Object.keys(state.payload.summary.currencies);if(!state.currency||!currencies.includes(state.currency))state.currency=currencies[0]||'';el('currency-tabs').innerHTML=currencies.map(c=>`<button class="segment ${c===state.currency?'active':''}" data-currency="${c}">${c}</button>`).join('');el('currency-tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.currency=b.dataset.currency;render()});const items=currencyRecords(),a=aggregate(items),fees=Math.max(0,a.gross-a.refunds-a.shareBase);const metrics=[['含税/平台流水',fmt(a.gross,state.currency),'原始平台或渠道口径'],['退款与坏账',fmt(a.refunds,state.currency),a.gross?`流水占比 ${(a.refunds/a.gross*100).toFixed(2)}%`:'无流水'],['结算金额',fmt(a.settlement,state.currency),`${items.length} 条标准记录`],['预计实收',fmt(a.net,state.currency),a.tax?`代扣税 ${fmt(a.tax,state.currency)}`:'暂无代扣税']];el('metric-cards').innerHTML=metrics.map(m=>`<div class="metric"><div class="label">${m[0]}</div><div class="value">${m[1]}</div><div class="foot">${m[2]}</div></div>`).join('');renderTrend(items);renderWaterfall(a,fees);el('overview-table').innerHTML=items.slice().sort((x,y)=>y.period.localeCompare(x.period)).slice(0,8).map(rowHtml).join('');el('source-status').textContent=`已解析 ${state.payload.summary.file_count} 份文件 · ${state.payload.summary.record_count} 条记录`;el('exception-count').textContent=state.payload.summary.exception_count;el('pending-count').textContent=state.payload.summary.pending_count;renderRecordFilters();if(state.view==='records')renderRecords();if(state.view==='exceptions')renderExceptions();if(state.view==='sources')renderSources()}
function rowHtml(r){return `<tr><td>${r.period}</td><td><strong>${r.game}</strong><br><small>${r.platform} · ${r.channel}</small></td><td>${r.currency||'待确认'}</td><td class="numeric">${fmt(r.gross,r.currency)}</td><td class="numeric">${fmt(r.refunds,r.currency)}</td><td class="numeric">${fmt(r.settlement_amount,r.currency)}</td><td class="numeric">${fmt(r.net_receivable,r.currency)}</td><td><span class="status ${statusClass(r.status)}">${r.status}</span></td></tr>`}
function renderTrend(items){const grouped={};items.forEach(r=>{const x=grouped[r.period]||(grouped[r.period]={settlement:0,net:0});x.settlement+=r.settlement_amount||0;x.net+=r.net_receivable||0});const entries=Object.entries(grouped).sort();const max=Math.max(1,...entries.flatMap(([,v])=>[v.settlement,v.net]));el('trend-chart').innerHTML=entries.map(([p,v])=>`<div class="bar-group"><div class="bar-value">${fmt(v.settlement,state.currency,true)}</div><div class="bars"><span class="bar settlement" title="${fmt(v.settlement,state.currency)}" style="height:${v.settlement/max*175}px"></span><span class="bar net" title="${fmt(v.net,state.currency)}" style="height:${v.net/max*175}px"></span></div><label>${p}</label></div>`).join('')||'<p>暂无趋势数据</p>'}
function renderWaterfall(a,fees){const rows=[['平台/渠道流水',a.gross,'base'],['退款与坏账',a.refunds,'refund'],['税费及渠道成本',fees,'tax'],['分成基数',a.shareBase,'base'],['结算金额',a.settlement,'base'],['预计实收',a.net,'net']],max=Math.max(1,...rows.map(r=>r[1]));el('waterfall').innerHTML=rows.map(r=>`<div class="water-row"><div class="water-label"><span>${r[0]}</span><strong>${fmt(r[1],state.currency)}</strong></div><div class="track"><div class="fill ${r[2]}" style="width:${Math.max(2,r[1]/max*100)}%"></div></div></div>`).join('')}
function renderRecordFilters(){const select=el('record-currency');if(!select)return;const currencies=Object.keys(state.payload.summary.currencies);const current=select.value;select.innerHTML='<option value="">全部币种</option>'+currencies.map(c=>`<option>${c}</option>`).join('');select.value=current}
function filteredRecords(){const q=(el('record-search')?.value||'').toLowerCase(),c=el('record-currency')?.value||'',s=el('record-status')?.value||'';return records().filter(r=>(!q||[r.game,r.channel,r.platform,r.period,r.source_file].join(' ').toLowerCase().includes(q))&&(!c||r.currency===c)&&(!s||r.status===s))}
function renderRecords(){el('records-table').innerHTML=filteredRecords().map(r=>`<tr><td>${r.period}</td><td>${r.scope}</td><td>${r.game}</td><td>${r.platform}<br><small>${r.channel}</small></td><td>${r.currency||'—'}</td><td class="numeric">${fmt(r.gross,r.currency)}</td><td class="numeric">${fmt(r.share_base,r.currency)}</td><td class="numeric">${pct(r.share_rate)}</td><td class="numeric">${fmt(r.settlement_amount,r.currency)}</td><td class="numeric">${fmt(r.withholding_tax,r.currency)}</td><td class="numeric">${fmt(r.net_receivable,r.currency)}</td><td><span class="status ${statusClass(r.status)}">${r.status}</span></td><td title="${r.source_file}">${r.source_sheet} · ${r.evidence.row}行</td></tr>`).join('')||'<tr><td colspan="13">没有符合条件的记录</td></tr>'}
function renderExceptions(){const items=records().filter(r=>r.status!=='已核对');el('exception-list').innerHTML=items.map(r=>`<div class="exception-item ${r.status==='异常'?'error':''}"><div><h3>${r.game} · ${r.period} · ${r.channel}</h3><span class="status ${statusClass(r.status)}">${r.status}</span></div><strong>${fmt(r.settlement_amount,r.currency)}</strong><p>${r.anomalies.length?r.anomalies.join('；'):'关键字段或口径尚未达到自动核对阈值'} · 来源：${r.source_file} / ${r.source_sheet} 第${r.evidence.row}行</p></div>`).join('')||'<article class="panel"><div class="panel-head"><h2>当前记录均已通过自动勾稽</h2></div></article>'}
function renderSources(){const groups={};records().forEach(r=>{const g=groups[r.source_file]||(groups[r.source_file]={sheets:new Set(),count:0,status:0});g.sheets.add(r.source_sheet);g.count++;if(r.status!=='已核对')g.status++});el('source-list').innerHTML=Object.entries(groups).map(([file,g])=>`<div class="source-item"><span class="file-icon">XLSX</span><div><strong>${file}</strong><small>${[...g.sheets].join('、')} · ${g.count}条标准记录</small></div><span class="status ${g.status?'pending':'ok'}">${g.status?`${g.status}项待处理`:'解析完成'}</span></div>`).join('')}
function availablePeriods(){return [...new Set(records().map(r=>r.period).filter(Boolean))].sort().reverse()}
async function ensureFinanceOps(force=false){const periods=availablePeriods(),select=el('ops-period');if(!state.opsPeriod)state.opsPeriod=periods[0]||new Date().toISOString().slice(0,7);if(select){select.innerHTML=periods.map(p=>`<option>${p}</option>`).join('');select.value=state.opsPeriod}if(state.financeOps&&!force){renderFinanceOps();return}if(force)state.taxFilingAssist=null;try{if(!state.companyProfile){const pr=await fetch('/api/company-profile'),pd=await pr.json();state.companyProfile=pd.profile;state.profileGaps=pd.gaps||[]}const r=await fetch('/api/finance-ops',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({period:state.opsPeriod,records:records(),purchases:state.procurement?.records||[],bank_transactions:state.banking?.transactions||[],invoices:state.invoices?.records||[],payroll_rows:state.payroll?.records||[],opening_balances:state.openingBalances||[],company_profile:state.companyProfile||{}})}),data=await r.json();if(!r.ok)throw new Error(data.error);state.financeOps=data;state.taxFilingAssist=data.tax_pack?.filing_assist||null;renderFinanceOps()}catch(e){toast(e.message||'月结数据生成失败')}}
function renderFinanceOps(){if(!state.financeOps)return;renderClose();renderVouchers();renderReview();renderLedger();renderTax();if(state.view==='tax'&&state.hasPersistentData)loadTaxFilingAssist()}
function statusTone(s){return s==='已完成'?'ok':s==='阻塞'?'error':'pending'}
function decisionHtml(d){if(!d)return'';return`<div class="decision-card"><h4>给业务同学的解释</h4><p>${d.plain_language}</p><p class="recommendation">Agent 建议：${d.recommendation} · 置信度 ${Math.round((d.confidence||0)*100)}%</p>${d.business_questions?.length?`<p>你只需确认：${d.business_questions.join('；')}</p>`:''}<div class="option-grid">${(d.options||[]).map(o=>`<div class="option ${o.recommended?'recommended':''}"><strong>${o.recommended?'推荐 · ':''}${o.name}</strong><span>好处：${o.benefit}</span><span>代价：${o.cost}</span></div>`).join('')}</div></div>`}
function renderClose(){const c=state.financeOps.close,periodState=state.periodStates[state.financeOps.period]||{};el('close-progress-text').textContent=`${state.financeOps.period} · ${periodState.status||'开放'} · 已完成 ${c.completed}/${c.total} · ${c.blocked} 项阻塞`;el('close-metrics').innerHTML=[['月结进度',`${Math.round(c.progress*100)}%`,'目标 D+7'],['已完成',c.completed,'可自动或已有证据'],['阻塞事项',c.blocked,'需要补数据或确认'],['凭证草稿',state.financeOps.vouchers.length,'接受后才能关账']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');el('module-map').innerHTML=state.financeOps.system_modules.map(m=>`<div class="module-item"><div class="module-item-head"><strong>${m.name}</strong><span>${m.coverage}%</span></div><div class="track"><div class="fill" style="width:${m.coverage}%"></div></div><small>${m.status}</small></div>`).join('');el('close-task-list').innerHTML=c.tasks.map(t=>`<div class="close-task"><span class="task-id">${t.id}</span><div><h3>${t.name}</h3><p>${t.blockers.join('；')||'资料与勾稽已满足当前规则'}</p>${t.decision_support?'<button class="decision-link">查看 Agent 判断与选择利弊 ↓</button>':''}</div><span class="task-owner">${t.owner}</span><span class="task-deadline">${t.deadline}</span><span class="status ${statusTone(t.status)}">${t.status}</span>${decisionHtml(t.decision_support)}</div>`).join('');el('close-task-list').querySelectorAll('.decision-link').forEach(b=>b.onclick=()=>b.closest('.close-task').classList.toggle('open'))}
function moneyOrPending(v){return v==null?'待折算':new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(v)}
function renderVouchers(){const vouchers=state.financeOps.vouchers,reviews=(state.periodStates[state.financeOps.period]||{}).voucher_reviews||{};el('voucher-list').innerHTML=vouchers.length?vouchers.map(v=>{const review=reviews[v.id];return`<article class="voucher-card"><div class="voucher-head"><div><h3>${v.id} · ${v.summary}</h3><p>${v.date} · 来源 ${v.source}（${v.source_count}条）· 原币 ${v.original_currency} ${moneyOrPending(v.original_amount)}</p></div><span class="status ${review?.decision==='接受'?'ok':review?.decision==='退回'?'error':statusTone(v.status)}">${review?.decision||v.status}</span></div><div class="entry-grid"><div class="entry-side"><strong>借方</strong>${v.debit.map(x=>`<div class="entry-line"><span>${x.account}<br><small>${x.dimension}</small></span><strong>${moneyOrPending(x.amount)}</strong></div>`).join('')}</div><div class="entry-side"><strong>贷方</strong>${v.credit.map(x=>`<div class="entry-line"><span>${x.account}<br><small>${x.dimension}</small></span><strong>${moneyOrPending(x.amount)}</strong></div>`).join('')}</div></div><div class="blocker-list">${v.blockers.join('；')}</div><div class="judgement"><strong>Agent 判断倾向</strong><p>${v.judgement.agent_recommendation}</p><p>为什么要确认：${v.judgement.question}</p><p>影响：${v.judgement.impact}</p><p>需要证据：${v.evidence.join('、')} · 最终复核：${v.review_role}</p></div><div class="voucher-actions"><input aria-label="复核说明" data-rationale="${v.id}" placeholder="可选：填写接受/退回原因" value="${review?.rationale||''}"/><button class="button primary" data-review="接受" data-voucher="${v.id}" ${v.status==='阻塞'?'disabled':''}>接受草稿</button><button class="button ghost" data-review="退回" data-voucher="${v.id}">退回补证据</button></div></article>`}).join(''):'<div class="empty-state">本期没有可生成凭证的结算记录。</div>';el('voucher-list').querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>reviewVoucher(b.dataset.voucher,b.dataset.review))}

async function reviewVoucher(voucherId,decision){const input=document.querySelector(`[data-rationale="${voucherId}"]`);try{const r=await fetch('/api/voucher-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({period:state.opsPeriod,voucher_id:voucherId,decision,rationale:input?.value||'',actor:'财务工作台用户'})}),data=await r.json();if(!r.ok)throw new Error(data.error);state.periodStates[state.opsPeriod]=data.period_state;renderVouchers();renderReview();toast(`${voucherId} 已${decision}并留下审计记录`)}catch(e){toast(e.message||'凭证复核失败')}}

function renderReview(){if(!state.financeOps)return;const periodState=state.periodStates[state.financeOps.period]||{},reviews=Object.values(periodState.voucher_reviews||{}),accepted=reviews.filter(x=>x.decision==='接受').length,returned=reviews.filter(x=>x.decision==='退回').length;el('review-metrics').innerHTML=[['期间状态',periodState.status||'开放',state.financeOps.period],['已接受',accepted,'可进入关账检查'],['已退回',returned,'需补业务证据'],['操作日志',state.auditEvents.length,'最近200条']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');el('review-list').innerHTML=reviews.length?reviews.map(x=>`<div class="audit-item"><span class="status ${x.decision==='接受'?'ok':'error'}">${x.decision}</span><div><strong>${x.voucher_id}</strong><small>${x.actor} · ${new Date(x.timestamp).toLocaleString('zh-CN')}<br>${x.rationale||'未填说明'}</small></div></div>`).join(''):'<div class="empty-state">本期还没有凭证复核记录。</div>';el('audit-list').innerHTML=state.auditEvents.length?state.auditEvents.map(x=>`<div class="audit-item"><span class="audit-action">${x.action}</span><div><strong>${x.target}</strong><small>${x.actor} · ${new Date(x.timestamp).toLocaleString('zh-CN')}<br>${JSON.stringify(x.detail||{})}</small></div></div>`).join(''):'<div class="empty-state">还没有操作日志。</div>'}

async function loadAudit(){try{const r=await fetch('/api/audit?limit=200'),data=await r.json();if(!r.ok)throw new Error(data.error);state.auditEvents=data.events||[];renderReview()}catch(e){toast(e.message||'审计日志读取失败')}}
function downloadAccountantPack(){if(!state.opsPeriod){toast('请先选择账期');return}window.location.href=`/api/accountant-pack?period=${encodeURIComponent(state.opsPeriod)}`}
function shadowCloseScope(){const entities=state.boxContext?.entities||[],select=el('shadow-close-entity');if(select&&!select.options.length)select.innerHTML=entities.map(x=>`<option value="${safe(x.id)}">${safe(x.name)} · ${safe(x.id)}</option>`).join('');const preferred=state.companyProfile?.entity_id||entities[0]?.id||'cn_studio';if(select&&!select.value&&entities.some(x=>x.id===preferred))select.value=preferred;const period=el('shadow-close-period');if(period&&!period.value)period.value=state.opsPeriod||new Date().toISOString().slice(0,7);return{entity_id:select?.value||preferred,period:period?.value||state.opsPeriod||''}}
async function loadShadowClose(){const scope=shadowCloseScope();if(!state.hasPersistentData){state.shadowClose=null;return renderShadowClose()}if(!scope.entity_id||!scope.period)return renderShadowClose();try{const r=await fetch(`/api/shadow-close?entity_id=${encodeURIComponent(scope.entity_id)}&period=${encodeURIComponent(scope.period)}`),data=await r.json();if(!r.ok)throw new Error(data.error);state.shadowClose=data;renderShadowClose()}catch(error){state.shadowClose=null;renderShadowClose();toast(error.message||'Shadow close 读取失败')}}
function renderShadowClose(){const data=state.shadowClose,report=data?.report,empty=el('shadow-close-empty'),results=el('shadow-close-results'),metrics=el('shadow-close-metrics');if(!metrics)return;if(!report){metrics.innerHTML=[['人工基准','未导入','按主体与期间隔离'],['对比方式','只读','不覆盖 Agent 或人工结果'],['签认','未开始','仅对当前指纹有效'],['运行边界','单主体','法定账不做管理合并']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value small-value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');empty.hidden=false;empty.innerHTML=`<div class="empty-state"><strong>${state.hasPersistentData?'尚未导入该主体和期间的人工关账基准':'当前是演示数据，Shadow close 只对持久化正式台账开放'}</strong><span>下载模板，由人工或外部会计填写已复核的总账、报表或税务底稿后导入。</span></div>`;results.hidden=true;return}empty.hidden=true;results.hidden=false;const reviewed=report.review_current,review=report.review;metrics.innerHTML=[['对比行',report.comparison_count,'只对基准已提供的域'],['一致',report.matched_count,'差异在明确容差内'],['差异 / 缺项',report.exception_count,report.exception_count?'需逐项解释':'可进入独立签认'],['签认',reviewed?review.decision:'待复核',reviewed?'当前指纹有效':'结果变化后旧签认失效']].map(x=>`<div class="metric"><div class="label">${safe(x[0])}</div><div class="value ${typeof x[1]==='string'?'small-value':''}">${safe(x[1])}</div><div class="foot">${safe(x[2])}</div></div>`).join('');el('shadow-close-status').textContent=report.status;el('shadow-close-status').className=`status ${report.exception_count?'error':'ok'}`;el('shadow-close-domains').innerHTML=(report.domain_summary||[]).map(x=>`<div class="shadow-domain"><span>${safe(x.label)}</span><strong>${x.matched}/${x.count}</strong><small>${x.exceptions?`${x.exceptions} 项需解释`:'全部一致'}</small></div>`).join('');const labels={trial_balance:'总账',statement:'报表',tax:'税务'};el('shadow-close-table').innerHTML=(report.comparisons||[]).map(x=>`<tr class="${x.status==='一致'?'':'shadow-exception'}"><td><strong>${safe(labels[x.domain]||x.domain)}</strong><br><small>${safe(x.key)}</small></td><td>${safe(x.name)}</td><td class="numeric">${x.manual_value==null?'—':fmt(x.manual_value,'')}</td><td class="numeric">${x.agent_value==null?'—':fmt(x.agent_value,'')}</td><td class="numeric">${x.difference==null?'—':fmt(x.difference,'')}</td><td><span class="status ${x.status==='一致'?'ok':'error'}">${safe(x.status)}</span></td><td><small>${safe(x.reason)}</small></td></tr>`).join('');el('shadow-review-status').textContent=reviewed?review.decision:'待复核';el('shadow-review-status').className=`status ${reviewed?'ok':'pending'}`;el('shadow-review-current').innerHTML=reviewed?`<strong>${safe(review.actor)}已签认“${safe(review.decision)}”</strong><span>${safe(review.rationale)} · ${new Date(review.reviewed_at).toLocaleString('zh-CN')}</span>`:`<strong>${safe(report.recommendation)}</strong><span>复核人应与生成 Agent 结果的操作人分开，并核对原始底稿。</span>`;el('shadow-review-decision').value=report.exception_count?'退回补数':'验证通过'}
async function uploadShadowClose(files){if(!files.length)return;if(!state.hasPersistentData){el('shadow-close-input').value='';return toast('请先导入正式台账，再做 Shadow close')}const form=new FormData();form.append('files',files[0]);form.append('actor','财务工作台用户');if(state.shadowClose?.baseline){if(!window.confirm('该主体和期间已有基准。确认以新工作簿替换？旧签认将因指纹变化而失效。'))return;form.append('confirmation','REPLACE_SHADOW_BASELINE')}el('loading').classList.add('show');try{const r=await fetch('/api/shadow-close-import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);state.shadowClose={entity_id:data.baseline.entity_id,period:data.baseline.period,status:data.report.status,baseline:data.baseline,report:data.report};el('shadow-close-entity').value=data.baseline.entity_id;el('shadow-close-period').value=data.baseline.period;state.opsPeriod=data.baseline.period;renderShadowClose();toast(`已导入 ${data.baseline.row_count} 行人工基准并完成只读对比`)}catch(error){toast(error.message||'Shadow close 导入失败')}finally{el('loading').classList.remove('show');el('shadow-close-input').value=''}}
async function submitShadowReview(){const scope=shadowCloseScope(),decision=el('shadow-review-decision').value,actor=el('shadow-review-actor').value.trim(),rationale=el('shadow-review-rationale').value.trim(),evidence=el('shadow-review-evidence').value.split(/[；;]/).map(x=>x.trim()).filter(Boolean);if(rationale.length<6)return toast('请填写至少6个字的签认依据');try{const r=await fetch('/api/shadow-close-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...scope,decision,actor,rationale,evidence})}),data=await r.json();if(!r.ok)throw new Error(data.error);state.shadowClose={...state.shadowClose,status:data.report.status,report:data.report};renderShadowClose();toast('已记录独立签认；数据变化后将自动失效')}catch(error){toast(error.message||'Shadow close 签认失败')}}

const renderShadowCloseWithoutResolutionControls=renderShadowClose;
renderShadowClose=function(){renderShadowCloseWithoutResolutionControls();const report=state.shadowClose?.report,table=el('shadow-close-table');if(!report||!table)return;const current=new Map((report.review?.exception_resolutions||[]).map(item=>[`${item.domain}\u0000${item.key}`,item]));[...table.querySelectorAll('tr')].forEach((row,index)=>{const comparison=report.comparisons?.[index],cell=document.createElement('td');if(!comparison||comparison.status==='一致'){cell.textContent='—';row.appendChild(cell);return}const resolution=current.get(`${comparison.domain}\u0000${comparison.key}`)||{};cell.innerHTML=`<details class="shadow-resolution" data-shadow-resolution-row data-shadow-domain="${safe(comparison.domain)}" data-shadow-key="${safe(comparison.key)}"><summary>${resolution.classification?'已记录处置':'填写分类、说明与证据'}</summary><select data-shadow-resolution-class><option value="">选择差异分类</option><option value="mapping">映射</option><option value="cutoff">截止</option><option value="accounting_policy">会计政策</option><option value="source_evidence">来源证据</option><option value="timing">时间差</option><option value="foreign_exchange">汇率</option><option value="accepted_scope">已批准范围</option><option value="system_defect">系统缺陷（阻塞 stable）</option></select><textarea data-shadow-resolution-rationale rows="3" placeholder="至少 12 个字，说明口径、截止、影响与处置">${safe(resolution.rationale||'')}</textarea><input data-shadow-resolution-evidence placeholder="证据引用，多项用分号分隔" value="${safe((resolution.evidence_references||[]).join('；'))}" /></details>`;cell.querySelector('[data-shadow-resolution-class]').value=resolution.classification||'';row.appendChild(cell)})};
submitShadowReview=async function(){const scope=shadowCloseScope(),decision=el('shadow-review-decision').value,actor=el('shadow-review-actor').value.trim(),rationale=el('shadow-review-rationale').value.trim(),evidence=evidenceList(el('shadow-review-evidence').value),rows=[...document.querySelectorAll('[data-shadow-resolution-row]')],exception_resolutions=decision==='接受差异'?rows.map(row=>({domain:row.dataset.shadowDomain,key:row.dataset.shadowKey,classification:row.querySelector('[data-shadow-resolution-class]').value,rationale:row.querySelector('[data-shadow-resolution-rationale]').value.trim(),evidence_references:evidenceList(row.querySelector('[data-shadow-resolution-evidence]').value)})):[];if(rationale.length<6)return toast('请填写至少6个字的签认依据');if(decision==='接受差异'&&exception_resolutions.some(item=>!item.classification||item.rationale.length<12||!item.evidence_references.length))return toast('接受差异前，请为每项差异填写分类、至少 12 个字说明和证据引用');try{const response=await fetch('/api/shadow-close-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...scope,decision,actor,rationale,evidence,exception_resolutions})}),data=await response.json();if(!response.ok)throw new Error(data.error);state.shadowClose={...state.shadowClose,status:data.report.status,report:data.report};renderShadowClose();toast('已记录独立签认；数据变化后将自动失效')}catch(error){toast(error.message||'Shadow close 签认失败')}};

async function closePeriod(){const output=el('close-result');try{const r=await fetch('/api/close-period',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({period:state.opsPeriod,actor:'财务负责人'})}),data=await r.json();if(!r.ok){if(r.status===409){output.className='close-result blocked';output.innerHTML=`<strong>暂不建议关账</strong><span>${(data.blockers||[]).join('；')}<br>${data.recommendation||''}</span>`;await loadAudit();return}throw new Error(data.error)}state.periodStates[state.opsPeriod]=data.period_state;output.className='close-result passed';output.innerHTML='<strong>关账检查通过</strong><span>本期已锁定，后续调整需要留下冲销或补充凭证记录。</span>';renderClose();await loadAudit()}catch(e){toast(e.message||'关账检查失败')}}
function renderLedger(){const t=state.financeOps.trial_balance,r=state.financeOps.period_report,b=state.financeOps.bank_reconciliation,f=state.financeOps.financial_statements||{};el('ledger-metrics').innerHTML=[['草稿收入',fmt(r.revenue,'CNY'),'已纳入试算凭证'],['草稿成本费用',fmt(r.expenses,'CNY'),'不含阻塞凭证'],['税前利润草稿',fmt(r.profit_before_tax_draft,'CNY'),r.scope],['试算差额',fmt(t.difference,'CNY'),`${t.included_vouchers.length}张纳入 / ${t.excluded_vouchers.length}张排除`]].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');el('trial-status').textContent=t.balanced?'借贷平衡':'借贷不平';el('trial-status').className=`status ${t.balanced?'ok':'error'}`;el('trial-table').innerHTML=t.rows.map(x=>`<tr><td>${x.account}</td><td class="numeric">${moneyOrPending(x.debit)}</td><td class="numeric">${moneyOrPending(x.credit)}</td><td class="numeric">${moneyOrPending(x.net)}</td></tr>`).join('')||'<tr><td colspan="4">暂无可纳入试算的凭证</td></tr>';const reportRows=[['收入',r.revenue,'base'],['成本费用',r.expenses,'refund'],['税前利润草稿',r.profit_before_tax_draft,'net'],['现金净变动',r.cash_movement,'base'],['应收净变动',r.receivable_movement,'tax'],['应付净变动',r.payable_movement,'tax']],max=Math.max(1,...[r.revenue,r.expenses,Math.abs(r.profit_before_tax_draft),Math.abs(r.cash_movement),Math.abs(r.receivable_movement),Math.abs(r.payable_movement)]);el('period-report').innerHTML=reportRows.map(x=>`<div class="water-row"><div class="water-label"><span>${x[0]}</span><strong>${fmt(x[1],'CNY')}</strong></div><div class="track"><div class="fill ${x[2]}" style="width:${Math.max(2,Math.abs(x[1])/max*100)}%"></div></div></div>`).join('')+`<p class="tax-missing">${r.scope}</p>`;el('bank-reconciliation').innerHTML=(b.accounts||[]).length?b.accounts.map(x=>`<div class="authority-item"><span>${safe(x.currency)}</span><div><strong>${safe(x.account_masked)} · 银行期末 ${moneyOrPending(x.statement_ending_balance)}</strong><small>收 ${moneyOrPending(x.receipts)} · 付 ${moneyOrPending(x.payments)} · ${x.matched}条已匹配 / ${x.pending}条待认领 · ${safe(x.status)}</small></div></div>`).join('')+`<div class="profile-gap"><strong>${b.status}</strong><span>${b.note}</span></div>`:`<div class="profile-gap"><strong>尚未导入银行流水</strong><span>${b.note}</span></div>`;const bs=f.balance_sheet||{},is=f.income_statement||{};el('statement-status').textContent=f.opening_available?(bs.balanced?'报表勾稽通过':'报表不平'):'待期初数';el('statement-status').className=`status ${f.opening_available&&bs.balanced?'ok':'pending'}`;el('financial-statements').innerHTML=[['资产',f.opening_available?fmt(bs.assets,'CNY'):'待期初数','资产负债表草稿'],['负债+权益+本期利润',f.opening_available?fmt(bs.liabilities_and_equity,'CNY'):'待期初数',f.opening_available?`差额 ${moneyOrPending(bs.difference)}`:f.guardrail],['本期收入',fmt(is.revenue||0,'CNY'),'利润表草稿'],['本期税前利润',fmt(is.profit_before_tax||0,'CNY'),'未包含未完成税务调整']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('')}

async function uploadOpeningBalances(files){if(!files.length)return;const form=new FormData();[...files].forEach(f=>form.append('files',f));form.append('period',state.opsPeriod||'');el('loading').classList.add('show');try{const r=await fetch('/api/opening-balance-import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);state.openingBalances=data.records||[];state.financeOps=null;await ensureFinanceOps(true);toast(`已导入 ${data.summary.count} 条期初科目余额，差额 ${data.summary.difference}`)}catch(e){toast(e.message||'期初余额导入失败')}finally{el('loading').classList.remove('show');el('opening-input').value=''}}
function renderTax(){const p=state.financeOps.tax_pack,w=p.returns_workspace||{returns:[],summary:{},workflow:[]},s=w.summary||{};el('tax-summary').innerHTML=[['申报表',s.form_count||0,'增值税、所得税、印花税、个税、财务报表'],['可进入复核',s.ready_for_review||0,'字段与证据达到当前规则'],['待补资料',s.blocked||0,'不能直接确认填报值'],['可直接上传',s.direct_upload_ready||0,'未适配属地模板前保持为0']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');renderTaxFilingAssist(state.taxFilingAssist||p.filing_assist);el('tax-workflow').innerHTML=(w.workflow||[]).map((x,i)=>`<div class="tax-step"><span>${i+1}</span><strong>${x}</strong></div>`).join('');el('tax-return-list').innerHTML=(w.returns||[]).map(t=>`<article class="tax-return-card"><div class="tax-return-head"><div><p class="eyebrow">${t.form_code} · ${t.version}</p><h3>${t.name}</h3><small>${t.frequency} · 复核：${t.review_role}</small></div><span class="status ${t.status==='待复核'?'ok':t.status==='不适用'?'pending':'error'}">${t.status}</span></div><div class="tax-return-grid"><div><strong>关键栏次</strong>${(t.fields||[]).slice(0,6).map(f=>`<div class="tax-field"><span>${f.name}</span><b>${typeof f.value==='number'?fmt(f.value,'CNY'):(f.value??'待补')}</b><small>${f.status} · ${f.source}</small></div>`).join('')}</div><div><strong>当前阻塞</strong><ul>${(t.blockers||[]).map(x=>`<li>${x}</li>`).join('')||'<li>无硬阻塞，待有权人复核</li>'}</ul><div class="tax-position"><strong>系统判断倾向</strong><p>${t.agent_position}</p></div></div></div><footer><span>${t.transport}</span><a href="${t.official_source}" target="_blank" rel="noopener">官方依据 ↗</a></footer></article>`).join('');el('tax-list').innerHTML=p.items.map(t=>`<article class="tax-card"><div class="tax-head"><div><h3>${t.tax}</h3><p>${t.frequency}</p></div><span class="status ${statusTone(t.status)}">${t.status}</span></div><div><div class="tax-output"><strong>系统会交付：</strong>${t.agent_output}</div><p class="tax-missing">当前还缺：${t.missing.join('、')||'基础资料已齐，待有权人复核'}</p></div><div><span class="status ${t.risk==='高'?'error':'pending'}">${t.risk}风险</span><p class="tax-missing">复核：${t.review_role}</p></div><div class="tax-decision">${decisionHtml(t.decision_support)}</div></article>`).join('');el('tax-list').querySelectorAll('.decision-card').forEach(x=>x.style.display='block');el('cross-border-reviews').innerHTML=p.cross_border.channels?.length?p.cross_border.channels.map(x=>`<div class="cross-review"><div><strong>${x.channel}</strong><span class="status ${x.status==='已完成'?'ok':'error'}">${x.status}</span><small>判断倾向：证据不足时保持“待补证据”，不按收款币种推断。</small></div><select data-tax-decision="${x.channel}"><option>待补证据</option><option>境内应税</option><option>跨境零税率</option><option>跨境免税</option></select><input data-tax-reviewer="${x.channel}" placeholder="复核人/税务机构" value="${x.review?.reviewer||''}"/><input data-tax-evidence="${x.channel}" placeholder="合同、消费地、履约及其他证据" value="${x.review?.evidence||''}"/><button class="button primary" data-save-tax="${x.channel}">记录复核</button></div>`).join(''):'<div class="empty-state">本期没有识别到海外渠道结算。</div>';p.cross_border.channels?.forEach(x=>{const select=document.querySelector(`[data-tax-decision="${x.channel}"]`);if(select)select.value=x.review?.decision||'待补证据'});el('cross-border-reviews').querySelectorAll('[data-save-tax]').forEach(b=>b.onclick=()=>saveTaxReview(b.dataset.saveTax));el('authority-list').innerHTML=state.financeOps.sources.map(s=>`<div class="authority-item"><span>${s.authority}</span><div><a href="${s.url}" target="_blank" rel="noopener">${s.title} ↗</a><small>生效 ${s.effective_date}${s.expires_date?` · 有效至 ${s.expires_date}`:''} · ${s.applies_to.join('、')}</small></div></div>`).join('')}
function renderTaxFilingAssist(assist){const summary=el('tax-release-summary'),list=el('tax-filing-contracts');if(!summary||!list)return;if(!assist){summary.textContent='等待生成';list.innerHTML='<div class="empty-state">选择申报期间后生成表单契约。</div>';return}summary.textContent=`${assist.summary?.ready_for_release||0} / ${assist.summary?.form_count||0} 可释放`;summary.className=`status ${assist.summary?.blocked?'pending':'ok'}`;list.innerHTML=(assist.forms||[]).map(form=>{const canReview=state.hasPersistentData&&!form.blockers?.length&&!form.review_current;const reviewed=form.review_current;return `<article class="filing-contract"><div class="contract-main"><span class="contract-code">${safe(form.form_code)}</span><div><strong>${safe(form.name)}</strong><small>${safe(form.contract_id)} · ${safe(form.contract?.version)}</small><a href="${safe(form.contract?.official_form_page)}" target="_blank" rel="noopener">查看官方表样与依据 ↗</a></div></div><div class="contract-state"><span class="status ${form.release_ready?'ok':form.blockers?.length?'error':'pending'}">${safe(form.release_status)}</span><small>复核 ${safe(form.review_status)} · 申报 ${safe(form.submission_status)}</small></div>${form.blockers?.length?`<div class="contract-blockers">${form.blockers.map(safe).join('；')}</div>`:''}${canReview?`<div class="contract-action"><input data-tax-review-rationale="${safe(form.form_code)}" placeholder="复核依据（至少6个字）"/><input data-tax-review-evidence="${safe(form.form_code)}" placeholder="证据或底稿说明"/><button class="button primary" data-tax-form-review="${safe(form.form_code)}">同意草稿</button></div>`:reviewed&&state.hasPersistentData?`<div class="contract-action"><select data-tax-submit-status="${safe(form.form_code)}"><option>已进入申报端</option><option>已提交待回执</option><option>申报成功</option><option>申报失败</option><option>已缴款</option><option>无需缴款</option></select><input data-tax-submit-ref="${safe(form.form_code)}" placeholder="流水号、回执号或凭证号"/><input data-tax-submit-evidence="${safe(form.form_code)}" placeholder="回执/缴款凭证证据"/><button class="button ghost" data-tax-submit="${safe(form.form_code)}" data-review-id="${safe(form.review_id||'')}">登记状态</button></div>`:!state.hasPersistentData?'<div class="contract-note">示例只展示表单版本与阻塞逻辑，不写入正式复核。</div>':''}</article>`}).join('');list.querySelectorAll('[data-tax-form-review]').forEach(button=>button.onclick=()=>reviewTaxForm(button.dataset.taxFormReview));list.querySelectorAll('[data-tax-submit]').forEach(button=>button.onclick=()=>recordTaxSubmission(button.dataset.taxSubmit,button.dataset.reviewId))}
async function loadTaxFilingAssist(){if(!state.opsPeriod||!state.hasPersistentData)return;try{const r=await fetch(`/api/tax-filing-assist?period=${encodeURIComponent(state.opsPeriod)}`),data=await r.json();if(!r.ok)throw new Error(data.error);state.taxFilingAssist=data;renderTaxFilingAssist(data)}catch(e){toast(e.message||'申报契约读取失败')}}
async function reviewTaxForm(code){const rationale=document.querySelector(`[data-tax-review-rationale="${code}"]`)?.value.trim()||'',evidence=document.querySelector(`[data-tax-review-evidence="${code}"]`)?.value.trim()||'';if(rationale.length<6)return toast('请填写至少6个字的复核依据');try{const r=await fetch('/api/tax-form-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({period:state.opsPeriod,entity_id:state.taxFilingAssist?.entity_id||'',form_code:code,decision:'同意草稿',actor:'财务工作台用户',rationale,evidence:evidence?[evidence]:[]})}),data=await r.json();if(!r.ok)throw new Error(data.error);toast(`${code} 已锁定当前版本和数据指纹`);await loadTaxFilingAssist()}catch(e){toast(e.message||'税务表单复核失败')}}
async function recordTaxSubmission(code,reviewId){const status=document.querySelector(`[data-tax-submit-status="${code}"]`)?.value||'',reference=document.querySelector(`[data-tax-submit-ref="${code}"]`)?.value.trim()||'',evidence=document.querySelector(`[data-tax-submit-evidence="${code}"]`)?.value.trim()||'';try{const r=await fetch('/api/tax-submission',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({review_id:reviewId,status,actor:'财务工作台用户',reference,evidence:evidence?[evidence]:[]})}),data=await r.json();if(!r.ok)throw new Error(data.error);toast(`${code} 已登记“${status}”并保留证据`);await loadTaxFilingAssist()}catch(e){toast(e.message||'申报状态登记失败')}}
async function downloadTaxWorkbook(){if(!state.opsPeriod)return toast('请先选择申报期间');el('loading').classList.add('show');try{const r=await fetch(`/api/tax-return-workbook?period=${encodeURIComponent(state.opsPeriod)}`);if(!r.ok){const d=await r.json();throw new Error(d.error)}const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`税务申报工作底稿-${state.opsPeriod}.xlsx`;a.click();URL.revokeObjectURL(a.href);toast('申报工作底稿已生成；上传状态请看每张表说明')}catch(e){toast(e.message||'税务申报工作底稿生成失败')}finally{el('loading').classList.remove('show')}}
async function downloadTaxFilingPackage(){if(!state.opsPeriod)return toast('请先选择申报期间');if(!state.hasPersistentData)return toast('当前是示例数据；请先导入正式台账再生成申报辅助包');el('loading').classList.add('show');try{const r=await fetch(`/api/tax-filing-assist-package?period=${encodeURIComponent(state.opsPeriod)}`);if(!r.ok){const d=await r.json();throw new Error(d.error)}const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`税务申报辅助包-${state.opsPeriod}.zip`;a.click();URL.revokeObjectURL(a.href);toast('已生成带表单契约、字段映射和回执模板的申报辅助包')}catch(e){toast(e.message||'申报辅助包生成失败')}finally{el('loading').classList.remove('show')}}
async function saveTaxReview(channel){const decision=document.querySelector(`[data-tax-decision="${channel}"]`).value,reviewer=document.querySelector(`[data-tax-reviewer="${channel}"]`).value,evidence=document.querySelector(`[data-tax-evidence="${channel}"]`).value;try{const r=await fetch('/api/tax-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({period:state.opsPeriod,channel,decision,reviewer,evidence,actor:'财务工作台用户'})}),data=await r.json();if(!r.ok)throw new Error(data.error);state.companyProfile=data.profile;state.financeOps=null;await ensureFinanceOps(true);toast(`${channel} 税务复核已留痕`)}catch(e){toast(e.message||'跨境税务复核保存失败')}}
async function uploadProcurement(files){if(!files.length)return;const form=new FormData();[...files].forEach(f=>form.append('files',f));el('loading').classList.add('show');try{const r=await fetch('/api/procurement-import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);state.procurement=data;state.financeOps=null;renderProcurement();toast(`已识别 ${data.summary.record_count} 条采购记录，并已接入月结与凭证草稿`)}catch(e){toast(e.message||'采购台账导入失败')}finally{el('loading').classList.remove('show');el('procurement-input').value=''}}
function renderProcurement(){const data=state.procurement;if(!data){el('procurement-metrics').innerHTML=[['采购记录','—','等待导入'],['订单金额','—','按币种核对'],['未开票暂估','—','需验收证据'],['异常','—','机器逐行检查']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');return}const s=data.summary;el('procurement-metrics').innerHTML=[['PO / 记录',`${s.po_count} / ${s.record_count}`,'采购数据规模'],['订单金额',fmt(s.ordered_amount,'CNY'),'当前导入合计'],['未开票暴露',fmt(s.uninvoiced_exposure,'CNY'),'已验收－已开票'],['异常记录',s.exception_count,'需处理后才能付款']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');el('procurement-status').textContent=`${s.exception_count} 项异常`;el('procurement-status').className=`status ${s.exception_count?'error':'ok'}`;el('procurement-table').innerHTML=data.records.map(r=>`<tr><td><strong>${r.po_number||'缺PO'}</strong><br><small>${r.order_date||'日期待补'}</small></td><td>${r.project}<br><small>${r.category}</small></td><td>${r.vendor}<br><small>${r.item}</small></td><td class="numeric">${moneyOrPending(r.quantity)}</td><td class="numeric">${moneyOrPending(r.unit_price)}</td><td class="numeric">${moneyOrPending(r.ordered_amount)}</td><td><span class="status ${r.accepted_amount?'ok':'pending'}">${r.delivery_status}</span></td><td><span class="status ${r.invoice_status==='已开票'?'ok':'pending'}">${r.invoice_status}</span></td><td><span class="status ${r.payment_status==='已付款'?'ok':'pending'}">${r.payment_status}</span></td><td>${r.anomalies.length?`<span class="status error">${r.anomalies.join('；')}</span>`:`<span class="status pending">${r.accounting_status}</span>`}<br><small>${r.source_sheet} 第${r.source_row}行</small></td></tr>`).join('')}
async function loadProcurementWorkflow(force=false){renderProcurement();const entityId=state.opsEntityId||defaultOpsEntityId();if(!state.hasPersistentData){const d=state.agentWorkspace?.datasets||{},requests=d.procurement_requests||[],orders=d.purchases||state.procurement?.records||[],deliveries=d.purchase_deliveries||[];state.procurementWorkflow={entity_id:entityId,requests:requests.filter(x=>x.entity_id===entityId),orders:orders.filter(x=>x.entity_id===entityId),deliveries:deliveries.filter(x=>x.entity_id===entityId),summary:{approved_to_order:requests.filter(x=>x.entity_id===entityId&&x.status==='已批准').length,open_orders:orders.filter(x=>x.entity_id===entityId&&x.acceptance_status!=='已验收').length,delivered_to_accept:deliveries.filter(x=>x.entity_id===entityId&&x.status==='已交付待验收').length,linked_orders:orders.filter(x=>x.entity_id===entityId&&x.procurement_request_id).length}};renderProcurementWorkflow();return}if(state.procurementWorkflow&&!force&&state.procurementWorkflow.entity_id===entityId){renderProcurementWorkflow();return}try{const r=await fetch(`/api/procurement-workflow?entity_id=${encodeURIComponent(entityId)}`),data=await r.json();if(!r.ok)throw new Error(data.error);state.procurementWorkflow=data;renderProcurementWorkflow()}catch(error){toast(error.message||'采购履约状态读取失败')}}
function procurementActionRow(title,meta,detail,action=''){return `<div class="flow-row"><div><strong>${safe(title)}</strong><small>${safe(meta)}</small><span>${safe(detail)}</span></div>${action?`<div class="flow-row-actions">${action}</div>`:''}</div>`}
function renderProcurementWorkflow(){const data=state.procurementWorkflow||{requests:[],orders:[],deliveries:[],summary:{}},requests=data.requests||[],orders=data.orders||[],deliveries=data.deliveries||[],summary=data.summary||{},live=state.hasPersistentData,ready=requests.filter(x=>x.status==='已批准'),openOrders=orders.filter(x=>(x.milestones||[]).length&&x.acceptance_status!=='已验收'),pending=deliveries.filter(x=>x.status==='已交付待验收');el('procurement-order-ready').textContent=`${ready.length} 个待下单`;el('procurement-order-ready').className=`status ${ready.length?'pending':'ok'}`;el('procurement-order-actions').innerHTML=[...ready.map(row=>procurementActionRow(row.description,`${row.project} · ${row.selected_vendor} · ${fmt(row.amount,row.currency)}`,`预算 ${row.period} · ${row.sourcing_method}`,live?`<button class="text-button" data-proc-order="${safe(row.id)}">生成订单</button>`:'<span class="status pending">演示流程</span>')),...orders.filter(x=>x.procurement_request_id).slice(0,4).map(row=>procurementActionRow(row.po_number,`${row.vendor} · ${fmt(row.ordered_amount,row.currency)}`,`${(row.milestones||[]).length} 个里程碑 · ${row.acceptance_status}`,''))].join('')||'<div class="empty-state">当前没有已批准待下单申请。</div>';el('procurement-delivery-ready').textContent=`${pending.length} 个待验收`;el('procurement-delivery-ready').className=`status ${pending.length?'pending':'ok'}`;el('procurement-delivery-actions').innerHTML=[...openOrders.map(order=>{const deliveredIds=new Set(deliveries.filter(x=>x.purchase_id===order.id).map(x=>x.milestone_id));const next=(order.milestones||[]).find(x=>!deliveredIds.has(x.id));return procurementActionRow(order.po_number,`${order.vendor} · ${order.acceptance_status}`,next?`下一里程碑：${next.title} · ${fmt(next.amount,next.currency)}`:'所有交付已登记，等待验收',live&&next?`<button class="text-button" data-proc-delivery="${safe(order.id)}:${safe(next.id)}">登记交付</button>`:'')}) ,...pending.map(row=>procurementActionRow(row.milestone_title,`${row.po_number} · ${fmt(row.delivered_amount,row.currency)}`,`已交付，按“${row.acceptance_criteria||'订单标准'}”验收`,`<button class="text-button" data-go="confirmations">去验收</button>`))].join('')||'<div class="empty-state">当前没有待登记交付或待验收里程碑。</div>';el('procurement-order-actions').querySelectorAll('[data-proc-order]').forEach(button=>button.onclick=()=>openPurchaseOrderForm(button.dataset.procOrder));el('procurement-delivery-actions').querySelectorAll('[data-proc-delivery]').forEach(button=>button.onclick=()=>{const [orderId,milestoneId]=button.dataset.procDelivery.split(':');openPurchaseDeliveryForm(orderId,milestoneId)});el('procurement-delivery-actions').querySelectorAll('[data-go]').forEach(button=>button.onclick=()=>setView(button.dataset.go));}
function parseMilestoneLines(value,currency){return String(value||'').split(/\n+/).map(line=>{const [title,amount,due_date,acceptance_criteria,owner]=line.split(/[，,]/).map(x=>x.trim());return{title,amount:Number(amount||0),due_date,acceptance_criteria,owner,currency}}).filter(x=>x.title&&x.amount>0)}
function openPurchaseOrderForm(requestId){const row=(state.procurementWorkflow?.requests||[]).find(x=>x.id===requestId);if(!row)return toast('找不到已批准采购申请');const today=new Date().toISOString().slice(0,10);openFlowModal('生成采购订单','申请与预算已绑定',`<div class="form-grid"><label>已批准申请<input value="${safe(row.description)}" disabled /></label><label>批准金额<input value="${safe(fmt(row.amount,row.currency))}" disabled /></label><label>PO 编号<input id="proc-order-po" /></label><label>订单日期<input id="proc-order-date" type="date" value="${today}" /></label><label class="wide">订单条目<input id="proc-order-item" value="${safe(row.description)}" /></label><label class="wide">交付里程碑（每行：名称,金额,日期,验收标准,负责人）<textarea id="proc-order-milestones" placeholder="首批角色素材,60000,2026-09-10,源文件和清单完整,美术负责人\n商店页素材,40000,2026-09-20,尺寸语言齐全,发行负责人"></textarea></label><label class="wide">订单依据（分号分隔）<textarea id="proc-order-evidence" placeholder="双方订单确认；报价确认邮件"></textarea></label><div class="profile-gap wide"><strong>里程碑金额必须等于批准金额</strong><span>订单会保留原采购申请、预算快照和寻源证据；后续只能按这些里程碑登记交付。</span></div></div>`,{kind:'purchase_order',entityId:row.entity_id,requestId:row.id,currency:row.currency,idempotencyKey:`order-${row.id}-${Date.now()}`})}
function openPurchaseDeliveryForm(orderId,milestoneId){const order=(state.procurementWorkflow?.orders||[]).find(x=>x.id===orderId),milestone=(order?.milestones||[]).find(x=>x.id===milestoneId);if(!order||!milestone)return toast('找不到采购里程碑');const today=new Date().toISOString().slice(0,10);openFlowModal('登记里程碑交付','尚未验收',`<div class="form-grid"><label>采购订单<input value="${safe(order.po_number)} · ${safe(order.vendor)}" disabled /></label><label>里程碑<input value="${safe(milestone.title)}" disabled /></label><label>本次交付金额<input id="proc-delivery-amount" type="number" step="0.01" value="${safe(milestone.amount)}" /></label><label>交付日期<input id="proc-delivery-date" type="date" value="${today}" /></label><label class="wide">交付证据（分号分隔）<textarea id="proc-delivery-evidence" placeholder="交付清单；文件链接/哈希；供应商交付邮件"></textarea></label><label class="wide">交付说明<textarea id="proc-delivery-note"></textarea></label><div class="profile-gap wide"><strong>登记交付不等于验收</strong><span>提交后会由里程碑负责人按“${safe(milestone.acceptance_criteria)}”独立验收，未验收部分不会释放付款额度。</span></div></div>`,{kind:'purchase_delivery',entityId:order.entity_id,orderId,milestoneId,idempotencyKey:`delivery-${order.id}-${milestone.id}-${Date.now()}`})}
async function uploadBank(files){if(!files.length)return;const form=new FormData();[...files].forEach(f=>form.append('files',f));form.append('settlements',JSON.stringify(records()));form.append('purchases',JSON.stringify(state.procurement?.records||[]));el('loading').classList.add('show');try{const r=await fetch('/api/bank-import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);state.banking=data;state.financeOps=null;renderBanking();toast(`已识别 ${data.summary.count} 条银行流水，${data.summary.high_confidence_count} 条高置信匹配`)}catch(e){toast(e.message||'银行流水导入失败')}finally{el('loading').classList.remove('show');el('bank-input').value=''}}
function renderBanking(){const data=state.banking;if(!data){el('bank-metrics').innerHTML=[['银行流水','—','等待导入'],['本期收款','—','匹配应收'],['本期付款','—','匹配应付'],['待认领','—','不明款项不入账']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');return}const s=data.summary;el('bank-metrics').innerHTML=[['银行流水',s.count,`${s.currencies.join(' / ')} 独立核对`],['本期收款',fmt(s.receipt_amount,s.currencies.length===1?s.currencies[0]:''),'匹配游戏应收'],['本期付款',fmt(s.payment_amount,s.currencies.length===1?s.currencies[0]:''),'匹配采购应付'],['待确认/认领',s.pending_count,`${s.high_confidence_count} 条高置信匹配`]].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');el('bank-status').textContent=`${s.pending_count} 条待处理`;el('bank-status').className=`status ${s.pending_count?'pending':'ok'}`;el('bank-table').innerHTML=data.transactions.map(r=>{const m=r.suggested_match;return`<tr><td>${r.transaction_date||'日期待补'}<br><small>${r.transaction_id||r.account_masked||'流水号待补'}</small></td><td><span class="status ${r.direction==='收入'?'ok':r.direction==='支出'?'pending':'error'}">${r.direction}</span></td><td>${r.counterparty||'待识别'}<br><small>${r.counterparty_account_masked||''}</small></td><td>${r.summary||'—'}</td><td>${r.currency}</td><td class="numeric">${fmt(r.amount,r.currency)}</td><td>${m?`<strong>${m.type} · ${Math.round(m.confidence*100)}%</strong><br><small>${m.target}</small><br><small>${m.recommendation}</small>`:'<small>金额或对手不足以匹配。请确认这是哪个游戏收入、供应商付款、股东往来或银行内部调拨。</small>'}</td><td><span class="status ${r.status==='高置信匹配'?'ok':r.status==='待认领'?'error':'pending'}">${r.status}</span></td></tr>`}).join('')}
function flowEntityOptions(){const entities=state.documentEntities?.length?state.documentEntities:(state.companyProfile?.legal_entities||[]).map(x=>({id:x.entity_id,name:x.name}));return entities.length?entities:[{id:state.companyProfile?.entity_id||'cn_studio',name:state.companyProfile?.company_name||'当前主体'}]}
async function loadBusinessFlows(){const select=el('flow-entity'),entities=flowEntityOptions(),scenario=el('sample-scenario')?.value||'group';if(select){const current=select.value||((scenario==='domestic'&&'cn_studio')||(scenario==='overseas'&&'sg_publisher')||'');select.innerHTML='<option value="">全球管理汇总</option>'+entities.map(x=>`<option value="${safe(x.id)}">${safe(x.name)} · ${safe(x.id)}</option>`).join('');select.value=entities.some(x=>x.id===current)?current:''}if(!state.hasPersistentData&&state.businessFlows){renderBusinessFlows();return}try{const entity=select?.value||'',r=await fetch(`/api/business-flows?entity_id=${encodeURIComponent(entity)}`),data=await r.json();if(!r.ok)throw new Error(data.error);state.businessFlows=data;renderBusinessFlows()}catch(e){toast(e.message||'收付款状态读取失败')}}
function flowRow({title,meta,amount,currency,status,detail,action}){return `<div class="flow-row"><div><strong>${safe(title)}</strong><small>${safe(meta)}</small>${detail?`<p>${safe(detail)}</p>`:''}</div><div class="flow-row-end"><b>${amount==null?'—':fmt(amount,currency)}</b><span class="status ${agentTone(status)}">${safe(status)}</span>${action||''}</div></div>`}
function currencyOutstanding(rows){const totals={};rows.forEach(row=>{const amount=Math.max(0,Number(row.outstanding||0));if(!amount)return;const currency=row.currency||'未知';totals[currency]=(totals[currency]||0)+amount});return Object.entries(totals).map(([currency,amount])=>`${currency} ${new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(amount)}`).join(' · ')||'—'}
function renderBusinessFlows(){const f=state.businessFlows;if(!f)return;const rec=f.receivables||{rows:[]},pay=f.payables||{rows:[]},payroll=f.payroll_payables||{rows:[]},requests=f.payment_request_records||[],claims=f.expense_claim_records||[],banks=(f.bank_transactions||[]).filter(x=>!['已核销'].includes(x.status)),recOutstanding=(rec.summary_by_currency||[]).map(x=>`${x.currency} ${new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(x.outstanding)}`).join(' · ')||'—',payOutstanding=currencyOutstanding([...(pay.rows||[]),...(payroll.rows||[])]);el('flow-metrics').innerHTML=[['待回款',recOutstanding,`${rec.overdue_count||0} 笔逾期`],['待付款',payOutstanding,`${pay.pending_payment_count||0}+${payroll.pending_count||0} 个目标`],['等待确认',(f.payment_requests?.pending_approval||0)+(f.expense_claims?.pending_approval||0),'统一进入待我确认'],['未认领流水',f.bank_unallocated_count||0,'确认用途后再核销']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value ${String(x[1]).length>20?'small-value':''}">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');el('flow-alerts').innerHTML=(f.alerts||[]).map(x=>`<div class="flow-alert"><span class="status ${x.severity==='高'?'error':'pending'}">${safe(x.severity)}</span><strong>${safe(x.type)} · ${x.count}</strong><small>${safe(x.action)}</small></div>`).join('')||'<div class="flow-alert"><span class="status ok">正常</span><strong>当前没有高优先级资金异常</strong><small>Agent 会随银行、应收应付和审批状态更新。</small></div>';el('receivable-count').textContent=`${rec.rows.length} 笔`;el('receivable-list').innerHTML=rec.rows.map(x=>flowRow({title:`${x.game||'游戏'} · ${x.channel||'渠道'}`,meta:`${x.period} · 到期 ${x.due_date||'待配置'}`,amount:x.outstanding,currency:x.currency,status:x.status,detail:x.anomalies?.join('；'),action:x.outstanding>0?`<button class="text-button" data-flow-collect="${safe(x.id)}">查看可核销流水</button>`:''})).join('')||'<div class="empty-state">暂无应收记录</div>';el('payable-count').textContent=`${pay.rows.length+payroll.rows.length} 个`;el('payable-list').innerHTML=[...pay.rows.map(x=>flowRow({title:x.item||x.vendor||x.po_number,meta:`${x.vendor||''} · ${x.currency} · 已验收 ${moneyOrPending(x.accepted_amount)} · 可付 ${fmt(x.payment_available_amount||0,x.currency)}`,amount:x.outstanding,currency:x.currency,status:x.status,detail:x.anomalies?.join('；'),action:x.payment_available_amount>0?`<button class="text-button" data-flow-payment="payable" data-target="${safe(x.id)}">申请付款</button>`:''})),...payroll.rows.map(x=>flowRow({title:`${x.period} 工资批次`,meta:`${x.employee_count} 人 · 隐私汇总`,amount:x.outstanding,currency:x.currency,status:x.status,detail:x.anomalies?.join('；'),action:x.outstanding>0?`<button class="text-button" data-flow-payment="payroll" data-target="${safe(x.id)}">申请付款</button>`:''}))].join('')||'<div class="empty-state">暂无待付目标</div>';el('payment-request-list').innerHTML=requests.map(x=>flowRow({title:x.purpose||x.target_id,meta:`${x.requested_by||''} · ${x.period||''}`,amount:x.amount,currency:x.currency,status:x.status,detail:(x.blockers||[]).join('；')||x.agent_recommendation})).join('')||'<div class="empty-state">还没有付款申请</div>';el('expense-claim-list').innerHTML=claims.map(x=>flowRow({title:`${x.claimant} · ${x.category}`,meta:`${x.claim_date} · ${x.project}`,amount:x.approved_amount||x.amount,currency:x.currency,status:x.status,detail:(x.blockers||[]).join('；')||x.purpose,action:x.status==='已批准待付款'?`<button class="text-button" data-flow-payment="expense" data-target="${safe(x.id)}">申请付款</button>`:''})).join('')||'<div class="empty-state">还没有费用报销</div>';el('allocation-list').innerHTML=banks.map(x=>{const m=x.suggested_match,can=m?.target_id&&['收入','支出'].includes(x.direction);return flowRow({title:`${x.counterparty||'未知对手'} · ${x.summary||'未写摘要'}`,meta:`${x.transaction_date||''} · ${x.transaction_id||x.id} · ${x.direction}`,amount:x.amount,currency:x.currency,status:x.status,detail:m?`${m.type}：${m.target} · 置信度 ${Math.round((m.confidence||0)*100)}%`:'Agent 尚未找到可靠核销目标',action:can?`<button class="text-button" data-flow-allocate="${safe(x.id)}" data-target="${safe(m.target_id)}" data-type="${x.direction==='收入'?'receivable':'payable'}">确认核销</button>`:''})}).join('')||'<div class="empty-state">没有待认领银行流水</div>';document.querySelectorAll('[data-flow-payment]').forEach(b=>b.onclick=()=>openPaymentForm(b.dataset.flowPayment,b.dataset.target));document.querySelectorAll('[data-flow-allocate]').forEach(b=>b.onclick=()=>openAllocationForm(b.dataset.flowAllocate,b.dataset.type,b.dataset.target));document.querySelectorAll('[data-flow-collect]').forEach(b=>b.onclick=()=>{const bank=(f.bank_transactions||[]).find(x=>x.direction==='收入'&&x.suggested_match?.target_id===b.dataset.flowCollect);if(bank)openAllocationForm(bank.id,'receivable',b.dataset.flowCollect);else toast('暂未找到指向该应收的银行流水，请先导入或认领银行对账单')});}
function openFlowModal(title,kicker,html,action){state.flowAction={...action,idempotencyKey:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`};el('flow-modal-title').textContent=title;el('flow-modal-kicker').textContent=kicker;el('flow-modal-body').innerHTML=html;el('flow-modal-submit').textContent=action?.kind==='bank_reconciliation'?'提交复核':'提交';el('flow-modal').classList.add('show');el('flow-modal').setAttribute('aria-hidden','false')}
function closeFlowModal(){state.flowAction=null;el('flow-modal-submit').textContent='提交';el('flow-modal').classList.remove('show');el('flow-modal').setAttribute('aria-hidden','true')}
function evidenceList(value){return String(value||'').split(/[；;\n]/).map(x=>x.trim()).filter(Boolean)}
async function openPaymentForm(type,targetId){const candidates=[...(state.businessFlows?.payables?.rows||[]),...(state.businessFlows?.payroll_payables?.rows||[]),...(state.businessFlows?.expense_claim_records||[])],target=candidates.find(x=>x.id===targetId),amount=Number(type==='payable'&&target&&'payment_available_amount'in target?target.payment_available_amount:(target?.outstanding||target?.approved_amount||0)),entityId=el('flow-entity')?.value||state.opsEntityId||'',currency=target?.currency||'CNY';let accounts=[];if(type==='payable'&&entityId&&target?.vendor){try{const response=await fetch(`/api/vendor-bank-accounts?entity_id=${encodeURIComponent(entityId)}&vendor=${encodeURIComponent(target.vendor)}&currency=${encodeURIComponent(currency)}`),data=await response.json();if(response.ok)accounts=data.accounts||[]}catch(error){toast('供应商收款账户读取失败')}}const accountField=type==='payable'?`<label class="wide">已批准供应商收款账户<select id="flow-payment-bank-account"><option value="">请先完成独立账户复核</option>${accounts.map(item=>`<option value="${safe(item.id)}">${safe(item.beneficiary_name)} · ${safe(item.bank_name)} · ${safe(item.account_masked)}</option>`).join('')}</select></label>`:'';openFlowModal('申请付款','资金动作',`<div class="form-grid"><label>付款目标<input value="${safe(target?.item||target?.purpose||targetId)}" disabled /></label><label>币种<input value="${safe(currency)}" disabled /></label><label>申请金额<input id="flow-payment-amount" type="number" min="0.01" step="0.01" value="${amount}" /></label><label>账期<input id="flow-payment-period" value="${safe(state.opsPeriod||new Date().toISOString().slice(0,7))}" /></label>${accountField}<label class="wide">付款用途<input id="flow-payment-purpose" value="支付${safe(target?.item||target?.purpose||'已确认款项')}" /></label><label class="wide">证据（分号分隔）<textarea id="flow-payment-evidence">验收记录；已查验发票；收款账户复核</textarea></label><label class="checkbox-line"><input id="flow-payment-prepay" type="checkbox" /> 这是预付款</label>${type==='payable'&&!accounts.length?'<div class="profile-gap wide"><strong>尚无已批准收款账户</strong><span>先在采购页新增账户并由另一人独立回拨或核对银行证明，付款申请才可批准。</span></div>':''}</div>`,{kind:'payment',type,targetId})}
function openExpenseForm(){const entity=el('flow-entity')?.value||state.companyProfile?.entity_id||'';openFlowModal('提交费用报销','员工费用',`<div class="form-grid"><label>报销人<input id="flow-expense-claimant" /></label><label>日期<input id="flow-expense-date" type="date" value="${new Date().toISOString().slice(0,10)}" /></label><label>金额<input id="flow-expense-amount" type="number" min="0.01" step="0.01" /></label><label>币种<select id="flow-expense-currency"><option>CNY</option><option>USD</option><option>HKD</option><option>SGD</option></select></label><label>游戏/项目<input id="flow-expense-project" /></label><label>费用类型<input id="flow-expense-category" placeholder="差旅、招待、软件等" /></label><label class="wide">业务用途<textarea id="flow-expense-purpose"></textarea></label><label class="wide">证据（分号分隔）<textarea id="flow-expense-evidence" placeholder="电子发票；付款记录；业务纪要"></textarea></label></div>`,{kind:'expense',entity})}
const openExpenseFormWithoutEntityGuard=openExpenseForm;openExpenseForm=function(){if(!el('flow-entity')?.value)return toast('全球管理汇总只读；请先选择报销所属法律主体');return openExpenseFormWithoutEntityGuard()};
function flowEntityContext(){const entityId=el('flow-entity')?.value||'',entity=(state.boxContext?.entities||[]).find(item=>item.id===entityId);return{entityId,functionalCurrency:entity?.functional_currency||'CNY',accountingBasis:entity?.accounting_basis||''}}
function currencyOptions(selected){return['CNY','USD','SGD','HKD','EUR','JPY'].map(currency=>`<option ${currency===selected?'selected':''}>${currency}</option>`).join('')}
function openAssetForm(){const context=flowEntityContext();if(!context.entityId)return toast('请先选择资产所属法律主体');openFlowModal('登记资产或待摊项目','会计事项',`<div class="form-grid"><label>资产名称<input id="flow-asset-name" /></label><label>类别<select id="flow-asset-type"><option>固定资产</option><option>无形资产</option><option>长期待摊费用</option><option>预付费用</option></select></label><label>取得日期<input id="flow-asset-date" type="date" value="${new Date().toISOString().slice(0,10)}" /></label><label>原币<select id="flow-asset-currency">${currencyOptions(context.functionalCurrency)}</select></label><label>原币成本<input id="flow-asset-cost" type="number" min="0.01" step="0.01" /></label><label>预计受益月数<input id="flow-asset-months" type="number" min="1" max="600" /></label><label>原币残值<input id="flow-asset-residual" type="number" min="0" step="0.01" value="0" /></label><label>折算汇率<input id="flow-asset-fx" type="number" min="0" step="0.000001" placeholder="1 原币 = ? ${safe(context.functionalCurrency)}；同币可留空" /></label><label>游戏/项目<input id="flow-asset-project" /></label><label>供应商<input id="flow-asset-vendor" /></label><label class="wide">证据（分号分隔）<textarea id="flow-asset-evidence" placeholder="合同；发票；验收记录；付款记录"></textarea></label><div class="profile-gap wide"><strong>${safe(context.functionalCurrency)} 本位币 · ${safe(context.accountingBasis)}</strong><span>系统按所选主体生成折旧/摊销底稿；类别和受益期仍进入会计复核。</span></div></div>`,{kind:'asset',entity:context.entityId,functionalCurrency:context.functionalCurrency})}
function openAccrualForm(){const context=flowEntityContext();if(!context.entityId)return toast('请先选择暂估所属法律主体');openFlowModal('新增费用暂估','会计事项',`<div class="form-grid"><label>账期<input id="flow-accrual-period" value="${safe(state.opsPeriod||new Date().toISOString().slice(0,7))}" /></label><label>原币<select id="flow-accrual-currency">${currencyOptions(context.functionalCurrency)}</select></label><label>暂估事项<input id="flow-accrual-description" /></label><label>原币金额<input id="flow-accrual-amount" type="number" min="0.01" step="0.01" /></label><label>费用角色<select id="flow-accrual-role"><option value="operating_expense">经营费用</option><option value="cost_of_sales">销售成本/项目直接成本</option><option value="finance_cost">财务费用</option><option value="other_expense">其他费用</option></select></label><label>折算汇率<input id="flow-accrual-fx" type="number" min="0" step="0.000001" placeholder="1 原币 = ? ${safe(context.functionalCurrency)}；同币可留空" /></label><label>交易对手<input id="flow-accrual-counterparty" /></label><label>游戏/项目<input id="flow-accrual-project" /></label><label class="checkbox-line"><input id="flow-accrual-reverse" type="checkbox" checked /> 下月自动冲回</label><label class="wide">证据（分号分隔）<textarea id="flow-accrual-evidence" placeholder="合同；订单；服务进度；验收记录"></textarea></label><div class="profile-gap wide"><strong>${safe(context.functionalCurrency)} 本位币 · ${safe(context.accountingBasis)}</strong><span>系统会生成本月暂估与下月冲回候选，不会绕过会计复核或主体账簿批准。</span></div></div>`,{kind:'accrual',entity:context.entityId,functionalCurrency:context.functionalCurrency})}
function openAllocationForm(transactionId,type,targetId){const transaction=(state.businessFlows?.bank_transactions||[]).find(x=>x.id===transactionId),suggested=Number(transaction?.suggested_match?.suggested_allocation_amount||0),remaining=Number(transaction?.remaining_amount??transaction?.amount??0),defaultAmount=suggested>0?Math.min(suggested,remaining):remaining,requests=(state.businessFlows?.payment_request_records||[]).filter(item=>item.status==='已批准'&&item.target_type===type&&item.target_id===targetId&&item.currency===transaction?.currency),authorization=requests[0]?.id||'';openFlowModal('确认银行核销','资金核对',`<div class="form-grid"><label>银行流水<input value="${safe(transaction?.counterparty||transactionId)}" disabled /></label><label>本次核销金额<input id="flow-allocation-amount" type="number" min="0.01" max="${remaining}" step="0.01" value="${defaultAmount}" /></label><label class="wide">剩余可核销<input value="${fmt(remaining,transaction?.currency)}" disabled /></label><label class="wide">核销说明<input id="flow-allocation-note" value="按金额、币种、交易对手和摘要确认" /></label><label class="wide">已批准付款申请（支出必选）<select id="flow-allocation-auth"><option value="">请选择系统内授权</option>${requests.map(item=>`<option value="${safe(item.id)}" ${item.id===authorization?'selected':''}>${safe(item.id)} · ${fmt(item.amount,item.currency)} · ${safe(item.approval?.actor||'已批准')}</option>`).join('')}</select></label><label class="wide">尾差原因（如有）<input id="flow-allocation-difference" /></label></div>`,{kind:'allocation',transactionId,type,targetId})}
async function submitFlowAction(){const a=state.flowAction;if(!a)return;let endpoint='',body={actor:'财务工作台用户',idempotency_key:a.idempotencyKey,entity_id:el('flow-entity')?.value||state.opsEntityId||''};if(a.kind==='expense'){if(!a.entity)return toast('请先选择报销所属法律主体');endpoint='/api/expense-claim';body={...body,entity_id:a.entity,claimant:el('flow-expense-claimant').value,claim_date:el('flow-expense-date').value,amount:Number(el('flow-expense-amount').value),currency:el('flow-expense-currency').value,project:el('flow-expense-project').value,category:el('flow-expense-category').value,purpose:el('flow-expense-purpose').value,evidence:evidenceList(el('flow-expense-evidence').value)}}
else if(a.kind==='asset'){endpoint='/api/asset-card';body={...body,entity_id:a.entity,name:el('flow-asset-name').value,asset_type:el('flow-asset-type').value,acquisition_date:el('flow-asset-date').value,original_cost:Number(el('flow-asset-cost').value),currency:el('flow-asset-currency').value,useful_months:Number(el('flow-asset-months').value),residual_value:Number(el('flow-asset-residual').value||0),fx_rate:el('flow-asset-fx').value?Number(el('flow-asset-fx').value):null,project:el('flow-asset-project').value,vendor:el('flow-asset-vendor').value,evidence:evidenceList(el('flow-asset-evidence').value)}}
else if(a.kind==='accrual'){endpoint='/api/accrual';body={...body,entity_id:a.entity,period:el('flow-accrual-period').value,description:el('flow-accrual-description').value,amount:Number(el('flow-accrual-amount').value),currency:el('flow-accrual-currency').value,expense_role:el('flow-accrual-role').value,fx_rate:el('flow-accrual-fx').value?Number(el('flow-accrual-fx').value):null,counterparty:el('flow-accrual-counterparty').value,project:el('flow-accrual-project').value,evidence:evidenceList(el('flow-accrual-evidence').value),auto_reverse:el('flow-accrual-reverse').checked}}
else if(a.kind==='payment'){endpoint='/api/payment-request';body={...body,target_type:a.type,target_id:a.targetId,amount:Number(el('flow-payment-amount').value),period:el('flow-payment-period').value,purpose:el('flow-payment-purpose').value,evidence:evidenceList(el('flow-payment-evidence').value),prepayment:el('flow-payment-prepay').checked,bank_account_id:el('flow-payment-bank-account')?.value||''}}
else{const transaction=(state.businessFlows?.bank_transactions||[]).find(x=>x.id===a.transactionId),auth=el('flow-allocation-auth').value.trim();if(transaction?.direction==='支出'&&!auth)return toast('支出核销必须选择系统内已批准的付款申请');endpoint='/api/cash-allocation';body={...body,transaction_id:a.transactionId,target_type:a.type,target_id:a.targetId,amount:Number(el('flow-allocation-amount').value),note:el('flow-allocation-note').value,authorization_reference:auth,difference_reason:el('flow-allocation-difference').value}}if(!state.hasPersistentData)return toast('演示数据仅用于查看流程；导入正式台账后才能提交资金动作');try{const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw new Error(data.error);closeFlowModal();toast(data.idempotent_replay?'网络重试已返回原结果，没有重复创建':'已提交并保留主体、证据与审计记录');state.businessFlows=null;state.financeOps=null;await loadBusinessFlows();await loadAgentWorkspace(true)}catch(e){toast(e.message||'事项提交失败')}}
const renderBusinessFlowsWithoutDecisionActions=renderBusinessFlows;renderBusinessFlows=function(){const result=renderBusinessFlowsWithoutDecisionActions(),entityId=el('flow-entity')?.value||'',requests=state.businessFlows?.payment_request_records||[],claims=state.businessFlows?.expense_claim_records||[];if(entityId){el('payment-request-list').innerHTML=requests.map(x=>flowRow({title:x.purpose||x.target_id,meta:`${x.requested_by||''} · ${x.period||''}`,amount:x.amount,currency:x.currency,status:x.status,detail:(x.blockers||[]).join('；')||x.agent_recommendation,action:x.status==='待批准'?`<button class="text-button" data-flow-payment-decision="${safe(x.id)}">审批</button>`:''})).join('')||'<div class="empty-state">还没有付款申请</div>';el('expense-claim-list').innerHTML=claims.map(x=>flowRow({title:`${x.claimant} · ${x.category}`,meta:`${x.claim_date} · ${x.project}`,amount:x.approved_amount||x.amount,currency:x.currency,status:x.status,detail:(x.blockers||[]).join('；')||x.purpose,action:x.status==='待审批'?`<button class="text-button" data-flow-expense-decision="${safe(x.id)}">审批</button>`:x.status==='已批准待付款'?`<button class="text-button" data-flow-payment="expense" data-target="${safe(x.id)}">申请付款</button>`:''})).join('')||'<div class="empty-state">还没有费用报销</div>';el('payment-request-list').querySelectorAll('[data-flow-payment-decision]').forEach(button=>button.onclick=()=>openPaymentDecisionForm(button.dataset.flowPaymentDecision));el('expense-claim-list').querySelectorAll('[data-flow-expense-decision]').forEach(button=>button.onclick=()=>openExpenseDecisionForm(button.dataset.flowExpenseDecision));el('expense-claim-list').querySelectorAll('[data-flow-payment]').forEach(button=>button.onclick=()=>openPaymentForm('expense',button.dataset.target))}return result};
function openPaymentDecisionForm(requestId){const item=(state.businessFlows?.payment_request_records||[]).find(row=>row.id===requestId);if(!item)return toast('找不到付款申请');openFlowModal('审批付款申请','独立复核',`<div class="form-grid"><label>申请人<input value="${safe(item.requested_by||'')}" disabled /></label><label>金额<input value="${fmt(item.amount,item.currency)}" disabled /></label><label>决定<select id="flow-decision"><option>批准</option><option>退回</option><option>取消</option></select></label><label>审批人<input id="flow-decision-actor" placeholder="不得与申请人相同" /></label><label class="wide">决定依据<textarea id="flow-decision-rationale" placeholder="说明验收、发票、收款账户与资金安排的核对结果"></textarea></label></div>`,{kind:'payment_decision',requestId})}
function openExpenseDecisionForm(claimId){const item=(state.businessFlows?.expense_claim_records||[]).find(row=>row.id===claimId);if(!item)return toast('找不到报销单');openFlowModal('审批费用报销','独立复核',`<div class="form-grid"><label>报销人<input value="${safe(item.claimant||'')}" disabled /></label><label>申请金额<input value="${fmt(item.amount,item.currency)}" disabled /></label><label>决定<select id="flow-decision"><option>批准</option><option>退回</option></select></label><label>批准金额<input id="flow-approved-amount" type="number" min="0.01" step="0.01" value="${Number(item.amount||0)}" /></label><label>审批人<input id="flow-decision-actor" placeholder="不得与报销人或提交人相同" /></label><label class="wide">决定依据<textarea id="flow-decision-rationale" placeholder="说明用途、归属、票据与预算的核对结果"></textarea></label></div>`,{kind:'expense_decision',claimId})}
const submitFlowActionWithoutMoneyDecisions=submitFlowAction;submitFlowAction=async function(){const action=state.flowAction;if(!['payment_decision','expense_decision'].includes(action?.kind))return submitFlowActionWithoutMoneyDecisions();const endpoint=action.kind==='payment_decision'?'/api/payment-decision':'/api/expense-decision',body={entity_id:el('flow-entity')?.value||'',actor:el('flow-decision-actor').value.trim(),decision:el('flow-decision').value,rationale:el('flow-decision-rationale').value.trim()};if(action.kind==='payment_decision')body.request_id=action.requestId;else{body.claim_id=action.claimId;body.approved_amount=Number(el('flow-approved-amount').value)};try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await response.json();if(!response.ok)throw new Error(data.error);closeFlowModal();state.businessFlows=null;await loadBusinessFlows();await loadAgentWorkspace(true);toast(body.decision==='批准'?'已完成独立审批并保留审计记录':'已退回并保留决定依据')}catch(error){toast(error.message||'审批提交失败')}};
async function loadCompanyProfile(){try{const r=await fetch('/api/company-profile'),data=await r.json();if(!r.ok)throw new Error(data.error);state.companyProfile=data.profile;state.profileGaps=data.gaps||[];renderCompanyProfile()}catch(e){toast(e.message||'财务档案读取失败')}}
function renderCompanyProfile(){const p=state.companyProfile;if(!p)return;el('profile-company-name').value=p.company_name||'';el('profile-credit-code').value=p.credit_code||'';el('profile-city').value=p.registered_city||'';el('profile-currency').value=p.base_currency||'CNY';el('profile-standard').value=p.accounting_standard||'小企业会计准则';el('profile-close-days').value=p.close_target_days||7;el('profile-vat-type').value=p.vat_taxpayer_type||'待配置';el('profile-vat-frequency').value=p.vat_filing_frequency||'待配置';el('profile-cit-frequency').value=p.cit_filing_frequency||'季度';el('profile-cit-method').value=p.cit_collection_method||'查账征收';el('profile-provider').value=p.external_accountant?.provider||'';el('profile-contact').value=p.external_accountant?.contact||'';el('profile-threshold').value=p.review_policy?.high_confidence_threshold??0.92;el('profile-materiality').value=p.review_policy?.materiality_cny??1000;el('profile-opening-cash').value=p.cash_planning?.opening_cash_cny??'';el('profile-minimum-cash').value=p.cash_planning?.minimum_buffer_cny??100000;const fxPeriod=state.opsPeriod||availablePeriods()[0]||new Date().toISOString().slice(0,7),rates=p.fx_policy?.month_end_rates?.[fxPeriod]||{};el('profile-fx-period').value=fxPeriod;el('profile-fx-source').value=p.fx_policy?.source||'';el('profile-usd-rate').value=rates.USD??'';el('profile-hkd-rate').value=rates.HKD??'';el('profile-asset-period').value=fxPeriod;el('profile-asset-attestation').value=p.asset_policy?.monthly_attestation?.[fxPeriod]||'';el('profile-gaps').innerHTML=state.profileGaps.length?state.profileGaps.map(g=>`<div class="profile-gap"><strong>${g.name}</strong><span>${g.reason}</span></div>`).join(''):'<div class="profile-gap"><strong>关键配置已完整</strong><span>Agent 可以根据当前档案生成月结和税务任务；交易级证据仍需逐笔核验。</span></div>'}
function collectCompanyProfile(){const old=state.companyProfile||{},fxPeriod=el('profile-fx-period').value.trim(),rates={...((old.fx_policy?.month_end_rates||{})[fxPeriod]||{})},assetPeriod=el('profile-asset-period').value.trim(),assetAttestation=el('profile-asset-attestation').value;if(el('profile-usd-rate').value!=='')rates.USD=Number(el('profile-usd-rate').value);if(el('profile-hkd-rate').value!=='')rates.HKD=Number(el('profile-hkd-rate').value);return{...old,company_name:el('profile-company-name').value.trim(),credit_code:el('profile-credit-code').value.trim(),registered_city:el('profile-city').value.trim(),base_currency:'CNY',accounting_standard:el('profile-standard').value,close_target_days:Number(el('profile-close-days').value),vat_taxpayer_type:el('profile-vat-type').value,vat_filing_frequency:el('profile-vat-frequency').value,cit_filing_frequency:el('profile-cit-frequency').value,cit_collection_method:el('profile-cit-method').value,external_accountant:{...(old.external_accountant||{}),provider:el('profile-provider').value.trim(),contact:el('profile-contact').value.trim()},review_policy:{...(old.review_policy||{}),high_confidence_threshold:Number(el('profile-threshold').value),materiality_cny:Number(el('profile-materiality').value)},cash_planning:{...(old.cash_planning||{}),opening_cash_cny:el('profile-opening-cash').value===''?null:Number(el('profile-opening-cash').value),minimum_buffer_cny:Number(el('profile-minimum-cash').value)},fx_policy:{...(old.fx_policy||{}),source:el('profile-fx-source').value.trim(),month_end_rates:{...(old.fx_policy?.month_end_rates||{}),[fxPeriod]:rates}},asset_policy:{...(old.asset_policy||{}),monthly_attestation:{...(old.asset_policy?.monthly_attestation||{}),[assetPeriod]:assetAttestation}}}}
const renderCompanyProfileBase=renderCompanyProfile;
renderCompanyProfile=function(){renderCompanyProfileBase();const p=state.companyProfile;if(p&&el('profile-sh-vat-pilot'))el('profile-sh-vat-pilot').value=p.tax_policy?.shanghai_vat_pilot_status||'待确认'};
const collectCompanyProfileBase=collectCompanyProfile;
collectCompanyProfile=function(){const profile=collectCompanyProfileBase();profile.tax_policy={...(profile.tax_policy||{}),shanghai_vat_pilot_status:el('profile-sh-vat-pilot')?.value||'待确认'};return profile};
async function saveCompanyProfile(){try{const r=await fetch('/api/company-profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile:collectCompanyProfile()})}),data=await r.json();if(!r.ok)throw new Error(data.error);state.companyProfile=data.profile;state.profileGaps=data.gaps||[];state.financeOps=null;updateCompanyContext(state.companyProfile);renderCompanyProfile();toast('公司财务档案已保存，规则将在后续任务中复用')}catch(e){toast(e.message||'财务档案保存失败')}}
async function uploadInvoices(files){if(!files.length)return;const form=new FormData();[...files].forEach(f=>form.append('files',f));form.append('purchases',JSON.stringify(state.procurement?.records||[]));el('loading').classList.add('show');try{const r=await fetch('/api/invoice-import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);state.invoices=data;state.financeOps=null;renderInvoices();toast(`已识别 ${data.summary.count} 张发票，${data.summary.exception_count} 张存在异常或未查验`)}catch(e){toast(e.message||'发票台账导入失败')}finally{el('loading').classList.remove('show');el('invoice-input').value=''}}
function renderInvoices(){const data=state.invoices;if(!data){el('invoice-metrics').innerHTML=[['发票数量','—','等待导入'],['价税合计','—','按票种和用途核对'],['采购匹配','—','PO/金额/供应商'],['异常/未查验','—','不得直接入账']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');return}const s=data.summary;el('invoice-metrics').innerHTML=[['发票数量',s.count,`${s.matched_count} 张匹配采购`],['价税合计',fmt(s.total_amount,'CNY'),`税额 ${fmt(s.tax_amount,'CNY')}`],['待查验',s.unverified_count,'查验通过后才能入账'],['异常发票',s.exception_count,'含重复、红冲或勾稽异常']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');el('invoice-table').innerHTML=data.records.map(r=>`<tr><td><strong>${r.invoice_number}</strong><br><small>${r.invoice_date||'日期待补'} · ${r.invoice_type}</small></td><td>${r.seller_name}<br><small>${r.seller_tax_id_masked}</small></td><td>${r.item}<br><small>${r.project}</small></td><td class="numeric">${moneyOrPending(r.amount_ex_tax)}</td><td class="numeric">${moneyOrPending(r.tax_amount)}</td><td class="numeric">${moneyOrPending(r.total_amount)}</td><td>${r.purchase_match?`<span class="status ok">${Math.round(r.purchase_match.score*100)}%</span><br><small>${r.purchase_match.target}</small>`:'<span class="status pending">待匹配</span>'}</td><td>${r.verification_status}<br><small>${r.booking_status} · ${r.deduction_status}</small></td><td>${r.anomalies.length?`<span class="status error">${r.anomalies.join('；')}</span>`:`<span class="status pending">${r.status}</span>`}</td></tr>`).join('')}
async function uploadPayroll(files){if(!files.length)return;const entityId=state.opsEntityId||state.selectedTaxEntityId;if(!entityId){toast('工资表属于法定财务资料，请先选择法律主体');return}const form=new FormData();form.append('files',files[0]);form.append('period',state.opsPeriod||availablePeriods()[0]||new Date().toISOString().slice(0,7));form.append('entity_id',entityId);el('loading').classList.add('show');try{const r=await fetch('/api/payroll-import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);state.payroll=data;state.financeOps=null;renderPayroll();toast(data.jurisdiction==='CN'?`已完成 ${data.summary.employee_count} 人工资与累计预扣个税试算`:`已导入 ${data.summary.employee_count} 人当地 payroll 结果，待核对法定扣款与雇主成本`)}catch(e){toast(e.message||'工资表导入失败')}finally{el('loading').classList.remove('show');el('payroll-input').value=''}}
function renderPayroll(){const data=state.payroll;if(!data){el('payroll-metrics').innerHTML=[['员工人数','—','匿名展示'],['应发工资','—','等待导入'],['法定扣款','—','按主体规则'],['雇主总成本','—','含雇主供款与征费']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');return}const s=data.summary,c=data.currency==='MIXED'?'CNY':data.currency||'CNY',isCn=data.jurisdiction==='CN';el('payroll-metrics').innerHTML=[['员工人数',s.employee_count,`${s.exception_count} 人需复核`],['应发工资',fmt(s.gross_salary,c),data.period],[isCn?'个税试算':'代扣税与员工扣款',fmt(isCn?s.calculated_iit:(s.withholding_tax+s.employee_deductions),c),isCn?'累计预扣法':'当地 payroll 导入'],['雇主总成本',fmt(s.total_employer_cost||s.gross_salary,c),isCn?'不含未导入单位承担项':`雇主供款/征费 ${fmt((s.employer_contributions||0)+(s.employer_levies||0),c)}`]].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');el('payroll-table').innerHTML=data.records.map(r=>`<tr><td>${r.employee_masked}</td><td>${r.department}<br><small>${r.project||'非研发/项目待补'}</small></td><td class="numeric">${moneyOrPending(r.gross_salary)}</td><td class="numeric">${moneyOrPending(r.employee_deductions??((r.social_security||0)+(r.housing_fund||0)))}</td><td class="numeric">${moneyOrPending(r.withholding_tax??r.calculated_iit)}</td><td class="numeric">${moneyOrPending(r.net_salary)}</td><td class="numeric">${moneyOrPending(r.total_employer_cost||r.gross_salary)}<br><small>${r.payroll_basis==='IMPORTED_LOCAL_PAYROLL'?'当地结果':pct(r.rd_ratio)}</small></td><td>${r.anomalies.length?`<span class="status error">${r.anomalies.join('；')}</span>`:`<span class="status pending">${r.status}</span>`}</td></tr>`).join('')}
async function uploadPlanning(files){if(!files.length)return;const form=new FormData();[...files].forEach(f=>form.append('files',f));el('loading').classList.add('show');try{const r=await fetch('/api/planning-import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);toast(`已识别 ${data.summary.line_count} 条预算/预测明细`);await loadPlanning()}catch(e){toast(e.message||'预算预测导入失败')}finally{el('loading').classList.remove('show');el('planning-input').value=''}}
async function loadPlanning(){if(state.hasPersistentData===false&&state.planning){renderPlanning();return}const scenario=el('planning-scenario')?.value||'基准',entityId=state.opsEntityId||defaultOpsEntityId();try{const r=await fetch(`/api/planning?scenario=${encodeURIComponent(scenario)}&period=${encodeURIComponent(state.opsPeriod||'')}&entity_id=${encodeURIComponent(entityId)}`),data=await r.json();if(!r.ok)throw new Error(data.error);state.planning=data;renderPlanning()}catch(e){toast(e.message||'滚动预测生成失败')}}
function renderPlanning(){const p=state.planning;if(!p)return;const last=p.forecast[p.forecast.length-1]||{},runway=p.runway_months==null?'未触发':`${p.runway_months}个月`,currency=p.functional_currency||'CNY',opening=p.opening_cash??p.opening_cash_cny,buffer=p.minimum_buffer??p.minimum_buffer_cny??0;el('planning-metrics').innerHTML=[['预测起点现金',opening==null?'待补':fmt(opening,currency),p.as_of_period],['现金跑道',runway,p.buffer_breach_period?`缓冲线 ${p.buffer_breach_period} 跌破`:'未跌破缓冲线'],['未付采购承诺',fmt(p.unpaid_purchase_commitments,currency),'来自采购台账'],['预测期末现金',last.ending_cash==null?'待补':fmt(last.ending_cash,currency),`${p.forecast.length}个月后`]].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');const scale=Math.max(1,...p.forecast.flatMap(x=>[x.inflows,x.outflows,Math.abs(x.ending_cash||0)]));el('cash-forecast').innerHTML=p.forecast.map(x=>`<div class="cash-row"><span>${x.period}</span><div class="cash-bars"><i class="inflow" style="width:${Math.max(1,x.inflows/scale*100)}%" title="流入 ${fmt(x.inflows,currency)}"></i><i class="outflow" style="width:${Math.max(1,x.outflows/scale*100)}%" title="流出 ${fmt(x.outflows,currency)}"></i></div><strong class="${x.ending_cash!=null&&x.ending_cash<buffer?'negative':''}">${x.ending_cash==null?'待补期初现金':fmt(x.ending_cash,currency)}</strong></div>`).join('');el('planning-recommendations').innerHTML=p.recommendations.map(x=>`<div class="planning-action"><span class="status ${x.severity==='高'||x.severity==='阻塞'?'error':'ok'}">${x.severity}</span><div><strong>${x.title}</strong><p>Agent 建议：${x.recommendation}</p><small>选择利弊：${x.tradeoff}</small></div></div>`).join('');el('variance-table').innerHTML=p.variance.length?p.variance.map(x=>`<tr><td>${x.period}</td><td>${x.category}</td><td>${x.direction}</td><td class="numeric">${fmt(x.budget,currency)}</td><td class="numeric">${fmt(x.actual,currency)}</td><td class="numeric">${fmt(x.variance,currency)}</td><td><span class="status ${x.favorable?'ok':'error'}">${x.favorable?'有利':'不利'}</span></td></tr>`).join(''):'<tr><td colspan="7">导入预算后，系统会和已有结算、采购及工资实际数比较。</td></tr>'}
async function loadBp(force=false){const period=el('bp-period')?.value||state.bp?.period||state.opsPeriod||'',scenario=el('bp-scenario')?.value||'基准';if(state.bp&&state.hasPersistentData===false){renderBp();return}if(state.bp&&!force&&(!period||period===state.bp.period)){renderBp();return}try{const r=await fetch(`/api/bp?period=${encodeURIComponent(period)}&scenario=${encodeURIComponent(scenario)}`),data=await r.json();if(!r.ok)throw new Error(data.error);state.bp=data;if(!state.opsPeriod&&data.period)state.opsPeriod=data.period;renderBp()}catch(e){toast(e.message||'经营分析生成失败')}}
function renderMarketingFinance(m){if(!m)return;const totals=m.totals||{},owned=m.boundary?.owned||[],notOwned=m.boundary?.not_owned||[];el('marketing-boundary').innerHTML=`<div><strong>财务负责</strong><span>${owned.join(' · ')}</span></div><div><strong>投手负责</strong><span>${notOwned.join(' · ')}</span></div><p>${m.guardrail}</p>`;el('marketing-metrics').innerHTML=[['媒体消耗',totals.media_spend?fmt(totals.media_spend,'CNY'):'待导入','媒体口径，不直接作为财务费用'],['财务投放费',totals.finance_spend?fmt(totals.finance_spend,'CNY'):'待勾稽','订单/验收/预提/发票口径'],['对账差额',fmt(totals.reconciliation_gap||0,'CNY'),'超过重要性先对账，不先谈 ROI'],['付费获客成本',totals.payer_cpa==null?'待付费用户':fmt(totals.payer_cpa,'CNY'),'LTV、回收期与目标门槛尚需 cohort 数据']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');el('marketing-finance-table').innerHTML=(m.projects||[]).map(x=>`<tr><td><strong>${x.project_name}</strong></td><td class="numeric">${x.media_spend?fmt(x.media_spend,'CNY'):'—'}</td><td class="numeric">${x.finance_spend?fmt(x.finance_spend,'CNY'):'—'}</td><td class="numeric ${Math.abs(x.reconciliation_gap)>1000?'negative':''}">${fmt(x.reconciliation_gap,'CNY')}</td><td class="numeric">${x.payer_cpa==null?'—':fmt(x.payer_cpa,'CNY')}</td><td class="numeric">${x.gross_roas==null?'—':`${x.gross_roas.toFixed(2)}x`}</td><td><small>${x.incrementality_status}<br>${x.ltv_status}</small></td><td><span class="status ${x.gate_status.includes('对账')?'error':'pending'}">${x.gate_status}</span><br><small>${x.gate_reason}</small></td></tr>`).join('')||'<tr><td colspan="8">本期没有可评估的投放数据。导入媒体消耗、获客结果及财务支出后，Agent 才会生成资源门控建议。</td></tr>'}
function renderBp(){const b=state.bp;if(!b)return;const periodSelect=el('bp-period');if(periodSelect){const current=b.period;periodSelect.innerHTML=(b.available_periods||[]).slice().reverse().map(p=>`<option>${p}</option>`).join('');periodSelect.value=current}const t=b.totals||{},chg=b.change_vs_previous||{},p=b.planning||{},last=p.forecast?.[p.forecast.length-1]||{},costComplete=(b.data_quality?.payroll_record_count||0)>0&&(b.data_quality?.purchase_record_count||0)>0;el('bp-demo-note').innerHTML=b.demo_mode?'<div class="decision-banner warning"><div><strong>当前是示例分析</strong><span>只有结算数据，缺少真实项目、人力和采购台账；结果仅用于体验页面，不能据此做经营决策。</span></div></div>':'';el('bp-metrics').innerHTML=[['本期收入',fmt(t.revenue,'CNY'),chg.revenue==null?'缺少可比上期':`较上期 ${chg.revenue>=0?'+':''}${fmt(chg.revenue,'CNY')}`],['项目投入',costComplete?fmt(t.direct_cost,'CNY'):'待补全',costComplete?`人力 ${fmt(t.payroll,'CNY')} · 外包/投放 ${fmt(t.outsourcing+t.marketing,'CNY')}`:'工资或采购台账尚不完整'],['直接贡献',costComplete?fmt(t.contribution,'CNY'):'暂不下结论',costComplete?`贡献率 ${pct(t.contribution_margin)}`:'可先看收入，不能当完整项目利润'],['现金安全',p.opening_cash_cny==null?'待补现金':p.buffer_breach_period?`${p.buffer_breach_period} 预警`:'基准情景安全',p.opening_cash_cny==null?'导入银行余额后计算跑道':`期末预测 ${fmt(last.ending_cash,'CNY')}`]].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');const variance=(b.variance||[]).slice().sort((x,y)=>Math.abs(y.variance)-Math.abs(x.variance));const projects=(b.projects||[]).filter(x=>x.project_code!=='公司公共/待分配').slice().sort((x,y)=>y.revenue-x.revenue);const driverRows=[];if(chg.revenue!=null)driverRows.push({tone:chg.revenue>=0?'ok':'error',title:`收入较上期${chg.revenue>=0?'增加':'减少'} ${fmt(Math.abs(chg.revenue),'CNY')}`,detail:projects.length?`${projects[0].project_name} 本期收入 ${fmt(projects[0].revenue,'CNY')}，是当前最大项目。`:'需要补项目映射后定位来源'});if(variance.length)driverRows.push({tone:variance[0].favorable?'ok':'error',title:`${variance[0].category}预算差异 ${fmt(variance[0].variance,'CNY')}`,detail:`实际 ${fmt(variance[0].actual,'CNY')} / 预算 ${fmt(variance[0].budget,'CNY')}，${variance[0].favorable?'对结果有利':'需要检查时点或超支原因'}`});if(b.data_quality?.kpi_record_count)driverRows.push({tone:'pending',title:'经营指标已接入',detail:'需要解释收入变化时，可继续问Agent查看活跃、付费、留存或投放驱动。'});else driverRows.push({tone:'pending',title:'经营原因暂不能拆解',detail:'缺少经营KPI，目前只能看到财务结果，无法区分活跃、付费率、ARPPU和投放影响。'});el('analysis-drivers').innerHTML=driverRows.map(x=>`<div class="analysis-item"><span class="status ${x.tone}">${x.tone==='ok'?'正向':x.tone==='error'?'关注':'待补'}</span><div><strong>${x.title}</strong><p>${x.detail}</p></div></div>`).join('');el('analysis-cash').innerHTML=p.opening_cash_cny==null?'<strong>现金跑道尚不能计算</strong><p>缺少真实银行余额或预测起点现金。先补余额，再看未来12个月最低点和未付采购承诺。</p><button class="text-button" data-go="banking">去资金模块补数据 →</button>':`<strong>${p.buffer_breach_period?`${p.buffer_breach_period} 跌破最低缓冲`:'基准情景未触发硬预警'}</strong><p>起点 ${fmt(p.opening_cash_cny,'CNY')} · 未付采购 ${fmt(p.unpaid_purchase_commitments,'CNY')} · 预测期末 ${fmt(last.ending_cash,'CNY')}</p><button class="text-button" data-go="planning">查看完整现金预测 →</button>`;el('analysis-cash').querySelectorAll('[data-go]').forEach(button=>button.onclick=()=>setView(button.dataset.go));el('bp-messages').innerHTML=(b.management_messages||[]).slice(0,4).map(x=>`<div class="planning-action"><span class="status ${['高','阻塞'].includes(x.severity)?'error':x.severity==='机会'?'ok':'pending'}">${x.severity}</span><div><strong>${x.title}</strong><p>${x.finding}</p><p class="recommendation">建议：${x.recommendation}</p><small>${x.tradeoff}</small></div></div>`).join('');renderMarketingFinance(b.marketing_finance);el('bp-project-table').innerHTML=(b.projects||[]).map(x=>`<tr><td><strong>${x.project_name}</strong><br><small>${x.project_code} · ${x.stage}</small></td><td class="numeric">${fmt(x.revenue,'CNY')}</td><td class="numeric">${fmt(x.direct_cost,'CNY')}</td><td class="numeric ${x.contribution<0?'negative':''}">${costComplete?fmt(x.contribution,'CNY'):'待补全'}</td><td>${x.unconverted?.length?`<span class="status error">${x.unconverted.length}项待折算</span>`:x.evidence_count?`<span class="status ${costComplete?'ok':'pending'}">${costComplete?'可分析':'成本待补'}</span>`:'<span class="status pending">缺实际数</span>'}</td></tr>`).join('')||'<tr><td colspan="5">先到“数据与配置”建立项目，再导入结算、工资和采购。</td></tr>'}
async function uploadKpis(files){if(!files.length)return;const form=new FormData();[...files].forEach(f=>form.append('files',f));el('loading').classList.add('show');try{const r=await fetch('/api/kpi-import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);state.bp=null;toast(`已导入 ${data.quality.record_count} 条经营KPI，发现 ${data.quality.issue_count} 个质量问题`);await loadBp(true)}catch(e){toast(e.message||'经营KPI导入失败')}finally{el('loading').classList.remove('show');el('kpi-input').value=''}}
function onboardingScope(){const entity=el('onboarding-entity'),period=el('onboarding-period'),entities=state.onboarding?.entities||state.boxContext?.entities||[];if(entity&&!entity.options.length)entity.innerHTML=entities.map(x=>`<option value="${safe(x.id)}">${safe(x.name)} · ${safe(x.id)}</option>`).join('');if(entity&&!entity.value)entity.value=state.companyProfile?.entity_id||entities[0]?.id||'cn_studio';if(period&&!period.value)period.value=state.opsPeriod||new Date().toISOString().slice(0,7);return{entity_id:entity?.value||'cn_studio',period:period?.value||state.opsPeriod||''}}
async function loadOnboarding(){try{const scope=onboardingScope(),r=await fetch(`/api/onboarding?entity_id=${encodeURIComponent(scope.entity_id)}&period=${encodeURIComponent(scope.period)}`),data=await r.json();if(!r.ok)throw new Error(data.error);state.onboarding=data;renderOnboarding()}catch(e){toast(e.message||'上线检查读取失败')}}
function renderFirstClose(){const f=state.onboarding?.first_close;if(!f)return;el('first-close-status').textContent=f.ready_for_shadow_close?'可进入 Shadow Close':`${f.blockers.length} 项阻塞`;el('first-close-status').className=`status ${f.ready_for_shadow_close?'ok':'error'}`;el('first-close-summary').innerHTML=`<div><strong>${safe(f.entity_name)}</strong><span>${safe(f.entity_id)} · ${safe(f.period)} · 资料覆盖 ${f.readiness_score}%</span></div><div><strong>Shadow Close ${safe(f.shadow_close.status)}</strong><span>Tax Pack ${safe(f.tax_readiness.status)} · ${safe(f.tax_readiness.note)}</span></div><p>${safe(f.control_note)}</p>`;el('first-close-grid').innerHTML=(f.items||[]).map(x=>`<article class="first-close-item"><div><span class="status ${x.status==='完成'||x.status==='不适用'?'ok':x.status==='阻塞'?'error':'pending'}">${safe(x.status)}</span><strong>${safe(x.name)}</strong></div><p>${safe(x.why)}</p><small>${safe(x.evidence)}<br>下一步：${safe(x.next_action)}</small>${x.can_declare_not_applicable&&x.status!=='完成'?`<details><summary>${x.status==='不适用'?'调整不适用声明':'确实没有这类业务？'}</summary><select data-onboarding-decision="${safe(x.domain)}"><option>${x.status==='不适用'?'撤销不适用':'本期不适用'}</option></select><textarea data-onboarding-rationale="${safe(x.domain)}" rows="2" placeholder="至少8个字说明业务事实"></textarea><input data-onboarding-evidence="${safe(x.domain)}" placeholder="证据引用，例如：本期采购清单；工资表负责人确认"/><button class="button ghost" data-onboarding-declare="${safe(x.domain)}">提交复核声明</button></details>`:''}</article>`).join('');el('first-close-grid').querySelectorAll('[data-onboarding-declare]').forEach(button=>button.onclick=()=>submitOnboardingDeclaration(button.dataset.onboardingDeclare))}
function renderOnboarding(){const o=state.onboarding;if(!o)return;const mq=o.master_quality||{},kq=o.kpi_quality||{};onboardingScope();el('onboarding-metrics').innerHTML=[['上线就绪度',`${o.readiness_score}%`,`${o.blockers.length} 个必需项待补`],['BP可用',o.ready_for_bp?'是':'否',o.ready_for_bp?'项目、渠道、组织与实际数已具备':'先补项目、渠道、组织与历史实际'],['关账底座',o.ready_for_close?'是':'否',o.ready_for_close?'主体、期初与质量检查已具备':'不代表当前期间已经可关账'],['主数据/KPI',`${mq.usable_count||0} / ${kq.usable_count||0}`,`${mq.issue_count||0}+${kq.issue_count||0} 个质量问题`]].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');renderFirstClose();el('onboarding-steps').innerHTML=(o.steps||[]).map(x=>`<div class="onboarding-step"><span class="step-number">${x.id}</span><div><strong>${x.name}</strong><p>${x.why}</p><small>${x.evidence}<br>下一步：${x.next_action}</small></div><span class="status ${x.status==='完成'?'ok':x.status==='待补'?'error':'pending'}">${x.status}</span></div>`).join('');const issues=[...(mq.issues||[]),...(kq.issues||[])];el('onboarding-quality').innerHTML=issues.length?issues.slice(0,30).map(x=>`<div class="audit-item"><span class="status error">需处理</span><div><strong>${x}</strong><small>修复后重新上传相同编码即可更新。</small></div></div>`).join(''):'<div class="empty-state">当前主数据与KPI未发现映射错误；仍需按月维护。</div>';el('onboarding-order').innerHTML=(o.import_order||[]).map(x=>`<tr><td>${x.order}</td><td><strong>${x.sheet}</strong></td><td>${x.destination}</td><td>${x.mode}</td></tr>`).join('')}
async function submitOnboardingDeclaration(domain){const scope=onboardingScope(),decision=window.document.querySelector(`[data-onboarding-decision="${domain}"]`)?.value,rationale=window.document.querySelector(`[data-onboarding-rationale="${domain}"]`)?.value.trim()||'',evidence=(window.document.querySelector(`[data-onboarding-evidence="${domain}"]`)?.value||'').split(/[；;]+/).map(x=>x.trim()).filter(Boolean);try{const r=await fetch('/api/onboarding-declaration',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...scope,domain,decision,rationale,evidence,actor:'财务复核人'})}),data=await r.json();if(!r.ok)throw new Error(data.error);toast('首月上线声明已记录并保留审计依据');await loadOnboarding();await loadAgentWorkspace(true)}catch(error){toast(error.message||'上线声明保存失败')}}
async function uploadOnboarding(files){if(!files.length)return;const scope=onboardingScope(),form=new FormData();[...files].forEach(f=>form.append('files',f));form.append('entity_id',scope.entity_id);el('loading').classList.add('show');try{const r=await fetch('/api/onboarding-import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);state.onboarding=data.onboarding;state.bp=null;toast(`已按 ${scope.entity_id} 导入 ${data.master_imported} 条主数据、${data.kpi_imported} 条经营KPI`);renderOnboarding();await loadWorkspace()}catch(e){toast(e.message||'前置上线包导入失败')}finally{el('loading').classList.remove('show');el('onboarding-input').value=''}}
function renderQa(){const suggestions=['这个月哪个游戏最赚钱？','为什么本月收入变化？','预算哪里超了？','现金还能撑多久？','要不要给表现最好的项目加投放？','哪些成本还没分到项目？','本月能不能关账？','海外收入税务要怎么处理？'];el('qa-suggestions').innerHTML=suggestions.map(x=>`<button data-question="${x}">${x}</button>`).join('');el('qa-suggestions').querySelectorAll('button').forEach(b=>b.onclick=()=>{el('qa-question').value=b.dataset.question;askQa()});renderQaHistory()}
function renderQaHistory(){const h=el('qa-history');if(!state.qaHistory.length){h.innerHTML='<div class="qa-empty">可以先问：“这个月哪个游戏最赚钱？”</div>';return}h.innerHTML=state.qaHistory.map(x=>`<article class="qa-answer"><div class="qa-question">${x.question}</div><div class="qa-answer-head"><span class="status ${x.confidence>=.8?'ok':x.confidence>=.5?'pending':'error'}">置信度 ${Math.round(x.confidence*100)}%</span><strong>${x.period||'当前期间'}${x.demo_mode?' · 示例数据':''}</strong></div><h3>${x.answer}</h3><p class="recommendation">Agent 倾向：${x.recommendation}</p>${x.evidence?.length?`<div class="evidence-grid">${x.evidence.map(e=>`<div><span>${e.metric}</span><strong>${e.value}</strong><small>${e.source}</small></div>`).join('')}</div>`:''}${x.options?.length?`<div class="option-grid">${x.options.map(o=>`<div class="option ${o.recommended?'recommended':''}"><strong>${o.recommended?'推荐 · ':''}${o.name}</strong><span>好处：${o.benefit}</span><span>代价：${o.cost}</span></div>`).join('')}</div>`:''}${x.data_gaps?.length?`<div class="qa-gaps"><strong>结论缺口</strong>${x.data_gaps.join('；')}</div>`:''}${x.next_actions?.length?`<div class="qa-actions"><strong>下一步</strong>${x.next_actions.map(a=>`<span>${a}</span>`).join('')}</div>`:''}<small class="qa-scope">${x.scope}</small></article>`).join('')}
async function askQa(){const input=el('qa-question'),question=input.value.trim();if(!question)return;el('qa-submit').disabled=true;try{const r=await fetch('/api/qa',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,period:state.bp?.period||state.opsPeriod||'',scenario:el('bp-scenario')?.value||'基准'})}),data=await r.json();if(!r.ok)throw new Error(data.error);state.qaHistory.unshift(data);input.value='';renderQaHistory()}catch(e){toast(e.message||'财务问答失败')}finally{el('qa-submit').disabled=false}}
async function loadSample(scenario=el('sample-scenario')?.value||'group'){el('loading').classList.add('show');try{const r=await fetch(`/api/sample?scenario=${encodeURIComponent(scenario)}`),data=await r.json();if(!r.ok)throw new Error(data.error);state.payload=data.settlements;state.procurement=data.procurement;state.banking=data.banking;state.invoices=data.invoices;state.payroll=data.payroll;state.openingBalances=data.opening_balances||[];state.planning=data.planning;state.bp=data.bp;state.financeOps=data.finance_ops;state.businessFlows=data.business_flows||null;state.companyProfile=data.company_profile;state.profileGaps=[];state.opsPeriod=data.bp?.period||data.finance_ops?.period||'';state.hasPersistentData=false;updateCompanyContext(state.companyProfile);render();renderProcurement();renderBanking();renderInvoices();renderPayroll();renderPlanning();renderBp();if(state.view==='flows')await loadBusinessFlows();if(['close','vouchers','ledger','tax','review'].includes(state.view))renderFinanceOps();toast(`已载入${data.scenario}`)}catch(e){toast(e.message||'示例载入失败，请确认服务已启动')}finally{el('loading').classList.remove('show')}}
function settlementPayload(rows){const currencies={};rows.forEach(r=>{const c=r.currency||'未知',x=currencies[c]||(currencies[c]={gross:0,settlement:0,net:0,refunds:0,count:0});x.gross+=Number(r.gross||0);x.settlement+=Number(r.settlement_amount||0);x.net+=Number(r.net_receivable||0);x.refunds+=Number(r.refunds||0);x.count++});return{records:rows,summary:{record_count:rows.length,file_count:new Set(rows.map(r=>r.source_file).filter(Boolean)).size,exception_count:rows.filter(r=>r.status==='异常').length,pending_count:rows.filter(r=>r.status==='待确认').length,currencies}}}
async function loadWorkspace(){el('loading').classList.add('show');try{const r=await fetch('/api/workspace'),data=await r.json();if(!r.ok)throw new Error(data.error);state.periodStates=data.period_states||{};state.hasPersistentData=Boolean(data.has_persistent_data);if(state.hasPersistentData){const d=data.datasets||{};state.payload=settlementPayload(d.settlements||[]);state.procurement=d.purchases?.length?{records:d.purchases,summary:{record_count:d.purchases.length,po_count:new Set(d.purchases.map(x=>x.po_number).filter(Boolean)).size,ordered_amount:d.purchases.reduce((a,x)=>a+Number(x.ordered_amount||0),0),accepted_amount:d.purchases.reduce((a,x)=>a+Number(x.accepted_amount||0),0),invoice_amount:d.purchases.reduce((a,x)=>a+Number(x.invoice_amount||0),0),paid_amount:d.purchases.reduce((a,x)=>a+Number(x.paid_amount||0),0),uninvoiced_exposure:d.purchases.reduce((a,x)=>a+Math.max(0,Number(x.accepted_amount||0)-Number(x.invoice_amount||0)),0),unpaid_exposure:d.purchases.reduce((a,x)=>a+Math.max(0,Number(x.invoice_amount||0)-Number(x.paid_amount||0)),0),exception_count:d.purchases.filter(x=>x.anomalies?.length).length}}:null;state.banking=d.bank_transactions?.length?{transactions:d.bank_transactions,summary:{count:d.bank_transactions.length,receipt_amount:d.bank_transactions.filter(x=>x.direction==='收入').reduce((a,x)=>a+Number(x.amount||0),0),payment_amount:d.bank_transactions.filter(x=>x.direction==='支出').reduce((a,x)=>a+Number(x.amount||0),0),high_confidence_count:d.bank_transactions.filter(x=>x.status==='高置信匹配').length,pending_count:d.bank_transactions.filter(x=>x.status!=='高置信匹配').length,currencies:[...new Set(d.bank_transactions.map(x=>x.currency||'未知'))]}}:null;state.invoices=d.invoices?.length?{records:d.invoices,summary:{count:d.invoices.length,amount_ex_tax:d.invoices.reduce((a,x)=>a+Number(x.amount_ex_tax||0),0),tax_amount:d.invoices.reduce((a,x)=>a+Number(x.tax_amount||0),0),total_amount:d.invoices.reduce((a,x)=>a+Number(x.total_amount||0),0),matched_count:d.invoices.filter(x=>x.purchase_match).length,exception_count:d.invoices.filter(x=>x.anomalies?.length).length,unverified_count:d.invoices.filter(x=>!['已查验','查验通过','有效'].includes(x.verification_status)).length}}:null;state.payroll=d.payroll_rows?.length?{records:d.payroll_rows,period:data.periods?.[0]||'',summary:{employee_count:d.payroll_rows.length,gross_salary:d.payroll_rows.reduce((a,x)=>a+Number(x.gross_salary||0),0),calculated_iit:d.payroll_rows.reduce((a,x)=>a+Number(x.calculated_iit||0),0),net_salary:d.payroll_rows.reduce((a,x)=>a+Number(x.net_salary||0),0),rd_salary_candidate:d.payroll_rows.reduce((a,x)=>a+Number(x.rd_salary_candidate||0),0),exception_count:d.payroll_rows.filter(x=>x.anomalies?.length).length}}:null;state.openingBalances=d.opening_balances||[];state.businessFlows=null;state.opsPeriod=data.periods?.[0]||'';render();toast('已恢复持久化财务台账')}else{await loadSample()}await loadAudit()}catch(e){toast('工作区读取失败，改用示例数据');await loadSample()}finally{el('loading').classList.remove('show')}}
async function loadRevenueClose(force=false){if(!state.hasPersistentData){state.revenueClose={candidates:[],summary:{candidate_count:0,ready_for_review:0,blocked:0,rejected:0,released:0,released_by_currency:[]},guardrail:'导入正式渠道账单后，系统先生成候选，不直接形成应收。'};renderRevenueClose();return}if(state.revenueClose&&!force){renderRevenueClose();return}try{const r=await fetch(`/api/revenue-close?entity_id=${encodeURIComponent(state.opsEntityId)}`),data=await r.json();if(!r.ok)throw new Error(data.error);state.revenueClose=data;renderRevenueClose()}catch(error){toast(error.message||'收入核对读取失败')}}
function revenueTone(value){return value==='released'?'ok':value==='blocked'||value==='rejected'?'error':'pending'}
function renderRevenueClose(){const data=state.revenueClose||{candidates:[],summary:{}},s=data.summary||{},list=el('revenue-close-list');if(!list)return;const released=(s.released_by_currency||[]).map(x=>`${x.currency} ${new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(x.released_receivable)}`).join(' · ')||'—';el('revenue-close-metrics').innerHTML=[['待业务确认',s.ready_for_review||0,'合同与公式已勾稽'],['阻塞待补',s.blocked||0,'不会形成应收'],['已释放应收',s.released||0,released],['已退回',s.rejected||0,'保留复核历史']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value ${String(x[1]).length>20?'small-value':''}">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');list.innerHTML=(data.candidates||[]).map(row=>{const c=row.contract_match||{},r=row.commercial_reconciliation||{},ready=row.release_status==='ready_for_review',blockers=row.release_blockers||[],formula=r.expected_amount==null?`${safe(r.basis||'结算公式')} · 缺少计算输入`:`${safe(r.basis)} = ${fmt(r.expected_amount,row.currency)}；账单 ${fmt(r.declared_amount,row.currency)}；差额 ${fmt(r.delta,row.currency)}`;return`<article class="revenue-close-card ${ready?'reviewable':''}"><header><div><span class="status ${revenueTone(row.release_status)}">${safe(row.status)}</span><h3>${safe(row.game)} · ${safe(row.channel)}</h3><small>${safe(row.period)} · ${safe(row.entity_id)} · ${safe(row.platform)} · ${safe(row.currency)}</small></div><strong>${fmt(row.net_receivable,row.currency)}</strong></header><div class="revenue-close-facts"><div><span>渠道规则</span><strong>${safe(c.rule_name||'未匹配')}</strong><small>${safe(c.contract_reference||c.reason||'需维护渠道规则')}</small></div><div><span>结算重算</span><strong>${r.passed?'勾稽通过':'仍有差异'}</strong><small>${formula}</small></div><div><span>系统建议</span><strong>${ready?'建议批准形成应收':'先补证据，不建议放行'}</strong><small>${safe(row.agent_judgement?.boundary||'商业应收与会计确认分开。')}</small></div></div>${blockers.length?`<div class="revenue-close-blockers">${blockers.map(x=>`<span>${safe(x)}</span>`).join('')}</div>`:''}${ready?`<div class="revenue-close-review"><input data-revenue-rationale="${safe(row.id)}" placeholder="确认依据，例如：已核对协议、后台和本期结算口径"/><button class="button ghost" data-revenue-decision="退回" data-revenue-id="${safe(row.id)}">退回补资料</button><button class="button primary" data-revenue-decision="批准" data-revenue-id="${safe(row.id)}">确认并形成应收</button></div>`:''}</article>`}).join('')||`<div class="empty-state"><strong>当前主体没有待处理收入账单</strong><span>${safe(data.guardrail||'导入账单后先核对，不会直接形成应收。')}</span></div>`;list.querySelectorAll('[data-revenue-decision]').forEach(button=>button.onclick=()=>reviewRevenueClose(button.dataset.revenueId,button.dataset.revenueDecision))}
async function reviewRevenueClose(id,decision){const rationale=document.querySelector(`[data-revenue-rationale="${id}"]`)?.value.trim()||'';if(rationale.length<4)return toast('请填写至少4个字的确认依据');if(decision==='批准'&&!window.confirm('确认渠道规则、账单和结算重算一致，并将该候选释放为应收？'))return;try{const r=await fetch('/api/revenue-close-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entity_id:state.opsEntityId,candidate_ids:[id],decision,rationale,actor:'财务工作台用户'})}),data=await r.json();if(!r.ok)throw new Error(data.error);state.revenueClose=data;await loadWorkspace();state.revenueClose=data;renderRevenueClose();state.financeOps=null;state.businessFlows=null;toast(decision==='批准'?'已形成应收；下一步可匹配银行回款并复核收入会计政策':'已退回并保留复核依据')}catch(error){toast(error.message||'收入结算复核失败')}}
async function upload(files){if(!files.length)return;if(files.length>1)return autoImport(files);state.pendingFile=files[0];const form=new FormData();form.append('files',files[0]);el('loading').classList.add('show');try{const r=await fetch('/api/discover',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);state.discovery=data.workbooks[0];openMapping(state.discovery)}catch(e){toast(e.message||'识别失败')}finally{el('loading').classList.remove('show');el('file-input').value=''}}
async function autoImport(files){const form=new FormData();[...files].forEach(f=>form.append('files',f));el('loading').classList.add('show');try{const r=await fetch('/api/import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);state.payload=data;state.financeOps=null;state.opsPeriod='';render();setView('overview');toast(`已自动解析 ${data.summary.file_count} 份对账单`)}catch(e){toast(e.message||'导入失败')}finally{el('loading').classList.remove('show');el('file-input').value=''}}
function selectedSheet(){return state.discovery?.sheets.find(s=>s.name===el('mapping-sheet').value)}
function selectedCandidate(){const sheet=selectedSheet();return sheet?.candidates.find(c=>String(c.row)===el('mapping-header').value)||sheet?.candidates[0]}
function openMapping(discovery){const sheets=discovery.sheets.filter(s=>s.candidates.length);el('mapping-sheet').innerHTML=sheets.map(s=>`<option>${s.name}</option>`).join('');el('mapping-sheet').value=discovery.selected?.sheet||sheets[0]?.name||'';fillHeaderRows();const template=discovery.matched_template;if(template){applyTemplate(template);toast(`已匹配模板：${template.name}`)}else{renderFieldMapping();el('template-name').value=''}el('mapping-modal').classList.add('show');el('mapping-modal').setAttribute('aria-hidden','false')}
function closeMapping(){el('mapping-modal').classList.remove('show');el('mapping-modal').setAttribute('aria-hidden','true');state.pendingFile=null;state.discovery=null}
function fillHeaderRows(){const sheet=selectedSheet(),preferred=state.discovery?.selected?.header_row;el('mapping-header').innerHTML=(sheet?.candidates||[]).map(c=>`<option value="${c.row}">第 ${c.row} 行 · 识别 ${c.score} 个字段</option>`).join('');if(preferred&&sheet?.candidates.some(c=>c.row===preferred))el('mapping-header').value=preferred;renderFieldMapping()}
function renderFieldMapping(mappingOverride){const candidate=selectedCandidate();if(!candidate)return;const headers=candidate.headers||[],mapping=mappingOverride||candidate.mapping||{};const options=headers.map((h,i)=>`<option value="${i}">${String.fromCharCode(65+i%26)}列 · ${h||'(空)'}</option>`).join('');el('field-mapping').innerHTML=state.discovery.fields.map(f=>`<div class="field-row ${f.key==='period'?'required':''}"><label>${f.label}</label><select data-field="${f.key}"><option value="">不映射</option>${options}</select></div>`).join('');el('field-mapping').querySelectorAll('select').forEach(s=>{if(mapping[s.dataset.field]!=null)s.value=String(mapping[s.dataset.field])});el('header-preview').innerHTML=headers.filter(Boolean).map((h,i)=>`<span class="preview-chip" title="${h}">${i+1}. ${h}</span>`).join('')}
function applyTemplate(template){const c=template.config||{},d=c.defaults||{};if(c.sheet&&state.discovery.sheets.some(s=>s.name===c.sheet))el('mapping-sheet').value=c.sheet;fillHeaderRows();if(c.header_row)el('mapping-header').value=String(c.header_row);renderFieldMapping(c.mapping);el('template-name').value=template.name||'';el('default-scope').value=d.scope||'海外';el('default-game').value=d.game||'';el('default-platform').value=d.platform||'';el('default-channel').value=d.channel||'';el('default-currency').value=d.currency||'';el('default-share-rate').value=d.share_rate??'';el('formula-mode').value=c.formula_mode||'declared'}
function collectConfig(){const mapping={};el('field-mapping').querySelectorAll('select').forEach(s=>{if(s.value!=='')mapping[s.dataset.field]=Number(s.value)});return{sheet:el('mapping-sheet').value,header_row:Number(el('mapping-header').value),mapping,defaults:{scope:el('default-scope').value,game:el('default-game').value.trim(),platform:el('default-platform').value.trim(),channel:el('default-channel').value.trim(),currency:el('default-currency').value.trim().toUpperCase(),share_rate:el('default-share-rate').value===''?null:Number(el('default-share-rate').value)},formula_mode:el('formula-mode').value}}
async function configuredImport(){const config=collectConfig();if(config.mapping.period==null){toast('请先映射账期字段');return}if(!['gross','share_base','settlement','net'].some(k=>config.mapping[k]!=null)){toast('至少映射一个金额字段');return}el('loading').classList.add('show');try{if(el('save-template').checked){const candidate=selectedCandidate(),name=el('template-name').value.trim()||`${config.defaults.game||'未命名'} · ${config.defaults.channel||'结算模板'}`;const sr=await fetch('/api/templates',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,fingerprint:candidate.fingerprint,config})}),saved=await sr.json();if(!sr.ok)throw new Error(saved.error)}const form=new FormData();form.append('files',state.pendingFile);form.append('config',JSON.stringify(config));const r=await fetch('/api/configured-import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.error);state.payload=data;state.financeOps=null;state.opsPeriod='';closeMapping();render();setView('overview');toast(`已按统一口径生成 ${data.summary.record_count} 条结算记录`)}catch(e){toast(e.message||'配置导入失败')}finally{el('loading').classList.remove('show')}}
