const pipelineDecisionLabel=value=>({approved:'已批准',rejected:'已拒绝',needs_more_evidence:'待补证据',pending:'待复核'}[value]||value||'待复核');
const pipelineDecisionTone=value=>value==='approved'?'ok':value==='rejected'?'error':'pending';
const PIPELINE_SCHEDULE_LABELS={disabled:'未启用',due:'到期可运行',retry_due:'重试到期',retry_wait:'等待重试',retry_exhausted:'重试耗尽',leased:'执行租约中',completed:'本期已完成',missed_window:'已错过窗口',blocked_configuration:'配置阻塞',blocked_non_retryable:'不可自动重试'};
