  el('pipeline-schedule-summary').textContent=!scheduleEnvelope?'读取中':scheduleEnvelope.configured?`${scheduleJobs.length} 个任务`:'未配置';el('pipeline-schedule-summary').className=`status ${scheduleEnvelope?.configured?'pending':'error'}`;
  el('pipeline-schedule-list').innerHTML=!scheduleEnvelope?'<div class="skeleton-block">正在计算到期与重试状态…</div>':!scheduleEnvelope.configured?`<div class="pipeline-schedule-empty"><strong>尚未配置调度计划</strong><span>通过服务端环境变量 <code>${safe(scheduleEnvelope.environment_reference||'OPC_FINANCE_PIPELINE_SCHEDULE_FILE')}</code> 引用经审批的计划。Box 不会自行安装 cron。</span></div>`:scheduleJobs.length?scheduleJobs.map(job=>`<article class="pipeline-schedule-job"><header><div><strong>${safe(job.job_id)}</strong><code>${safe(job.pipeline_id)} · ${safe(job.entity_id)}</code></div><span class="status ${pipelineScheduleTone(job.status)}">${safe(PIPELINE_SCHEDULE_LABELS[job.status]||job.status)}</span></header><div class="pipeline-schedule-facts"><span><small>本期计划时间</small><strong>${pipelineDate(job.scheduled_for_local)}</strong></span><span><small>执行 / 告警</small><strong>${safe(job.operator)} / ${safe(job.alert_owner)}</strong></span><span><small>尝试 / 租约</small><strong>${safe(job.history?.attempt_count||0)} / ${job.history?.active_claim?'占用中':'空闲'}</strong></span></div>${job.blockers?.length?`<p>${job.blockers.map(safe).join('；')}</p>`:''}<footer>审批：${safe(job.approved_by||'未审批')} · request 不在控制面返回 · 本页不会触发运行</footer></article>`).join(''):'<div class="pipeline-schedule-empty"><strong>计划中没有任务</strong><span>从编译产物的 pipeline-schedule-template.json 开始配置。</span></div>';
  el('pipeline-review-summary').textContent=tasks.length?`${tasks.length} 个门`:'无待办';el('pipeline-review-summary').className=`status ${tasks.length?'pending':'ok'}`;
  const reviewDisabled=!integrityOk||!canReview||state.pipelineControlBusy;
  el('pipeline-review-queue').innerHTML=groupPipelineTasks().length?groupPipelineTasks().map(([attemptId,items])=>{const first=items[0];return `<article class="pipeline-review-group"><header><div><strong>${safe(first.pipeline_id)}</strong><small>${safe(first.entity_id||'主体待确认')} · ${safe(pipelineShort(attemptId,10))} · ${pipelineDate(first.recorded_at)}</small></div><span class="status ${first.run_status==='ready'?'ok':'error'}">${first.run_status==='ready'?'运行就绪':'运行阻塞'}</span></header><div class="pipeline-gates">${items.map(task=>`<section class="pipeline-gate"><div class="pipeline-gate-head"><div><strong>${safe(PIPELINE_GATE_LABELS[task.gate]||task.gate)}</strong><code>${safe(task.gate)}</code></div><span class="status ${pipelineDecisionTone(task.current_decision)}">${safe(pipelineDecisionLabel(task.current_decision))}</span></div><label>决定依据<textarea rows="2" maxlength="1000" data-pipeline-rationale="${safe(attemptId)}:${safe(task.gate)}" placeholder="说明已检查什么，以及为什么作出这个决定"></textarea></label><label>证据引用（可选）<input maxlength="200" data-pipeline-evidence="${safe(attemptId)}:${safe(task.gate)}" placeholder="例如 evidence://contract/2026-08" /></label><div class="pipeline-review-actions"><button class="button primary" data-pipeline-decision="approved" data-attempt-id="${safe(attemptId)}" data-gate="${safe(task.gate)}" ${reviewDisabled?'disabled':''}>批准此门</button><button class="button ghost" data-pipeline-decision="needs_more_evidence" data-attempt-id="${safe(attemptId)}" data-gate="${safe(task.gate)}" ${reviewDisabled?'disabled':''}>要求补证据</button><button class="button danger" data-pipeline-decision="rejected" data-attempt-id="${safe(attemptId)}" data-gate="${safe(task.gate)}" ${reviewDisabled?'disabled':''}>拒绝</button></div></section>`).join('')}</div></article>`}).join(''):`<div class="empty-state">${runs.length?'当前没有未解决的财务任务流复核门。':'还没有记录财务任务流运行尝试。可先通过 CLI 或 API 运行并记录一个候选结果。'}</div>`;
  if(!canReview&&integrityOk)el('pipeline-review-queue').insertAdjacentHTML('afterbegin','<div class="pipeline-permission-note">当前身份可以查看，但没有 reviewer 权限，复核按钮已关闭。</div>');
