  el('pipeline-attempt-list').innerHTML=runs.length?runs.map(run=>`<button class="pipeline-attempt ${state.selectedPipelineAttempt?.attempt_id===run.attempt_id?'selected':''}" data-pipeline-attempt="${safe(run.attempt_id)}"><span class="pipeline-attempt-main"><strong>${safe(run.pipeline_id)}</strong><small>${safe(run.entity_id||'主体待确认')} · ${pipelineDate(run.recorded_at)}<br>执行：${safe(run.actor||'—')} · 尝试 #${safe(run.attempt_number_for_idempotency_key||1)}</small></span><span><b class="status ${run.status==='ready'?'ok':'error'}">${run.status==='ready'?'就绪':'阻塞'}</b><b class="status ${pipelineDecisionTone(run.review_status==='approved'?'approved':run.review_status==='rejected'?'rejected':'pending')}">${safe(pipelineDecisionLabel(run.review_status==='pending_review'?'pending':run.review_status))}</b></span></button>`).join(''):'<div class="empty-state">暂无运行尝试。</div>';
  renderPipelineAttemptDetail();
