function renderPipelineAttemptDetail(){const run=state.selectedPipelineAttempt,target=el('pipeline-attempt-detail');if(!run){target.innerHTML='<div class="empty-state">选择一条运行尝试，查看连接器、服务阶段与复核历史。</div>';return}const reviews=run.review_history||[],connectors=run.connector_batches||[],stages=run.service_stages||[];target.innerHTML=`<div class="pipeline-detail-summary"><div><span>财务任务流</span><strong>${safe(run.pipeline_id)}</strong></div><div><span>法律主体</span><strong>${safe(run.entity_id||'待确认')}</strong></div><div><span>运行状态</span><strong>${safe(run.status)}</strong></div><div><span>复核状态</span><strong>${safe(run.review_status)}</strong></div><div><span>尝试 ID</span><strong>${safe(run.attempt_id)}</strong></div><div><span>运行指纹</span><strong title="${safe(run.result_fingerprint)}">${safe(pipelineShort(run.result_fingerprint,18))}</strong></div></div><div class="pipeline-detail-columns"><section><h3>连接器批次</h3>${connectors.length?connectors.map(item=>`<div class="pipeline-detail-row"><strong>${safe(item.connector_id)}</strong><small>${safe(item.batch_id||'无批次号')} · ${safe(item.record_count??'—')} 条 · ${item.quality_ready?'质量通过':'质量未通过'}</small></div>`).join(''):'<p class="pipeline-detail-empty">没有连接器摘要</p>'}</section><section><h3>服务阶段</h3>${stages.length?stages.map(item=>`<div class="pipeline-detail-row"><strong>${safe(item.stage)} · ${safe(item.service_id)}</strong><small>${safe((item.entity_ids||[]).join('、')||'无主体')} · ${safe(item.action_class||'—')} · ${item.ready?'就绪':'未就绪'}</small></div>`).join(''):'<p class="pipeline-detail-empty">没有服务阶段摘要</p>'}</section><section><h3>复核历史</h3>${reviews.length?reviews.map(item=>`<div class="pipeline-detail-row"><strong>${safe(PIPELINE_GATE_LABELS[item.gate]||item.gate)} · ${safe(pipelineDecisionLabel(item.decision))}</strong><small>${safe(item.actor)} · ${pipelineDate(item.reviewed_at)}<br>${safe(item.rationale)}${item.evidence_references?.length?`<br>证据：${item.evidence_references.map(safe).join('、')}`:''}</small></div>`).join(''):'<p class="pipeline-detail-empty">还没有复核记录</p>'}</section></div><div class="pipeline-boundary-note">安全边界：原始请求、完整运行结果和密钥均不在控制台运行台账中持久化；“候选可释放”也不是付款、入账、报税或其他外部授权。</div>`}
async function loadPipelineAttempt(attemptId){try{const data=await pipelineJson(`/api/box/pipeline-runs/${encodeURIComponent(attemptId)}`);state.selectedPipelineAttempt=data.run;renderPipelineControl()}catch(error){toast(error.message||'运行尝试详情读取失败')}}
async function loadPipelineControl(){if(state.pipelineControlBusy)return;state.pipelineControlBusy=true;state.pipelineControlError='';renderPipelineControl();const endpoints=[['runs','/api/box/pipeline-runs?limit=50'],['queue','/api/box/pipeline-review-queue?limit=100'],['integrity','/api/box/pipeline-run-integrity'],['schedule','/api/box/pipeline-schedule'],['auth','/api/auth/whoami']];const results=await Promise.allSettled(endpoints.map(([,url])=>pipelineJson(url)));results.forEach((result,index)=>{const key=endpoints[index][0];if(result.status==='fulfilled'){if(key==='runs')state.pipelineRuns=result.value.runs||[];if(key==='queue')state.pipelineReviewTasks=result.value.review_tasks||[];if(key==='integrity')state.pipelineIntegrity=result.value.integrity;if(key==='schedule')state.pipelineSchedule=result.value;if(key==='auth')state.pipelineAuth=result.value}else{if(key==='integrity')state.pipelineIntegrity=null;if(key==='schedule')state.pipelineSchedule=null;state.pipelineControlError=state.pipelineControlError||result.reason.message}});state.pipelineControlBusy=false;renderPipelineControl();if(state.pipelineControlError)toast(state.pipelineControlError)}
async function submitPipelineReview(button){const attemptId=button.dataset.attemptId,gate=button.dataset.gate,decision=button.dataset.pipelineDecision,key=`${attemptId}:${gate}`,rationale=document.querySelector(`[data-pipeline-rationale="${key}"]`)?.value.trim()||'',evidence=document.querySelector(`[data-pipeline-evidence="${key}"]`)?.value.trim()||'';if(!state.pipelineIntegrity?.valid)return toast('完整性验证未通过，不能提交复核');if(!pipelineCanReview())return toast('当前身份没有 reviewer 权限');if(!rationale)return toast('请填写复核决定依据');if((decision==='approved'||decision==='rejected')&&!window.confirm(decision==='approved'?'确认批准此控制门？这可能使运行成为候选可释放状态，但不会执行外部动作。':'确认拒绝此控制门？该决定会写入追加式复核历史。'))return;state.pipelineControlBusy=true;renderPipelineControl();try{await pipelineJson('/api/box/pipeline-run-reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({attempt_id:attemptId,gate,decision,actor:'财务工作台复核人',rationale,evidence_references:evidence?[evidence]:[]})});toast(`${PIPELINE_GATE_LABELS[gate]||gate} 已记录“${pipelineDecisionLabel(decision)}”`);state.pipelineControlBusy=false;await loadPipelineControl();if(state.selectedPipelineAttempt?.attempt_id===attemptId)await loadPipelineAttempt(attemptId)}catch(error){state.pipelineControlBusy=false;renderPipelineControl();toast(error.status===403?'当前身份没有 reviewer 权限':error.message||'财务任务流复核失败')}}
function pipelineTemplates(){return state.pipelineCatalog?.request_templates?.templates||[]}
function pipelineDefinition(pipelineId){return (state.pipelineCatalog?.pipelines||[]).find(item=>item.pipeline_id===pipelineId)}
function selectPipelineTemplate(templateId){const template=pipelineTemplates().find(item=>item.template_id===templateId);if(!template)return;state.selectedPipelineTemplateId=templateId;state.pipelineDraftText=JSON.stringify(template.request,null,2);state.pipelinePreflight=null;renderPipelineLaunch()}
function renderPipelineLaunch(){const catalog=state.pipelineCatalog,pipelines=catalog?.pipelines||[],templates=pipelineTemplates(),selected=templates.find(item=>item.template_id===state.selectedPipelineTemplateId),canOperate=pipelineCanOperate(),auth=state.pipelineAuth;el('pipeline-operator-identity').textContent=auth?`${auth.principal?.principal_id||'未知身份'} · ${(auth.principal?.roles||[]).join(' / ')||'无角色'}`:'身份读取失败';el('pipeline-launch-metrics').innerHTML=[['可执行财务任务流',pipelines.filter(x=>x.implementation_status==='executable').length,'由当前 Pack 和 provider 共同决定'],['请求起点',templates.length,'按法律主体生成'],['复核门',[...new Set(pipelines.flatMap(x=>x.review_gates||[]))].length,'运行后独立决定'],['运行权限',canOperate?'可运行':'只读',canOperate?'operator / admin':'仍可执行只读预检']].map(item=>`<div class="metric"><div class="label">${safe(item[0])}</div><div class="value ${item[1]==='只读'?'small-value':''}">${safe(item[1])}</div><div class="foot">${safe(item[2])}</div></div>`).join('');el('pipeline-catalog-summary').textContent=`${pipelines.length} 个财务任务流 · ${templates.length} 个请求起点`;el('pipeline-catalog-list').innerHTML=templates.length?templates.map(template=>{const definition=pipelineDefinition(template.pipeline_id)||{};return`<button class="pipeline-catalog-item ${template.template_id===state.selectedPipelineTemplateId?'selected':''}" data-pipeline-template="${safe(template.template_id)}"><span class="status ${definition.implementation_status==='executable'?'ok':'error'}">${definition.implementation_status==='executable'?'可执行':'缺 provider'}</span><strong>${safe(definition.display_name||template.pipeline_id)}</strong><small>${safe(template.pipeline_id)}${template.entity_id?` · ${safe(template.entity_id)}`:' · 管理范围'}<br>${(definition.review_gates||[]).length} 道复核门 · 不执行外部动作</small></button>`}).join(''):'<div class="empty-state">当前 Pack 组合没有可执行财务任务流。</div>';el('pipeline-catalog-list').querySelectorAll('[data-pipeline-template]').forEach(button=>button.onclick=()=>selectPipelineTemplate(button.dataset.pipelineTemplate));const title=el('pipeline-editor-title'),editor=el('pipeline-request-editor'),requirements=el('pipeline-template-requirements'),status=el('pipeline-editor-status'),preflight=el('pipeline-preflight-result'),reset=el('pipeline-template-reset'),check=el('pipeline-preflight-button'),record=el('pipeline-record-button');if(!selected){title.textContent='请求编辑器';editor.value='';editor.disabled=true;requirements.innerHTML='<div class="empty-state">选择一个请求起点。</div>';status.textContent='无模板';status.className='status pending';preflight.innerHTML='';[reset,check,record].forEach(button=>button.disabled=true);return}title.textContent=selected.pipeline_id;editor.disabled=false;editor.value=state.pipelineDraftText||JSON.stringify(selected.request,null,2);requirements.innerHTML=`<strong>运行前必须完成</strong><ol>${(selected.required_configuration||[]).map(item=>`<li>${safe(item)}</li>`).join('')}</ol><p>${safe(state.pipelineCatalog?.request_templates?.control_note||'')}</p>`;const result=state.pipelinePreflight;if(result?.ready_to_dispatch){status.textContent='预检通过';status.className='status ok'}
else if(result){status.textContent='预检阻塞';status.className='status error'}else{status.textContent='未预检';status.className='status pending'}preflight.innerHTML=result?`<div class="pipeline-preflight-card ${result.ready_to_dispatch?'ok':'blocked'}"><strong>${result.ready_to_dispatch?'可以运行候选财务任务流':'仍不能运行'}</strong><span>未读取数据源 · 未改变状态 · 未执行外部动作</span>${result.blockers?.length?`<ul>${result.blockers.map(item=>`<li>${safe(item)}</li>`).join('')}</ul>`:''}${result.placeholder_paths?.length?`<details><summary>${result.placeholder_paths.length} 个占位符位置</summary><code>${result.placeholder_paths.map(safe).join('\n')}</code></details>`:''}</div>`:'<div class="pipeline-preflight-empty">修改 JSON 后先做安全预检。</div>';reset.disabled=state.pipelineLaunchBusy;check.disabled=state.pipelineLaunchBusy;record.disabled=state.pipelineLaunchBusy||!result?.ready_to_dispatch||!canOperate;if(!canOperate)record.title='当前身份需要 operator 或 admin 权限';editor.oninput=event=>{state.pipelineDraftText=event.target.value;state.pipelinePreflight=null;status.textContent='待重新预检';status.className='status pending';record.disabled=true;preflight.innerHTML='<div class="pipeline-preflight-empty">请求已修改，请重新预检。</div>'}}
async function loadPipelineLaunch(force=false){if(state.pipelineLaunchBusy)return;if(state.pipelineCatalog&&!force){renderPipelineLaunch();return}state.pipelineLaunchBusy=true;renderPipelineLaunch();try{const [catalog,auth]=await Promise.all([pipelineJson('/api/box/pipelines'),pipelineJson('/api/auth/whoami')]);state.pipelineCatalog=catalog;state.pipelineAuth=auth;const templates=pipelineTemplates();if(!templates.some(item=>item.template_id===state.selectedPipelineTemplateId)){const preferred=templates.find(item=>item.pipeline_id.endsWith('channel_close'))||templates[0];state.selectedPipelineTemplateId=preferred?.template_id||'';state.pipelineDraftText=preferred?JSON.stringify(preferred.request,null,2):''}state.pipelinePreflight=null}catch(error){toast(error.message||'财务任务流目录读取失败')}finally{state.pipelineLaunchBusy=false;renderPipelineLaunch()}}
function parsePipelineDraft(){try{return JSON.parse(state.pipelineDraftText||el('pipeline-request-editor').value)}catch(error){toast(`请求 JSON 无法解析：${error.message}`);return null}}
async function preflightPipelineDraft(){const request=parsePipelineDraft();if(!request)return;state.pipelineLaunchBusy=true;renderPipelineLaunch();try{state.pipelinePreflight=await pipelineJson('/api/box/pipelines/preflight',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(request)});toast(state.pipelinePreflight.ready_to_dispatch?'预检通过：尚未读取数据源':'预检发现阻塞项')}catch(error){state.pipelinePreflight=null;toast(error.message||'财务任务流预检失败')}finally{state.pipelineLaunchBusy=false;renderPipelineLaunch()}}
function resetPipelineTemplate(){const template=pipelineTemplates().find(item=>item.template_id===state.selectedPipelineTemplateId);if(template){state.pipelineDraftText=JSON.stringify(template.request,null,2);state.pipelinePreflight=null;renderPipelineLaunch()}}
async function recordPipelineDraft(){if(!state.pipelinePreflight?.ready_to_dispatch)return toast('请先完成安全预检');if(!pipelineCanOperate())return toast('当前身份没有 operator 权限');const request=parsePipelineDraft();if(!request)return;if(!window.confirm('确认调用该财务任务流的 Connector 并记录候选运行？这可能读取已配置的数据源，但不会自动入账、付款或申报。'))return;state.pipelineLaunchBusy=true;renderPipelineLaunch();try{const data=await pipelineJson('/api/box/pipeline-runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:'财务工作台操作人',request})});state.selectedPipelineAttempt=data.run_record;toast('财务任务流已运行并写入秘密值安全的控制台账');state.pipelineLaunchBusy=false;setView('pipeline-control')}catch(error){state.pipelineLaunchBusy=false;renderPipelineLaunch();toast(error.status===403?'当前身份没有 operator 权限':error.message||'财务任务流运行失败')}}
