function renderPilotBusinessControlOverlay(){const data=state.pilotShadowPeriods,statusEl=el('pilot-business-control-status'),container=el('pilot-business-control-overlay');if(!statusEl||!container)return;if(!data){statusEl.textContent='读取中';statusEl.className='status pending';container.innerHTML='<div class="skeleton-block">正在组合本业务的月度控制重点…</div>';return}const overlay=data.business_control_overlay||{},models=(overlay.business_model_type_ids||[]).map(item=>CFO_BUSINESS_MODEL_LABELS[item]||item),objectives=(overlay.monthly_control_objective_type_ids||[]).map(item=>CFO_CONTROL_OBJECTIVE_LABELS[item]||item),boundaries=(overlay.source_boundary_type_ids||[]).map(item=>CFO_SOURCE_BOUNDARY_LABELS[item]||item),questions=(overlay.founder_review_question_type_ids||[]).map(item=>CFO_FOUNDER_QUESTION_LABELS[item]||item),extension=overlay.method_extension_required;statusEl.textContent=extension?'需要补方法扩展':'控制覆盖层已组合';statusEl.className=`status ${extension?'error':'ok'}`;container.innerHTML=`<article><header><div><small>当前业务模型</small><div>${models.map(item=>`<span class="pilot-domain required">${safe(item)}</span>`).join('')}</div></div><strong>${safe(objectives.length)} 项控制目标 · ${safe(boundaries.length)} 项来源边界</strong></header><div class="pilot-business-control-grid"><section><small>本月重点控制</small><ol>${objectives.map(item=>`<li>${safe(item)}</li>`).join('')}</ol></section><section class="source-boundaries"><small>数据源不能越过的边界</small><ul>${boundaries.map(item=>`<li>${safe(item)}</li>`).join('')}</ul></section><section class="founder-questions"><small>创始人复盘问题</small><ol>${questions.map(item=>`<li>${safe(item)}</li>`).join('')}</ol></section></div>${extension?'<footer>当前包含尚未映射的方法扩展；完成独立范围和完整性设计前，不应进入真实并行验证。</footer>':''}</article>`}
function renderPilotBusinessMetricCatalog(){const data=state.pilotShadowPeriods,statusEl=el('pilot-cfo-metric-status'),container=el('pilot-cfo-metric-catalog');if(!statusEl||!container)return;if(!data){statusEl.textContent='读取中';statusEl.className='status pending';container.innerHTML='<div class="skeleton-block">正在组合本业务的指标定义…</div>';return}const catalog=data.business_metric_catalog||{},definitions=catalog.metric_definitions||[],scopes=['finance_core',...(catalog.business_model_type_ids||[])];statusEl.textContent=definitions.length?`${definitions.length} 项指标定义`:'指标定义缺失';statusEl.className=`status ${definitions.length?'ok':'error'}`;const policy='<div class="pilot-cfo-metric-policy"><span class="pilot-domain required">缺输入：不可用，不填零</span><span class="pilot-domain optional">币种：显式折算前保持原币</span><span class="pilot-domain optional">聚合：比率按分子分母重算</span></div>';const groups=scopes.map(scope=>{const items=definitions.filter(item=>item.model_scope_type_id===scope);if(!items.length)return'';return`<section class="pilot-cfo-metric-group"><header><strong>${safe(CFO_METRIC_SCOPE_LABELS[scope]||scope)}</strong><small>${safe(items.length)} 项月度定义</small></header><div class="pilot-cfo-metric-grid">${items.map(item=>{const formula=item.formula||{},domains=(item.required_data_domain_ids||[]).map(domain=>CFO_METRIC_DOMAIN_LABELS[domain]||domain),operator=CFO_METRIC_OPERATOR_LABELS[formula.operator_type_id]||formula.operator_type_id,operands=(formula.operand_type_ids||[]).join(' · ');return`<article class="pilot-cfo-metric-card"><strong>${safe(CFO_METRIC_LABELS[item.metric_type_id]||item.metric_type_id)}</strong><span>${safe(CFO_METRIC_VALUE_LABELS[item.value_type_id]||item.value_type_id)} · ${safe(operator)}</span><small>必需数据域：${domains.map(safe).join(' · ')}</small><code>${safe(operands)}${formula.scale?` × ${safe(formula.scale)}`:''}</code></article>`}).join('')}</div></section>`}).join('');container.innerHTML=policy+groups}
