const confirmationAmount=item=>item?.amount?fmt(item.amount.value,item.amount.currency):'—';
const actionById=(goal,id)=>(goal?.actions||[]).find(action=>action.id===id);
const actionView=id=>({C02:'overview',C03:'overview',C04:'invoices',C05:'procurement',C06:'payroll',C07:'banking',C08:'flows',C10:'ledger',C11:'vouchers',C13:'ledger',C14:'tax',C15:'close',S01:'shadow-close',P01:'planning',A01:'bp'}[id]||'close');

async function loadAgentWorkspace(force=false){
  if(state.agentBusy&&!force)return;
  const scenario=el('sample-scenario')?.value||'group';
  try{
    const r=await fetch(`/api/agent-workspace?scenario=${encodeURIComponent(scenario)}`),data=await r.json();
    if(!r.ok)throw new Error(data.error);
    state.agentWorkspace=data;
    state.procurementWorkflow=null;
    if(data.goal?.period)state.opsPeriod=data.goal.period;
    renderAgentWorkspace();
    renderConfirmations();
    if(state.view==='procurement')await loadProcurementWorkflow(true);
  }catch(error){toast(error.message||'Agent 工作台读取失败')}
}

async function runAgent(){
  if(state.agentBusy)return;
  state.agentBusy=true;
  const button=el('run-agent-button'),scenario=el('sample-scenario')?.value||'group';
  if(button){button.disabled=true;button.textContent='正在运行…'}
  try{
    const payload={actor:'财务工作台用户',demo_scenario:scenario};
    if(state.agentWorkspace?.goal?.id&&state.agentWorkspace?.demo_scenario===scenario)payload.goal_id=state.agentWorkspace.goal.id;
    const r=await fetch('/api/agent-run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await r.json();
    if(!r.ok)throw new Error(data.error);
    state.agentWorkspace=data;
    renderAgentWorkspace();renderConfirmations();await loadDocuments();
    const auto=data.automation_run||{};
    toast(auto.completed_count?`Agent 已识别 ${auto.completed_count} 份资料并刷新全部目标`:'Agent 已刷新全部目标、异常与交付物');
  }catch(error){toast(error.message||'Agent 运行失败')}
  finally{state.agentBusy=false;if(button){button.disabled=false;button.textContent='立即运行'}}
}

function completedTitles(actions,limit=3){const titles=actions.filter(x=>x.status==='已完成').slice(0,limit).map(x=>x.title);return titles.length?titles:['等待可执行资料'];}
function pendingAction(actions){return actions.find(x=>x.status==='阻塞')||actions.find(x=>['等待确认','已批准待执行','可执行'].includes(x.status));}

function goalPortfolioRow({title,subtitle,actions,progress,progressLabel,next,deliverables,view}){
  const blocker=pendingAction(actions);
  return `<article class="portfolio-row">
    <div class="portfolio-title"><strong>${safe(title)}</strong><span>${safe(subtitle)}</span><button class="text-button" data-go="${view}">查看执行明细</button></div>
    <div class="portfolio-progress"><div><span>${safe(progressLabel)}</span><strong>${Math.round(progress*100)}%</strong></div><div class="portfolio-track"><i style="width:${Math.max(2,Math.min(100,progress*100))}%"></i></div></div>
    <div class="portfolio-cell"><small>Agent 已完成</small><p>${completedTitles(actions).map(safe).join('<br>')}</p></div>
    <div class="portfolio-cell"><small>下一步</small><p>${safe(next||blocker?.title||'持续监控并自动刷新')}</p></div>
    <div class="portfolio-cell"><small>阻塞 / 需确认</small><p class="${blocker?.status==='阻塞'?'danger-text':''}">${safe(blocker?(blocker.blockers?.[0]||blocker.title):'当前没有关键阻塞')}</p></div>
    <div class="portfolio-cell"><small>交付物证据</small><p>${deliverables.length?deliverables.slice(0,3).map(x=>`${safe(x.name)} · ${safe(x.status)}`).join('<br>'):'正在生成'}</p></div>
  </article>`;
}

function renderAgentWorkspace(){
  const workspace=state.agentWorkspace;if(!workspace)return;
  const goal=workspace.goal||{},actions=goal.actions||[],deliverables=workspace.deliverables?.items||[];
  el('agent-period').textContent=`${goal.period||'当前账期'} · ${goal.status||'执行中'}`;
  el('agent-mode').textContent=workspace.is_demo?({group:'全球管理汇总',overseas:'海外主体',domestic:'国服主体'}[workspace.demo_scenario]||'演示口径'):'真实台账';
  el('agent-mode').className=`status ${workspace.is_demo?'pending':'ok'}`;
  el('agent-scale-note').textContent=workspace.scale_principle||'';
  const closeActions=actions.filter(x=>!['P01','A01','C08'].includes(x.id)),cashAction=actionById(goal,'P01'),analysisAction=actionById(goal,'A01'),flowAction=actionById(goal,'C08');
  const closeProgress=closeActions.length?closeActions.filter(x=>x.status==='已完成').length/closeActions.length:0;
  const cashMonths=workspace.cash_safety?.next_90_days?.length||0,cashProgress=Math.min(1,cashMonths/3);
  const analysisProgress=analysisAction?.status==='已完成'?1:analysisAction?.status==='阻塞'?0:.5;
  const flowStatus=goal.business_flow_status||{},flowIssues=Number(flowStatus.overdue_receivables||0)+Number(flowStatus.pending_payments||0)+Number(flowStatus.bank_unallocated||0)+Number(flowStatus.pending_approvals||0),flowProgress=flowIssues?Math.max(.12,1-Math.min(1,flowIssues/12)):1;
  const groupScope=workspace.scope_mode==='group';
  el('goal-portfolio').innerHTML=[
    goalPortfolioRow({title:groupScope?`协调各主体完成 ${goal.period||'本期'} 月结与税务准备`:`完成 ${goal.period||'本期'} 月结与税务准备`,subtitle:groupScope?'主体分别生成凭证、法定报表与税务底稿':'收入、采购、资金、凭证、报表与税务底稿',actions:closeActions,progress:closeProgress,progressLabel:`已完成 ${closeActions.filter(x=>x.status==='已完成').length}/${closeActions.length}`,next:goal.next_focus?.title,deliverables:deliverables.filter(x=>!['P01','A01'].includes(x.action_id)),view:'close'}),
    goalPortfolioRow({title:'让本周收付款安全流转',subtitle:'应收、供应商、报销、工资与银行核销',actions:flowAction?[flowAction]:[],progress:flowProgress,progressLabel:flowIssues?`${flowIssues} 项待处理`:'资金链路正常',next:goal.operating_alerts?.[0]?.action||'持续核对到期应收和已批准付款',deliverables:deliverables.filter(x=>x.action_id==='C08'),view:'flows'}),
    goalPortfolioRow({title:'守住未来 90 天现金安全垫',subtitle:`安全垫 ${fmt(workspace.cash_safety?.minimum_buffer_cny||0,'CNY')}`,actions:cashAction?[cashAction]:[],progress:cashProgress,progressLabel:`预测覆盖 ${cashMonths}/3 个月`,next:workspace.cash_safety?.buffer_breach_period?`处理 ${workspace.cash_safety.buffer_breach_period} 安全垫缺口`:'更新应收与已承诺支出',deliverables:deliverables.filter(x=>x.action_id==='P01'),view:'planning'}),
    goalPortfolioRow({title:'解释本月游戏经营变化',subtitle:'收入、MAU、付费率、ARPPU 与项目投入',actions:analysisAction?[analysisAction]:[],progress:analysisProgress,progressLabel:analysisAction?.status||'等待数据',next:workspace.management_analysis?.proactive_insights?.[0]?.recommendation||'确认最重要的经营异常',deliverables:deliverables.filter(x=>x.action_id==='A01'),view:'bp'})
  ].join('');
  const confirmations=workspace.confirmations?.items||[];
  el('nav-confirmation-count').textContent=workspace.confirmations?.count||0;
  el('agent-confirmation-preview').innerHTML=confirmations.slice(0,4).map(item=>`<button class="preview-decision" data-confirm-jump="${safe(item.id)}"><span class="priority-dot ${agentTone(item.priority)}"></span><div><strong>${safe(item.title)}</strong><small>${item.entity_name?`${safe(item.entity_name)} · `:''}${safe(item.reason)}</small></div><div><b>${confirmationAmount(item)}</b><span class="status ${agentTone(item.status)}">${item.status==='阻塞'?'先补资料':safe(item.status)}</span></div></button>`).join('')||'<div class="empty-state">当前没有需要你确认的关键事项。</div>';
  el('agent-confirmation-preview').querySelectorAll('[data-confirm-jump]').forEach(button=>button.onclick=()=>{state.highlightConfirmation=button.dataset.confirmJump;setView('confirmations')});
  el('deliverable-summary').textContent=`已生成 ${workspace.deliverables?.generated_count||0} · 最终完成 ${workspace.deliverables?.complete_count||0}`;
  el('agent-deliverables').innerHTML=deliverables.slice(0,10).map(item=>`<tr><td><strong>${safe(item.name)}</strong><br><small>${safe(item.entity_name||'')}${item.entity_id?` · ${safe(item.entity_id)}`:''} · ${safe(item.period)}</small></td><td>${safe(item.action)}</td><td><span class="status ${agentTone(item.status)}">${safe(item.status)}</span></td><td>${safe(item.evidence_state)}</td><td><small>${safe(item.scope_note)}</small></td><td><button class="text-button" data-go="${actionView(item.action_id)}">查看</button></td></tr>`).join('')||'<tr><td colspan="6">Agent 正在生成首批交付物。</td></tr>';
  const auto=workspace.automation_run;
  el('agent-run-note').innerHTML=auto?.planned_count?`<strong>本次自动执行</strong><span>识别预览 ${auto.completed_count} 份，失败 ${auto.failed_count} 份。正式入账仍需确认。</span>`:workspace.is_demo?'<strong>当前为安全演示</strong><span>可查看完整流程；示例决定不会写入正式台账。</span>':'<strong>Agent 持续工作中</strong><span>自动处理明细，只把关键判断和资金动作交给你。</span>';
  const scope=el('agent-scope-summary'),entities=workspace.entity_workspaces||[];
  scope.innerHTML=workspace.scope_mode==='group'?`<div class="scope-head"><div><strong>全球项目打包视图</strong><span>${safe(workspace.statutory_guardrail)}</span></div><span class="status pending">${safe(workspace.elimination_policy?.status||'合并口径待配置')}</span></div><div class="entity-scope-grid">${entities.map(entity=>`<button data-entity-scope="${safe(entity.key)}"><span>${safe(entity.market)}主体</span><strong>${safe(entity.name)}</strong><small>${entity.settlement_records} 条结算 · ${safe(entity.currencies.join(' / '))} · 点击下钻</small></button>`).join('')}</div>`:'';
  scope.querySelectorAll('[data-entity-scope]').forEach(button=>button.onclick=async()=>{el('sample-scenario').value=button.dataset.entityScope;await loadSample(button.dataset.entityScope);await loadAgentWorkspace(true)});
}

function confirmationCard(item){
  const ready=Boolean(item.decision)&&item.status!=='阻塞',demo=Boolean(state.agentWorkspace?.is_demo),warnings=item.metadata?.warnings||[];
  const choices=ready&&!demo&&item.decision.method==='POST'?(item.decision.choices||[]).map(choice=>`<button class="button ${choice.includes('批准')||choice.includes('同意')||choice.includes('接受')||choice.includes('全部验收')?'primary':'ghost'}" data-decision-choice="${safe(choice)}" data-confirm-id="${safe(item.id)}">${safe(choice)}</button>`).join(''):'';
  return `<article class="confirmation-card ${state.highlightConfirmation===item.id?'highlight':''}">
    <div class="confirmation-head"><div><span class="priority-label ${agentTone(item.priority)}">${safe(item.priority)}</span><span class="domain-label">${safe(item.domain)}</span>${item.entity_id?`<span class="domain-label">${safe(item.entity_name)} · ${safe(item.entity_id)}</span>`:''}<h3>${safe(item.title)}</h3></div><div class="confirmation-amount"><strong>${confirmationAmount(item)}</strong><span class="status ${agentTone(item.status)}">${item.status==='阻塞'?'先补资料':safe(item.status)}</span></div></div>
    <div class="confirmation-grid"><div><small>为什么需要你</small><p>${safe(item.reason)}</p></div><div><small>Agent 建议</small><p>${safe(item.recommendation)}</p></div><div><small>需要谁确认</small><p>${safe(item.required_role)}</p></div></div>
    ${(item.blockers||[]).length?`<div class="blocker-strip"><strong>不能直接批准</strong><span>${item.blockers.map(safe).join('；')}</span></div>`:''}
    ${warnings.length?`<div class="warning-strip"><strong>同时关注</strong><span>${warnings.map(safe).join('；')}</span></div>`:''}
    ${ready?`<details class="confirmation-action"><summary>${demo?'查看决策要求（演示模式）':'展开处理'}</summary><div class="confirmation-form">${['procurement_request','vendor_bank_change'].includes(item.source_type)?`<label>独立确认人<input data-confirm-actor="${safe(item.id)}" placeholder="不得与申请人相同" /></label>`:''}<label>决定依据<textarea data-confirm-rationale="${safe(item.id)}" placeholder="请说明你核对了什么，以及决定依据"></textarea></label><label>证据或附件说明<input data-confirm-evidence="${safe(item.id)}" placeholder="例如：验收记录、报价页码、复核说明" /></label>${item.source_type==='vendor_bank_change'?`<label>独立核验方式<select data-confirm-verification-method="${safe(item.id)}"><option>回拨主数据联系人</option><option>银行证明核对</option><option>线下当面确认</option></select></label><label>核验记录引用<input data-confirm-verification-reference="${safe(item.id)}" placeholder="联系人及回拨时间、银行证明编号等" /></label>`:''}${['expense_claim','purchase_acceptance'].includes(item.source_type)?`<label>确认金额<input type="number" step="0.01" data-confirm-amount="${safe(item.id)}" value="${item.amount?.value||''}" /></label>`:''}<div class="confirmation-buttons">${choices||`<span>${demo?'演示模式不写入正式决定。':'请进入资料页继续处理。'}</span>`}</div></div></details>`:`<div class="blocked-next"><strong>下一步：</strong>先补齐上述事实或证据，Agent 会自动重新评估。</div>`}
  </article>`;
}

function renderConfirmations(){
  const workspace=state.agentWorkspace;if(!workspace)return;
  const queue=workspace.confirmations||{items:[]},domains=[...new Set(queue.items.map(x=>x.domain))].sort(),domain=el('confirmation-domain'),priority=el('confirmation-priority');
  if(domain){const current=domain.value;domain.innerHTML='<option value="">全部类型</option>'+domains.map(x=>`<option>${safe(x)}</option>`).join('');domain.value=current}
  const filtered=queue.items.filter(item=>(!domain?.value||item.domain===domain.value)&&(!priority?.value||item.priority===priority.value));
  const exposure=(queue.amount_exposure_by_currency||[]).map(x=>`${x.currency} ${new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(x.value)}`).join(' · ')||'无金额事项';
  if(el('confirmation-metrics'))el('confirmation-metrics').innerHTML=[['全部事项',queue.count||0,'跨资料、业务、会计与税务'],['可作决定',queue.decision_ready_count||0,'已有足够事实与证据'],['先补资料',queue.blocked_count||0,'不会显示批准动作'],['涉及金额',exposure,'不同币种不直接相加']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value ${typeof x[1]==='string'&&x[1].length>18?'small-value':''}">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');
  if(el('confirmation-list')){el('confirmation-list').innerHTML=filtered.map(confirmationCard).join('')||'<div class="empty-state">当前筛选下没有待确认事项。</div>';el('confirmation-list').querySelectorAll('[data-decision-choice]').forEach(button=>button.onclick=()=>submitConfirmation(button.dataset.confirmId,button.dataset.decisionChoice));}
  state.highlightConfirmation=null;
}

async function submitConfirmation(itemId,choice){
  const item=state.agentWorkspace?.confirmations?.items?.find(x=>x.id===itemId);if(!item?.decision)return;
  if(item.decision.method==='NAVIGATE'){state.highlightDocument=item.source_id;setView(item.decision.navigation_view||'documents');await loadDocuments();return}
  const rationale=document.querySelector(`[data-confirm-rationale="${CSS.escape(itemId)}"]`)?.value.trim()||'',evidence=document.querySelector(`[data-confirm-evidence="${CSS.escape(itemId)}"]`)?.value.trim()||'',amount=Number(document.querySelector(`[data-confirm-amount="${CSS.escape(itemId)}"]`)?.value||item.amount?.value||0);
  if(['procurement_request','vendor_bank_change'].includes(item.source_type)&&rationale.length<8)return toast('采购及账户复核请填写至少8个字的决定依据');
  if(rationale.length<4)return toast('请填写至少4个字的决定依据');
  const independentActor=document.querySelector(`[data-confirm-actor="${CSS.escape(itemId)}"]`)?.value.trim()||'';
  if(['procurement_request','vendor_bank_change'].includes(item.source_type)&&!independentActor)return toast('请填写与申请人不同的独立确认人');
  const body={...(item.decision.id_fields||{}),decision:choice,actor:independentActor||'财务工作台用户',rationale,evidence:evidence?[evidence]:[]};
  if(item.source_type==='vendor_bank_change'){body.verification_method=document.querySelector(`[data-confirm-verification-method="${CSS.escape(itemId)}"]`)?.value||'';body.verification_reference=document.querySelector(`[data-confirm-verification-reference="${CSS.escape(itemId)}"]`)?.value.trim()||'';if(choice==='批准'&&body.verification_reference.length<6)return toast('请记录独立核验的联系人、证明编号或线下记录引用')}
  if(item.source_type==='expense_claim')body.approved_amount=amount;
  if(item.source_type==='purchase_acceptance'){body.accepted_amount=amount;body.note=rationale;if(!evidence&&choice!=='退回整改')return toast('确认验收前请填写至少一项交付证据')}
  try{const r=await fetch(item.decision.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw new Error(data.error);toast(`${item.title} 已记录“${choice}”并保留审计依据`);state.businessFlows=null;await loadAgentWorkspace(true);if(state.view==='flows')await loadBusinessFlows()}catch(error){toast(error.message||'决定保存失败')}
}

async function loadDocuments(){try{const r=await fetch('/api/inbox?limit=200'),data=await r.json();if(!r.ok)throw new Error(data.error);state.documents=data.documents||[];state.documentEntities=data.entities||[];const uploadEntity=el('document-upload-entity'),current=uploadEntity?.value||'';if(uploadEntity){uploadEntity.innerHTML='<option value="">上传时选择主体（可稍后确认）</option>'+state.documentEntities.map(entity=>`<option value="${safe(entity.id)}">${safe(entity.name)} · ${safe(entity.id)}</option>`).join('');uploadEntity.value=state.documentEntities.some(x=>x.id===current)?current:''}renderDocuments()}catch(error){toast(error.message||'资料收件箱读取失败')}}
const documentTypeOptions={finance_package:'综合财务资料包',settlement:'平台/渠道结算单',settlement_reconciliation_evidence:'收入结算核对底稿',bank_statement:'银行 Excel/CSV 流水',bank_statement_document:'银行 PDF/图片对账单',invoice_register:'发票清单',invoice_document:'单张发票',purchase:'采购/费用/验收资料',payroll:'工资薪酬资料',planning:'预算与预测',opening_balance:'期初余额/科目余额表',contract_commercial:'合同商业条款',acceptance_evidence:'交付/验收证据'};
function recognitionPreview(document){const recognition=document.recognition||{},records=recognition.records||[],kind=document.classification?.document_type;if(!records.length)return'';if(kind==='bank_statement_document'){const confirmed=(recognition.corrections||[]).some(x=>x.confirmed_against_original);return`<div class="document-preview"><strong>识别候选 · ${confirmed?'已记录原件核对':'对照原件后才能入台账'}</strong><small>下方预览前 20 条；“确认”代表你已逐页核对全部 ${records.length} 条，不只是当前预览。</small>${records.slice(0,20).map((row,index)=>`<div class="document-preview-row"><span>${safe(row.transaction_date||'日期待补')}</span><input data-bank-field="${safe(document.id)}:${index}:transaction_id" value="${safe(row.transaction_id)}" placeholder="流水号"/><input data-bank-field="${safe(document.id)}:${index}:counterparty" value="${safe(row.counterparty)}" placeholder="交易对手"/><select data-bank-field="${safe(document.id)}:${index}:direction"><option ${row.direction==='收入'?'selected':''}>收入</option><option ${row.direction==='支出'?'selected':''}>支出</option><option ${row.direction==='待确认'?'selected':''}>待确认</option></select><input data-bank-field="${safe(document.id)}:${index}:currency" value="${safe(row.currency)}" placeholder="币种"/><input data-bank-field="${safe(document.id)}:${index}:amount" type="number" step="0.01" value="${safe(row.amount)}" placeholder="金额"/></div>`).join('')}<div class="document-preview-actions"><input data-correction-note="${safe(document.id)}" placeholder="核对依据，例如：已逐页对照原银行对账单"/><button class="button ghost" data-confirm-extraction="${safe(document.id)}">${confirmed?'重新确认':'确认已核全部原件'}</button></div></div>`}if(kind==='invoice_document')return`<div class="document-preview"><strong>发票识别候选 · 尚未完成官方查验</strong><div class="document-preview-summary">${records.slice(0,3).map(row=>`${safe(row.invoice_number||'号码待补')} · ${safe(row.seller_name)} · ${fmt(row.total_amount,'')}`).join('<br>')}</div><div class="document-preview-actions"><input data-correction-note="${safe(document.id)}" placeholder="已对照原票核对关键字段"/><button class="button ghost" data-confirm-extraction="${safe(document.id)}">确认已核原票</button></div></div>`;return''}
function evidenceLinkControls(document){const kind=document.classification?.document_type,scope=document.entity_scope||{};if(!['acceptance_evidence','contract_commercial','settlement_reconciliation_evidence'].includes(kind)||!document.recognition)return'';const targetType=kind==='settlement_reconciliation_evidence'?'settlement':'purchase',targets=(targetType==='settlement'?(state.payload?.records||[]):(state.procurement?.records||[])).filter(row=>row.entity_id===scope.entity_id);if(!state.hasPersistentData)return`<div class="document-link-controls"><span>示例模式只演示关系；切换到公司数据后才能建立可审计证据链接。</span></div>`;return`<div class="document-link-controls" data-target-type="${targetType}"><select data-evidence-target="${safe(document.id)}"><option value="">${targetType==='settlement'?'选择同主体收入结算记录':'选择同主体采购/验收记录'}</option>${targets.map(row=>`<option value="${safe(row.id)}">${targetType==='settlement'?`${safe(row.period)} · ${safe(row.game)} · ${safe(row.channel)}`:`${safe(row.po_number||row.id)} · ${safe(row.vendor)} · ${safe(row.item)}`}</option>`).join('')}</select><input data-evidence-note="${safe(document.id)}" placeholder="说明这份资料核对了什么"/><button class="button ghost" data-link-evidence="${safe(document.id)}" ${targets.length?'':'disabled'}>关联证据</button></div>`}
