loadTaxFilingAssist=async function(){if(!state.opsPeriod||!state.hasPersistentData)return;if(state.opsEntityId!=='cn_studio'){state.taxFilingAssist=null;renderTaxFilingAssist(null);return}try{const r=await fetch(`/api/tax-filing-assist?entity_id=${encodeURIComponent(state.opsEntityId)}&period=${encodeURIComponent(state.opsPeriod)}`),data=await r.json();if(!r.ok)throw new Error(data.error);state.taxFilingAssist=data;renderTaxFilingAssist(data)}catch(e){toast(e.message||'申报契约读取失败')}};
