function parseQuoteLines(value,currency){return String(value||'').split(/\n+/).map(line=>{const [vendor,amount,evidence='']=line.split(/[，,]/).map(x=>x.trim());return{vendor,amount:Number(amount||0),currency,evidence}}).filter(x=>x.vendor&&x.amount>0)}
async function openVendorBankChangeForm(){const entityId=state.opsEntityId||defaultOpsEntityId(),entity=opsEntities().find(item=>item.id===entityId);if(!entityId)return toast('请先选择供应商账户所属法律主体');let accounts=[];if(state.hasPersistentData){try{const response=await fetch(`/api/vendor-bank-accounts?entity_id=${encodeURIComponent(entityId)}`),data=await response.json();if(response.ok)accounts=data.accounts||[]}catch(error){toast('现有供应商账户读取失败')}}openFlowModal('供应商收款账户','双人复核',`<div class="form-grid"><label>法律主体<input value="${safe(entity?.name||entityId)} · ${safe(entityId)}" disabled /></label><label>申请类型<select id="vendor-bank-change-type"><option>新增</option><option>变更</option></select></label><label>供应商名称<input id="vendor-bank-vendor" /></label><label>收款户名<input id="vendor-bank-beneficiary" /></label><label>开户银行<input id="vendor-bank-name" /></label><label>银行国家/地区<input id="vendor-bank-country" placeholder="CN、SG、US 等" /></label><label>币种<select id="vendor-bank-currency">${currencyOptions(entity?.functional_currency||'CNY')}</select></label><label>完整账号 / IBAN<input id="vendor-bank-account" autocomplete="off" /></label><label>SWIFT / BIC<input id="vendor-bank-swift" /></label><label class="wide">被替换的已批准账户<select id="vendor-bank-previous"><option value="">新增时留空</option>${accounts.map(item=>`<option value="${safe(item.id)}">${safe(item.vendor)} · ${safe(item.currency)} · ${safe(item.account_masked)}</option>`).join('')}</select></label><label class="wide">证据（分号分隔，至少两类）<textarea id="vendor-bank-evidence" placeholder="供应商盖章账户函；主数据联系人；银行证明"></textarea></label><div class="profile-gap wide"><strong>完整账号不会写入财务台账</strong><span>系统只保存不可逆指纹和尾号。另一人必须通过主数据联系人回拨、银行证明或线下确认，批准后付款申请才能引用。</span></div></div>`,{kind:'vendor_bank_change',entityId})}
function openProcurementRequestForm(){const entityId=state.opsEntityId||defaultOpsEntityId(),entity=opsEntities().find(item=>item.id===entityId),context={entityId,functionalCurrency:entity?.functional_currency||'CNY'};if(!context.entityId)return toast('请先选择采购申请所属法律主体');const period=state.opsPeriod||new Date().toISOString().slice(0,7),needed=new Date(Date.now()+30*86400000).toISOString().slice(0,10);openFlowModal('新建采购申请','预算与寻源',`<div class="form-grid"><label>法律主体<input value="${safe(entity?.name||entityId)} · ${safe(entityId)}" disabled /></label><label>游戏/项目<input id="proc-request-project" /></label><label>采购类目<input id="proc-request-category" placeholder="素材制作、投放、云服务等" /></label><label class="wide">需求说明<textarea id="proc-request-description" placeholder="说明买什么、为什么需要、主要交付物"></textarea></label><label>预算期间<input id="proc-request-period" value="${safe(period)}" /></label><label>期望交付日<input id="proc-request-needed" type="date" value="${needed}" /></label><label>申请金额<input id="proc-request-amount" type="number" min="0.01" step="0.01" /></label><label>币种<select id="proc-request-currency">${currencyOptions(context.functionalCurrency)}</select></label><label>采购方式<select id="proc-request-method"><option>竞争比价</option><option>框架协议</option><option>单一来源</option><option>平台直采</option></select></label><label>拟选供应商<input id="proc-request-vendor" /></label><label class="wide">报价（每行：供应商,金额,证据引用）<textarea id="proc-request-quotes" placeholder="供应商A,50000,报价单A\n供应商B,56000,报价单B\n供应商C,61000,报价单C"></textarea></label><label class="wide">选择理由（非最低价中选必填）<textarea id="proc-request-selection"></textarea></label><label>框架编号/价格表<input id="proc-request-framework" /></label><label>寻源例外原因<input id="proc-request-sourcing-exception" placeholder="少于三方或单一来源时填写" /></label><label class="wide">预算例外原因<input id="proc-request-budget-exception" placeholder="无预算或超预算时填写；提交后仍需独立审批" /></label><label class="wide">证据（分号分隔）<textarea id="proc-request-evidence" placeholder="需求说明；报价记录；框架价格表；历史价对比"></textarea></label><div class="profile-gap wide"><strong>Agent 先查同主体、项目、类目、期间和币种预算</strong><span>待批准和已批准申请会占用预算。少于三方、非最低价、单一来源和超预算不会静默放行。</span></div></div>`,{kind:'procurement_request',entityId:context.entityId})}
const submitFlowActionBeforeProcurementRequest=submitFlowAction;
submitFlowAction=async function(){const action=state.flowAction;if(action?.kind!=='procurement_request')return submitFlowActionBeforeProcurementRequest();if(!state.hasPersistentData)return toast('示例数据仅展示流程；导入正式预算后才能提交采购申请');const currency=el('proc-request-currency').value,body={entity_id:action.entityId,project:el('proc-request-project').value.trim(),category:el('proc-request-category').value.trim(),description:el('proc-request-description').value.trim(),period:el('proc-request-period').value.trim(),needed_by:el('proc-request-needed').value,amount:Number(el('proc-request-amount').value),currency,sourcing_method:el('proc-request-method').value,selected_vendor:el('proc-request-vendor').value.trim(),quotes:parseQuoteLines(el('proc-request-quotes').value,currency),selection_rationale:el('proc-request-selection').value.trim(),framework_reference:el('proc-request-framework').value.trim(),sourcing_exception_reason:el('proc-request-sourcing-exception').value.trim(),budget_exception_reason:el('proc-request-budget-exception').value.trim(),evidence:evidenceList(el('proc-request-evidence').value),actor:'财务工作台用户',idempotency_key:action.idempotencyKey};try{const response=await fetch('/api/procurement-request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await response.json();if(!response.ok)throw new Error(data.error);closeFlowModal();await loadAgentWorkspace(true);toast(data.request.status==='阻塞'?`采购申请已记录，但有 ${data.request.blockers.length} 项需补齐`:'采购申请已进入独立审批并占用预算')}catch(error){toast(error.message||'采购申请提交失败')}};
