function openCollectionForm(settlementId){const item=(state.businessFlows?.receivables?.rows||[]).find(row=>row.id===settlementId);if(!item)return toast('找不到应收记录');if(!el('flow-entity')?.value)return toast('全球管理汇总只读；请先选择应收所属法律主体');const today=new Date().toISOString().slice(0,10);openFlowModal('记录回款跟进','应收催收',`<div class="form-grid"><label>应收对象<input value="${safe(item.game||'游戏')} · ${safe(item.channel||'渠道')}" disabled /></label><label>当前未回款<input value="${fmt(item.outstanding,item.currency)}" disabled /></label><label>动作类型<select id="flow-collection-type"><option>跟进记录</option><option>回款承诺</option><option>争议登记</option><option>争议解除</option></select></label><label>催收责任人<input id="flow-collection-owner" value="${safe(item.collection_owner||'')}" placeholder="内部负责人" /></label><label>跟进日期<input id="flow-collection-date" type="date" value="${today}" /></label><label>承诺回款日<input id="flow-collection-promise-date" type="date" value="${safe(item.promised_date||'')}" /></label><label>承诺金额<input id="flow-collection-promise-amount" type="number" min="0.01" step="0.01" value="${Number(item.promised_amount||item.outstanding||0)}" /></label><label>争议原因<input id="flow-collection-dispute" value="${safe(item.dispute_reason||'')}" placeholder="仅争议登记必填" /></label><label class="wide">本次联系事实 / 处理依据<textarea id="flow-collection-note" placeholder="例如：渠道邮件确认2月28日前支付；对账差异待运营补流水明细"></textarea></label><div class="profile-gap wide"><strong>不会自动发消息或改应收账</strong><span>新承诺会追加留痕；现金计划单列“含承诺情景”，不会静默覆盖基准预测。</span></div></div>`,{kind:'collection',settlementId})}
const renderBusinessFlowsBeforeCollections=renderBusinessFlows;
renderBusinessFlows=function(){const result=renderBusinessFlowsBeforeCollections(),f=state.businessFlows,rec=f?.receivables||{rows:[]},editable=Boolean(el('flow-entity')?.value);el('receivable-list').innerHTML=rec.rows.map(x=>{const details=[x.due_date_basis,x.collection_owner?`责任人 ${x.collection_owner}`:'',x.promised_date?`承诺 ${x.promised_date} · ${fmt(x.promised_amount,x.currency)}`:'',x.dispute_reason?`争议：${x.dispute_reason}`:'',...(x.anomalies||[])].filter(Boolean).join('；');const actions=x.outstanding>0?`${editable?`<button class="text-button" data-flow-followup="${safe(x.id)}">记录跟进</button>`:''}<button class="text-button" data-flow-collect="${safe(x.id)}">查看可核销流水</button>`:'';return flowRow({title:`${x.game||'游戏'} · ${x.channel||'渠道'}`,meta:`${x.period} · 到期 ${x.due_date||'待配置'} · ${x.collection_status||'未跟进'}`,amount:x.outstanding,currency:x.currency,status:x.promise_missed?'承诺逾期':x.disputed?'争议中':x.status,detail:details,action:actions})}).join('')||'<div class="empty-state">暂无应收记录</div>';el('receivable-list').querySelectorAll('[data-flow-followup]').forEach(button=>button.onclick=()=>openCollectionForm(button.dataset.flowFollowup));el('receivable-list').querySelectorAll('[data-flow-collect]').forEach(button=>button.onclick=()=>{const bank=(f.bank_transactions||[]).find(x=>x.direction==='收入'&&x.suggested_match?.target_id===button.dataset.flowCollect);if(bank)openAllocationForm(bank.id,'receivable',button.dataset.flowCollect);else toast('暂未找到指向该应收的银行流水，请先导入或认领银行对账单')});return result};
const submitFlowActionBeforeCollections=submitFlowAction;
submitFlowAction=async function(){const action=state.flowAction;if(action?.kind!=='collection')return submitFlowActionBeforeCollections();if(!state.hasPersistentData)return toast('演示数据仅展示催收流程；导入正式台账后才能记录');const body={entity_id:el('flow-entity')?.value||'',settlement_id:action.settlementId,action_type:el('flow-collection-type').value,owner:el('flow-collection-owner').value.trim(),action_date:el('flow-collection-date').value,promised_date:el('flow-collection-promise-date').value,promised_amount:Number(el('flow-collection-promise-amount').value||0),dispute_reason:el('flow-collection-dispute').value.trim(),note:el('flow-collection-note').value.trim(),actor:'财务工作台用户',idempotency_key:action.idempotencyKey};try{const response=await fetch('/api/collection-action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await response.json();if(!response.ok)throw new Error(data.error);closeFlowModal();state.businessFlows=null;state.planning=null;await loadBusinessFlows();await loadPlanning();await loadAgentWorkspace(true);toast(data.idempotent_replay?'网络重试已返回原跟进记录':'已记录跟进，并更新承诺回款情景')}catch(error){toast(error.message||'催收记录提交失败')}};
const renderBusinessFlowsBeforePriority=renderBusinessFlows;renderBusinessFlows=function(){const result=renderBusinessFlowsBeforePriority(),f=state.businessFlows,rec=f?.receivables||{rows:[]},editable=Boolean(el('flow-entity')?.value),rows=[...(rec.rows||[])].sort((a,b)=>(b.collection_priority_score||0)-(a.collection_priority_score||0)||(a.collection_priority_rank||999)-(b.collection_priority_rank||999));el('receivable-list').innerHTML=rows.map(x=>{const details=[`${x.collection_priority_label||'待跟进'} · ${x.collection_priority_reason||''}`,x.due_date_basis,x.collection_owner?`责任人 ${x.collection_owner}`:'',x.promised_date?`承诺 ${x.promised_date} · ${fmt(x.promised_amount,x.currency)}`:'',x.effective_promised_amount?`有效承诺情景后仍有 ${fmt(x.promise_scenario_outstanding,x.currency)}`:'',x.dispute_reason?`争议：${x.dispute_reason}`:'',...(x.anomalies||[])].filter(Boolean).join('；');const actions=x.outstanding>0?`${editable?`<button class="text-button" data-flow-followup="${safe(x.id)}">记录跟进</button>`:''}<button class="text-button" data-flow-collect="${safe(x.id)}">查看可核销流水</button>`:'';return flowRow({title:`${x.game||'游戏'} · ${x.channel||'渠道'} · #${x.collection_priority_rank||'—'}`,meta:`${x.period} · 到期 ${x.due_date||'待配置'} · ${x.collection_status||'未跟进'}`,amount:x.outstanding,currency:x.currency,status:x.collection_priority_label||x.status,detail:details,action:actions})}).join('')||'<div class="empty-state">暂无应收记录</div>';el('receivable-list').querySelectorAll('[data-flow-followup]').forEach(button=>button.onclick=()=>openCollectionForm(button.dataset.flowFollowup));el('receivable-list').querySelectorAll('[data-flow-collect]').forEach(button=>button.onclick=()=>{const bank=(f.bank_transactions||[]).find(x=>x.direction==='收入'&&x.suggested_match?.target_id===button.dataset.flowCollect);if(bank)openAllocationForm(bank.id,'receivable',button.dataset.flowCollect);else toast('暂未找到指向该应收的银行流水，请先导入或认领银行对账单')});return result};
const renderPlanningBeforeCollections=renderPlanning;
renderPlanning=function(){renderPlanningBeforeCollections();const p=state.planning;if(!p)return;const currency=p.functional_currency||'CNY',opening=p.opening_cash??p.opening_cash_cny,last=p.forecast[p.forecast.length-1]||{},runway=p.runway_months==null?'未触发':`${p.runway_months}个月`;el('planning-metrics').innerHTML=[['预测起点现金',opening==null?'待补':fmt(opening,currency),p.as_of_period],['现金跑道',runway,p.buffer_breach_period?`缓冲线 ${p.buffer_breach_period} 跌破`:'未跌破缓冲线'],['承诺回款情景',fmt(p.collection_commitment_total||0,currency),`${(p.missed_collection_commitments||[]).length} 笔承诺已过期`],['预测期末现金',last.ending_cash==null?'待补':fmt(last.ending_cash,currency),last.ending_cash_with_commitments!=null&&p.collection_commitment_total?`含有效承诺 ${fmt(last.ending_cash_with_commitments,currency)}`:`${p.forecast.length}个月后`]].map(x=>`<div class="metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="foot">${x[2]}</div></div>`).join('');const scale=Math.max(1,...p.forecast.flatMap(x=>[x.inflows,x.outflows,x.collection_commitments||0,Math.abs(x.ending_cash_with_commitments||x.ending_cash||0)]));el('cash-forecast').innerHTML=p.forecast.map(x=>`<div class="cash-row"><span>${x.period}</span><div class="cash-bars"><i class="inflow" style="width:${Math.max(1,x.inflows/scale*100)}%" title="计划流入 ${fmt(x.inflows,currency)}"></i>${x.collection_commitments?`<i class="collection" style="width:${Math.max(1,x.collection_commitments/scale*100)}%" title="承诺回款情景 ${fmt(x.collection_commitments,currency)}"></i>`:''}<i class="outflow" style="width:${Math.max(1,x.outflows/scale*100)}%" title="计划流出 ${fmt(x.outflows,currency)}"></i></div><strong class="${x.ending_cash!=null&&x.ending_cash<(p.minimum_buffer||0)?'negative':''}" title="${x.collection_commitments?'右侧为基准值；承诺回款另作情景，不直接改基准':''}">${x.ending_cash==null?'待补期初现金':fmt(x.ending_cash,currency)}</strong></div>`).join('')};
