const opsEntityChangeBeforeProcurementWorkflow=el('ops-entity').onchange;
el('ops-entity').onchange=async event=>{await opsEntityChangeBeforeProcurementWorkflow(event);state.procurementWorkflow=null;if(state.view==='procurement')await loadProcurementWorkflow(true)};
async function bootstrap(){await loadBoxContext();const isGame=state.boxContext?.product?.workbench?.profile==='game_studio',requested=new URLSearchParams(window.location.search).get('view'),allowed=isGame?['agent','box-builder','tax-workspace','confirmations','pipeline-launch','connector-onboarding','pipeline-control','bp','documents','settings','overview','revenue-close','flows','shadow-close']:['box-home','box-builder','tax-workspace','pipeline-launch','connector-onboarding','pipeline-control','documents'],initial=allowed.includes(requested)?requested:(isGame?'agent':'box-home');setView(initial);if(isGame&&!['box-builder','connector-onboarding','tax-workspace'].includes(initial)){await loadCompanyContext();await loadWorkspace();if(initial==='revenue-close'&&state.hasPersistentData)await loadRevenueClose(true);if(initial==='flows'&&state.hasPersistentData)await loadBusinessFlows();if(initial==='shadow-close')await loadShadowClose();await loadAgentWorkspace(true);await loadDocuments();if(initial==='bp')renderBp()}else{updateCompanyContext(null);if(initial==='documents')await loadDocuments()}}
function renderGameCollections(portfolio){const summary=portfolio?.summary||{},summaryNode=el('game-collection-summary'),table=el('game-collection-table');if(!summaryNode||!table)return;const entities=new Map(opsEntities().map(item=>[item.id,item.name]));summaryNode.innerHTML=`<strong>${summary.multi_entity_game_count||0} 款游戏覆盖多个主体</strong><span>${(summary.currencies||[]).join(' / ')||'待补币种'} 分币种展示，不直接相加。${safe(portfolio?.guardrail||'')}</span>`;table.innerHTML=(portfolio?.rows||[]).map(row=>{const rate=row.collection_rate==null?'—':pct(row.collection_rate),tone=row.outstanding<=.01?'ok':row.overdue_count?'error':'pending',local=(row.local_games||[]).join(' / ')||row.management_game_name;return`<tr><td><strong>${safe(row.management_game_name)}</strong><br><small>${safe(local)} · ${row.receivable_count||0} 笔应收</small></td><td><strong>${safe(entities.get(row.entity_id)||row.entity_id)}</strong><br><small>${safe(row.entity_id)}</small></td><td>${safe(row.currency)}</td><td class="numeric">${fmt(row.receivable,row.currency)}</td><td class="numeric">${fmt(row.received,row.currency)}</td><td class="numeric">${fmt(row.outstanding,row.currency)}</td><td><div class="collection-progress"><span style="width:${Math.max(0,Math.min(100,Number(row.collection_rate||0)*100))}%"></span></div><small>${rate}${row.overdue_count?` · ${row.overdue_count}笔逾期`:''}</small></td><td><button class="text-button" data-game-collection-entity="${safe(row.entity_id)}" ${row.entity_id==='legacy_unassigned'?'disabled':''}>${row.outstanding<=.01?'查看核销':'进入主体回款'} →</button><br><span class="status ${tone}">${row.outstanding<=.01?'已回款':row.overdue_count?'需跟进':'未结清'}</span></td></tr>`}).join('')||'<tr><td colspan="8">导入已批准的渠道应收后，这里会按同一游戏、主体和币种自动组织。</td></tr>';table.querySelectorAll('[data-game-collection-entity]').forEach(button=>button.onclick=async()=>{const entityId=button.dataset.gameCollectionEntity;state.opsEntityId=entityId;setView('flows');await loadBusinessFlows();const select=el('flow-entity');if(select){select.value=entityId;if(state.hasPersistentData){state.businessFlows=null;await loadBusinessFlows()}}})}
const renderGameCollectionsWithoutDemoDrill=renderGameCollections;renderGameCollections=function(portfolio){const result=renderGameCollectionsWithoutDemoDrill(portfolio);if(state.hasPersistentData===false)el('game-collection-table')?.querySelectorAll('[data-game-collection-entity]').forEach(button=>button.onclick=async()=>{const scenario=button.dataset.gameCollectionEntity==='sg_publisher'?'overseas':'domestic';el('sample-scenario').value=scenario;await loadSample(scenario);setView('flows')});return result};
renderGameCollections=function(portfolio){const summary=portfolio?.summary||{},summaryNode=el('game-collection-summary'),table=el('game-collection-table');if(!summaryNode||!table)return;const entities=new Map(opsEntities().map(item=>[item.id,item.name]));summaryNode.innerHTML=`<strong>${summary.multi_entity_game_count||0} 款游戏覆盖多个主体</strong><span>${summary.priority_entity_currency_scope_count||0} 个主体/币种范围需跟进 · ${summary.valid_promise_count||0} 个有效承诺 · ${summary.missed_promise_count||0} 个承诺逾期。承诺只是情景，不冲减应收。</span>`;table.innerHTML=(portfolio?.rows||[]).map(row=>{const tone=['P0','P1'].includes(row.collection_priority)?'error':row.collection_priority==='P2'?'pending':'ok',local=(row.local_games||[]).join(' / ')||row.management_game_name,promise=Number(row.effective_promised_amount||0),priorityItems=(row.priority_items||[]).map(item=>`${safe(item.channel||'渠道')} · ${safe(item.collection_priority_label)}${item.days_overdue?` · 逾期${item.days_overdue}天`:''}`).join('<br>');return`<tr><td><strong>${safe(row.management_game_name)}</strong><br><small>${safe(local)} · ${row.receivable_count||0} 笔应收</small></td><td><strong>${safe(entities.get(row.entity_id)||row.entity_id)}</strong><br><small>${safe(row.entity_id)} · ${safe(row.currency)}</small></td><td class="numeric">${fmt(row.receivable,row.currency)}<br><small>已回 ${fmt(row.received,row.currency)}</small></td><td class="numeric">${fmt(row.outstanding,row.currency)}<br><small>回款率 ${row.collection_rate==null?'—':pct(row.collection_rate)}</small></td><td>${promise?`<strong>${fmt(promise,row.currency)}</strong><br><small>若按时到账，仍有 ${fmt(row.promise_scenario_outstanding,row.currency)}</small>`:'<strong>尚无有效承诺</strong><br><small>不对基准现金预测做乐观调整</small>'}</td><td><span class="status ${tone}">${safe(row.collection_priority_label)}</span><br><small>${safe(row.collection_priority_reason)}</small>${priorityItems?`<div class="collection-priority-items">${priorityItems}</div>`:''}</td><td><strong>${safe(row.recommended_collection_action)}</strong><br><button class="text-button" data-game-collection-entity="${safe(row.entity_id)}" ${row.entity_id==='legacy_unassigned'?'disabled':''}>${row.outstanding<=.01?'查看核销':'进入主体催收'} →</button></td></tr>`}).join('')||'<tr><td colspan="7">导入已批准的渠道应收后，这里会按同一游戏、主体和币种自动排出催收优先级。</td></tr>';table.querySelectorAll('[data-game-collection-entity]').forEach(button=>button.onclick=async()=>{const entityId=button.dataset.gameCollectionEntity;if(state.hasPersistentData===false){el('sample-scenario').value=entityId==='sg_publisher'?'overseas':'domestic';await loadSample(el('sample-scenario').value);setView('flows');return}state.opsEntityId=entityId;setView('flows');await loadBusinessFlows();const select=el('flow-entity');if(select){select.value=entityId;state.businessFlows=null;await loadBusinessFlows()}})};
const renderBpWithoutGameCollections=renderBp;renderBp=function(){const result=renderBpWithoutGameCollections();renderGameCollections(state.bp?.game_collection_portfolio);return result};
function renderProjectProcurementCosts(view){const guardrail=el('project-cost-guardrail'),table=el('project-cost-table');if(!guardrail||!table)return;const rows=view?.rows||[],entities=new Map(opsEntities().map(item=>[item.id,item.name])),projects=new Map((state.bp?.projects||[]).map(item=>[item.project_code,item.project_name]));guardrail.innerHTML=`<strong>成本确认边界：</strong>${safe((view?.guardrails||[]).slice(1).join(' '))}`;table.innerHTML=rows.map(row=>{const tone=row.control_status==='链路完整'?'ok':row.issues?.length?'error':'pending',issues=(row.issues||[]).join('；'),categories=(row.categories||[]).join(' / ');return`<tr><td><strong>${safe(projects.get(row.project)||row.project)}</strong><br><small>${safe(row.project)}${categories?` · ${safe(categories)}`:''}</small></td><td><strong>${safe(entities.get(row.entity_id)||row.entity_id||'主体待补')}</strong><br><small>${safe(row.entity_id||'未归属')} · ${safe(row.currency)}</small></td><td class="numeric">${fmt(row.budget_amount,row.currency)}</td><td class="numeric">${fmt(row.approved_request_amount,row.currency)}</td><td class="numeric">${fmt(row.committed_order_amount,row.currency)}<br><small>未履约 ${fmt(row.open_commitment,row.currency)}</small></td><td class="numeric">${fmt(row.delivered_pending_acceptance,row.currency)}</td><td class="numeric">${fmt(row.accepted_actual,row.currency)}</td><td class="numeric">${fmt(row.pending_invoice,row.currency)}</td><td class="numeric">${fmt(row.pending_payment,row.currency)}<br><small>已付 ${fmt(row.paid_amount,row.currency)}，不冲成本</small></td><td class="numeric ${row.budget_remaining<0?'negative':''}">${fmt(row.budget_remaining,row.currency)}</td><td><span class="status ${tone}">${safe(row.control_status)}</span>${issues?`<br><small>${safe(issues)}</small>`:''}</td></tr>`}).join('')||'<tr><td colspan="11">本期尚无同时具备明确项目、主体和币种的采购成本链路。</td></tr>'}
function renderProjectLaborCosts(view){const guardrail=el('project-labor-guardrail'),table=el('project-labor-table');if(!guardrail||!table)return;const rows=view?.rows||[],entities=new Map(opsEntities().map(item=>[item.id,item.name])),projects=new Map((state.bp?.projects||[]).map(item=>[item.project_code,item.project_name]));guardrail.innerHTML=`<strong>隐私与判断边界：</strong>${safe((view?.guardrails||[]).slice(1).join(' '))}`;table.innerHTML=rows.map(row=>{const evidence=[...(row.evidence_types||[]),...(row.allocation_methods||[])].join(' · '),activities=(row.activity_types||[]).join(' / ');return`<tr><td><strong>${safe(projects.get(row.project)||row.project)}</strong><br><small>${safe(row.project)}</small></td><td><strong>${safe(entities.get(row.entity_id)||row.entity_id||'主体待补')}</strong><br><small>${safe(row.entity_id||'未归属')} · ${safe(row.currency)}</small></td><td class="numeric">${fmt(row.gross_salary,row.currency)}</td><td class="numeric">${fmt(row.employer_cost,row.currency)}</td><td class="numeric"><strong>${fmt(row.project_cost_candidate,row.currency)}</strong></td><td class="numeric">${fmt(row.employee_deductions,row.currency)}<br><small>不增加成本</small></td><td class="numeric">${fmt(row.withholding_tax,row.currency)}<br><small>不增加成本</small></td><td class="project-labor-evidence"><span class="status ${row.evidence_count?'ok':'error'}">${safe(row.control_status)}</span><br><small>${safe(evidence||'证据待补')} · ${row.allocation_record_count||0} 条分摊${row.evidenced_hours?` · ${row.evidenced_hours} 小时`:''}</small></td><td class="numeric">${fmt(row.research_cost_candidate,row.currency)}<br><small>${safe(activities||'活动性质待标注')}</small></td><td class="project-labor-boundary">${safe(row.research_treatment)}</td></tr>`}).join('')||'<tr><td colspan="10">本期尚无具备明确项目代码和工时/分摊证据的人力成本候选；未分配部分保留在公司公共成本。</td></tr>'}
function renderGamePrepaidCosts(view){const guardrail=el('prepaid-cost-guardrail'),table=el('prepaid-cost-table'),schedule=el('prepaid-release-table');if(!guardrail||!table||!schedule)return;const entities=new Map(opsEntities().map(item=>[item.id,item.name])),projects=new Map((state.bp?.projects||[]).map(item=>[item.project_code,item.project_name]));guardrail.innerHTML=`<strong>候选边界：</strong>${safe((view?.guardrails||[]).join(' '))}`;table.innerHTML=(view?.candidates||[]).map(row=>{const tone=row.issues?.length?'error':'pending',issues=(row.issues||[]).join('；');return`<tr><td><strong>${safe(row.cost_type)}</strong><br><small>${safe(projects.get(row.project)||row.project||'项目待补')} · ${safe(row.contract_reference||'合同待补')}</small></td><td><strong>${safe(entities.get(row.entity_id)||row.entity_id||'主体待补')}</strong><br><small>${safe(row.entity_id||'未归属')} · ${safe(row.currency)}</small></td><td>${safe(row.service_start||'待补')} → ${safe(row.service_end||'待补')}</td><td><strong>${safe(row.classification_candidate)}</strong><br><small>${safe(row.allocation_method||'政策待补')} · ${safe(row.policy_status)}</small></td><td class="numeric">${fmt(row.cost_basis_amount,row.currency)}</td><td class="numeric">${fmt(row.accepted_amount,row.currency)} / ${fmt(row.verified_invoice_amount,row.currency)}</td><td class="numeric">${fmt(row.paid_amount,row.currency)}<br><small>不决定资本化或费用化</small></td><td class="numeric"><strong>${fmt(row.current_period_release_candidate,row.currency)}</strong></td><td class="numeric">${fmt(row.unreleased_candidate_balance,row.currency)}</td><td class="prepaid-cost-boundary"><span class="status ${tone}">${safe(row.status)}</span><br><small>${safe(issues||row.accounting_boundary)}</small></td></tr>`}).join('')||'<tr><td colspan="10">尚无显式标记为游戏授权、IP license 或服务器/云资源的成本事项。</td></tr>';schedule.innerHTML=(view?.release_schedule||[]).map(row=>`<tr><td><strong>${safe(projects.get(row.project)||row.project)}</strong><br><small>${safe(row.cost_type)} · ${safe(row.classification)}</small></td><td>${safe(entities.get(row.entity_id)||row.entity_id)}<br><small>${safe(row.entity_id)} · ${safe(row.currency)}</small></td><td>${safe(row.period)}</td><td class="numeric">${fmt(row.planned_release,row.currency)}</td><td class="numeric ${row.release_candidate?'':'release-zero'}">${fmt(row.release_candidate,row.currency)}</td><td class="numeric">${fmt(row.unreleased_candidate_balance,row.currency)}</td><td><span class="status ${row.release_candidate?'ok':'error'}">${safe(row.status)}</span><br><small>${row.period_evidence_count||0} 项期间证据 · 未过账</small></td></tr>`).join('')||'<tr><td colspan="7">待合同服务期和已批准政策完整后生成期间释放表。</td></tr>'}
const renderBpWithoutProjectCosts=renderBp;renderBp=function(){const result=renderBpWithoutProjectCosts(),b=state.bp;if(!b)return result;renderProjectProcurementCosts(b.project_procurement_costs);const costComplete=(b.data_quality?.payroll_record_count||0)>0&&(b.data_quality?.purchase_record_count||0)>0;el('bp-project-table').innerHTML=(b.projects||[]).map(x=>`<tr><td><strong>${safe(x.project_name)}</strong><br><small>${safe(x.project_code)} · ${safe(x.stage)}</small></td><td class="numeric">${fmt(x.revenue,'CNY')}</td><td class="numeric">${fmt(x.procurement_actual||0,'CNY')}</td><td class="numeric">${fmt(x.direct_cost,'CNY')}</td><td class="numeric ${x.contribution<0?'negative':''}">${costComplete?fmt(x.contribution,'CNY'):'待补全'}</td><td class="numeric">${fmt(x.procurement_open_commitment||0,'CNY')}</td><td class="numeric ${x.committed_contribution<0?'negative':''}">${costComplete?fmt(x.committed_contribution,'CNY'):'待补全'}</td><td>${x.unconverted?.length?`<span class="status error">${x.unconverted.length}项待折算</span>`:x.evidence_count?`<span class="status ${costComplete?'ok':'pending'}">${costComplete?'可分析':'成本待补'}</span>`:'<span class="status pending">缺实际数</span>'}</td></tr>`).join('')||'<tr><td colspan="8">先建立项目，再导入结算、工资和采购。</td></tr>';return result};
const renderBpWithoutLaborCosts=renderBp;renderBp=function(){const result=renderBpWithoutLaborCosts(),b=state.bp;if(!b)return result;renderProjectLaborCosts(b.project_labor_costs);const costComplete=(b.data_quality?.payroll_record_count||0)>0&&(b.data_quality?.purchase_record_count||0)>0;el('bp-project-table').innerHTML=(b.projects||[]).map(x=>`<tr><td><strong>${safe(x.project_name)}</strong><br><small>${safe(x.project_code)} · ${safe(x.stage)}</small></td><td class="numeric">${fmt(x.revenue,'CNY')}</td><td class="numeric">${fmt(x.payroll||0,'CNY')}</td><td class="numeric">${fmt(x.procurement_actual||0,'CNY')}</td><td class="numeric">${fmt(x.direct_cost,'CNY')}</td><td class="numeric ${x.contribution<0?'negative':''}">${costComplete?fmt(x.contribution,'CNY'):'待补全'}</td><td class="numeric">${fmt(x.procurement_open_commitment||0,'CNY')}</td><td class="numeric ${x.committed_contribution<0?'negative':''}">${costComplete?fmt(x.committed_contribution,'CNY'):'待补全'}</td><td>${x.unconverted?.length?`<span class="status error">${x.unconverted.length}项待折算</span>`:x.evidence_count?`<span class="status ${costComplete?'ok':'pending'}">${costComplete?'可分析':'成本待补'}</span>`:'<span class="status pending">缺实际数</span>'}</td></tr>`).join('')||'<tr><td colspan="9">先建立项目，再导入结算、工资和采购。</td></tr>';return result};
